@Composable
fun SplashScreen(isBengali: Boolean, onTimeout: () -> Unit) {
    LaunchedEffect(Unit) {
        kotlinx.coroutines.delay(2500) // 2.5 seconds
        onTimeout()
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    colors = listOf(
                        DarkBg,
                        DarkSurface,
                        DarkBg
                    )
                )
            ),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center,
            modifier = Modifier.fillMaxHeight().padding(24.dp)
        ) {
            val infiniteTransition = rememberInfiniteTransition(label = "pulse")
            val scale by infiniteTransition.animateFloat(
                initialValue = 0.95f,
                targetValue = 1.05f,
                animationSpec = infiniteRepeatable(
                    animation = tween(1200, easing = FastOutSlowInEasing),
                    repeatMode = RepeatMode.Reverse
                ),
                label = "scale"
            )
            val alpha by infiniteTransition.animateFloat(
                initialValue = 0.85f,
                targetValue = 1.0f,
                animationSpec = infiniteRepeatable(
                    animation = tween(1200, easing = FastOutSlowInEasing),
                    repeatMode = RepeatMode.Reverse
                ),
                label = "alpha"
            )

            Box(
                modifier = Modifier
                    .scale(scale)
                    .alpha(alpha),
                contentAlignment = Alignment.Center
            ) {
                Box(
                    modifier = Modifier
                        .size(160.dp)
                        .background(
                            Brush.radialGradient(
                                colors = listOf(
                                    DarkAccentGold.copy(alpha = 0.15f),
                                    Color.Transparent
                                )
                            ),
                            shape = RoundedCornerShape(80.dp)
                        )
                )

                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    NikotLogo(
                        modifier = Modifier
                            .size(96.dp),
                        color = DarkAccentGold
                    )
                }
            }

            Spacer(modifier = Modifier.height(24.dp))

            Text(
                text = "NIKOT",
                color = DarkTextPrimary,
                fontSize = 38.sp,
                fontWeight = FontWeight.Black,
                style = androidx.compose.ui.text.TextStyle(
                    letterSpacing = 2.5.sp,
                    shadow = androidx.compose.ui.graphics.Shadow(
                        color = DarkAccentGold.copy(alpha = 0.3f),
                        blurRadius = 8f
                    )
                ),
                textAlign = TextAlign.Center
            )

            Spacer(modifier = Modifier.height(6.dp))
            Text(
                text = "PASSION IN CARE",
                color = DarkTextSecondary,
                fontSize = 12.sp,
                fontWeight = FontWeight.Bold,
                style = androidx.compose.ui.text.TextStyle(
                    letterSpacing = 3.sp
                ),
                textAlign = TextAlign.Center
            )
        }

        Box(
            modifier = Modifier
                .fillMaxSize()
                .navigationBarsPadding()
                .padding(bottom = 32.dp),
            contentAlignment = Alignment.BottomCenter
        ) {
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.Center
            ) {
                PoweredByRoFooter(isBengali = isBengali, badgeHeight = 20.dp)
            }
        }
    }
}

@Composable
fun PharmacyApp(viewModel: PharmacyViewModel) {
    val isLoggedIn by viewModel.isLoggedIn.collectAsState()
    val isBengali by viewModel.isBengali.collectAsState()
    val isDarkMode by viewModel.isDarkMode.collectAsState()
    val uploadedLogoBase64 by viewModel.uploadedLogoBase64.collectAsState()
    isDarkModeGlobal = isDarkMode

    var showSplash by remember { mutableStateOf(true) }

    CompositionLocalProvider(LocalUploadedLogo provides uploadedLogoBase64) {
        // Mobile viewport constraint container: max width 420dp
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(if (isDarkModeGlobal) Color.Black else Color(0xFFE2E8F0)),
            contentAlignment = Alignment.Center
        ) {
            Box(
                modifier = Modifier
                    .widthIn(max = 420.dp)
                    .fillMaxHeight()
                    .background(GlassBackgroundGradient)
            ) {
                Crossfade(
                    targetState = when {
                        showSplash -> "splash"
                        !isLoggedIn -> "login"
                        else -> "app"
                    },
                    animationSpec = tween(420, easing = FastOutSlowInEasing),
                    label = "appRoot"
                ) { route ->
                    when (route) {
                        "splash" -> SplashScreen(isBengali = isBengali, onTimeout = { showSplash = false })
                        "login" -> LoginScreen(viewModel, isBengali)
                        else -> LoggedInNavigator(viewModel, isBengali)
                    }
                }
            }
        }
    }
}

