    // Login states
    var username by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var isPasswordVisible by remember { mutableStateOf(false) }

    // Signup states
    var signupUsername by remember { mutableStateOf("") }
    var signupPharmacyName by remember { mutableStateOf("") }
    var signupAddress by remember { mutableStateOf("") }
    var signupPhone by remember { mutableStateOf("") }
    var signupOwnerName by remember { mutableStateOf("") }
    var signupPassword by remember { mutableStateOf("") }
    var isSignupPasswordVisible by remember { mutableStateOf(false) }
    var signupRole by remember { mutableStateOf("customer") } // "admin", "staff", "customer"
    val loginButtonInteractionSource = remember { MutableInteractionSource() }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(24.dp)
            .verticalScroll(rememberScrollState()),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Top
    ) {
        Spacer(modifier = Modifier.height(16.dp))

        // Quick Controls Header (Language, Theme & Server toggle)
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(bottom = 16.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            // Language selector button
            Card(
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(containerColor = GlassFillStrong),
                border = BorderStroke(1.dp, GlassBorder),
                modifier = Modifier.clickable { viewModel.toggleLanguage() }
            ) {
                Row(
                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Icon(
                        imageVector = Icons.Filled.Language,
                        contentDescription = "Language",
                        tint = DarkAccentGold,
                        modifier = Modifier.size(16.dp)
                    )
                    Spacer(modifier = Modifier.width(4.dp))
                    Text(
                        text = if (isBengali) "ENG" else "বাংলা",
                        color = DarkTextPrimary,
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            }

            // Theme switch button
            Card(
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(containerColor = GlassFillStrong),
                border = BorderStroke(1.dp, GlassBorder),
                modifier = Modifier.clickable { viewModel.toggleDarkMode() }
            ) {
                Row(
                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Icon(
                        imageVector = if (isDarkModeGlobal) Icons.Filled.LightMode else Icons.Filled.DarkMode,
                        contentDescription = "Theme",
                        tint = DarkAccentGold,
                        modifier = Modifier.size(16.dp)
                    )
                    Spacer(modifier = Modifier.width(4.dp))
                    Text(
                        text = if (isDarkModeGlobal) {
                            if (isBengali) "লাইট" else "Light"
                        } else {
                            if (isBengali) "ডার্ক" else "Dark"
                        },
                        color = DarkTextPrimary,
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        }

        Spacer(modifier = Modifier.height(12.dp))
        RoLogoHeader(height = 90.dp)
        Spacer(modifier = Modifier.height(16.dp))

        if (isSignUpMode) {
            Text(
                text = if (isBengali) "নতুন একাউন্ট রেজিস্ট্রেশন" else "New Account Registration",
                color = DarkTextPrimary,
                fontSize = 19.sp,
                fontWeight = FontWeight.Bold,
                modifier = Modifier.padding(bottom = 4.dp)
            )

            Text(
                text = if (isBengali) "প্রয়োজনীয় তথ্য দিয়ে আপনার একাউন্ট নিবন্ধন করুন" else "Register your account with required details",
                color = DarkTextSecondary,
                fontSize = 12.sp,
                textAlign = TextAlign.Center,
                modifier = Modifier.padding(bottom = 16.dp, start = 8.dp, end = 8.dp)
            )
        } else {
            Spacer(modifier = Modifier.height(12.dp))
        }

        // Conditional views based on isSignUpMode
        if (!isSignUpMode) {
            // Login Fields
            OutlinedTextField(
                value = username,
                onValueChange = {
                    username = it
                    errorMsg = ""
                },
                label = { Text(if (isBengali) "ইউজারনেম / ফার্মেসীর নাম / ব্যক্তির নাম" else "Username / Pharmacy Name / Person Name") },
                placeholder = { Text(if (isBengali) "ইউজারনেম, ফার্মেসীর নাম বা ব্যক্তির নাম দিন" else "Enter username, pharmacy name, or person name", color = DarkTextSecondary.copy(alpha = 0.5f), fontSize = 12.sp) },
                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 5.dp),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = DarkAccentRed,
                    unfocusedBorderColor = DarkTextSecondary,
                    focusedLabelColor = DarkAccentRed,
                    unfocusedLabelColor = DarkTextSecondary
                ),
                shape = RoundedCornerShape(12.dp)
            )

            OutlinedTextField(
                value = password,
                onValueChange = {
                    password = it
                    errorMsg = ""
                },
                label = { Text(if (isBengali) "পাসওয়ার্ড (Password)" else "Password") },
                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                visualTransformation = if (isPasswordVisible) VisualTransformation.None else PasswordVisualTransformation(),
                trailingIcon = {
                    IconButton(onClick = { isPasswordVisible = !isPasswordVisible }) {
                        Icon(
                            imageVector = if (isPasswordVisible) Icons.Default.Visibility else Icons.Default.VisibilityOff,
                            contentDescription = if (isPasswordVisible) "Hide password" else "Show password",
                            tint = DarkTextSecondary
                        )
                    }
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 5.dp),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = DarkAccentRed,
                    unfocusedBorderColor = DarkTextSecondary,
                    focusedLabelColor = DarkAccentRed,
                    unfocusedLabelColor = DarkTextSecondary
                ),
                shape = RoundedCornerShape(12.dp)
            )
        } else {
            // Signup Fields
            OutlinedTextField(
                value = signupOwnerName,
                onValueChange = { signupOwnerName = it },
                label = { Text(if (isBengali) "আপনার পূর্ণ নাম (Full Name)" else "Your Full Name") },
                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 4.dp),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = DarkAccentRed,
                    unfocusedBorderColor = DarkTextSecondary,
                    focusedLabelColor = DarkAccentRed,
                    unfocusedLabelColor = DarkTextSecondary
                ),
                shape = RoundedCornerShape(12.dp)
            )



            OutlinedTextField(
                value = signupUsername,
                onValueChange = { signupUsername = it },
                label = { Text(if (isBengali) "ইউজারনেম (Username - লগইন করার জন্য)" else "Username (For login)") },
                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 4.dp),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = DarkAccentRed,
                    unfocusedBorderColor = DarkTextSecondary,
                    focusedLabelColor = DarkAccentRed,
                    unfocusedLabelColor = DarkTextSecondary
                ),
                shape = RoundedCornerShape(12.dp)
            )

            OutlinedTextField(
                value = signupPhone,
                onValueChange = { signupPhone = it },
                label = { Text(if (isBengali) "মোবাইল নম্বর (Phone Number)" else "Phone Number") },
                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 4.dp),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = DarkAccentRed,
                    unfocusedBorderColor = DarkTextSecondary,
                    focusedLabelColor = DarkAccentRed,
                    unfocusedLabelColor = DarkTextSecondary
                ),
                shape = RoundedCornerShape(12.dp)
            )



            OutlinedTextField(
                value = signupPassword,
                onValueChange = { signupPassword = it },
                label = { Text(if (isBengali) "পাসওয়ার্ড (Password)" else "Password") },
                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                visualTransformation = if (isSignupPasswordVisible) VisualTransformation.None else PasswordVisualTransformation(),
                trailingIcon = {
                    IconButton(onClick = { isSignupPasswordVisible = !isSignupPasswordVisible }) {
                        Icon(
                            imageVector = if (isSignupPasswordVisible) Icons.Default.Visibility else Icons.Default.VisibilityOff,
                            contentDescription = if (isSignupPasswordVisible) "Hide password" else "Show password",
                            tint = DarkTextSecondary
                        )
                    }
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 4.dp),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = DarkAccentRed,
                    unfocusedBorderColor = DarkTextSecondary,
                    focusedLabelColor = DarkAccentRed,
                    unfocusedLabelColor = DarkTextSecondary
                ),
                shape = RoundedCornerShape(12.dp)
            )
        }

        if (errorMsg.isNotEmpty()) {
            Text(
                text = errorMsg,
                color = DarkAccentRed,
                fontSize = 13.sp,
                fontWeight = FontWeight.SemiBold,
                modifier = Modifier.padding(vertical = 8.dp),
                textAlign = TextAlign.Center
            )
        }

        Spacer(modifier = Modifier.height(14.dp))

        // Main Submit Action Button
        Button(
            onClick = {
                if (!isSignUpMode) {
                    val (loginSuccess, loginError) = viewModel.loginWithResult(username, password)
                    if (loginSuccess) {
                        errorMsg = ""
                    } else {
                        // Check if direct cloud query finds the user across devices
                        viewModel.loginAsync(username, password) { cloudOk, cloudErr ->
                            if (cloudOk) {
                                errorMsg = ""
                            } else {
                                errorMsg = if (cloudErr.isNotBlank()) cloudErr else (if (isBengali) "ভুল ইউজারনেম, ফার্মেসীর নাম বা ব্যক্তির নাম অথবা পাসওয়ার্ড!" else "Incorrect username, pharmacy name, person name, or password!")
                            }
                        }
                    }
                } else {
                    if (signupUsername.trim().isEmpty() || signupPassword.trim().isEmpty() || signupOwnerName.trim().isEmpty()) {
                        errorMsg = if (isBengali) "নাম, ইউজারনেম এবং পাসওয়ার্ড পূরণ করুন!" else "Please fill name, username and password!"
                    } else {
                        val chosenRole = if (signupRole == "merchant") "admin" else signupRole
                        val ok = viewModel.signUp(
                            username = signupUsername,
                            pharmName = signupPharmacyName,
                            addr = signupAddress,
                            ph = signupPhone,
                            ownName = signupOwnerName,
                            pass = signupPassword,
                            role = chosenRole
                        )
                        if (ok) {
                            errorMsg = ""
                        } else {
                            errorMsg = if (isBengali) "ইউজারনেম আগে থেকেই নিবন্ধিত!" else "Username is already registered!"
                        }
                    }
                }
            },
            modifier = Modifier
                .fillMaxWidth()
                .height(52.dp)
                .premiumShadow(radius = 10.dp, shape = RoundedCornerShape(16.dp), alpha = if (isDarkModeGlobal) 0.35f else 0.14f)
                .pressScale(loginButtonInteractionSource),
            interactionSource = loginButtonInteractionSource,
            colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed, contentColor = DarkAccentText),
            shape = RoundedCornerShape(16.dp)
        ) {
            Text(
                text = if (isSignUpMode) {
                    if (isBengali) "রেজিস্ট্রেশন সম্পন্ন করুন" else "Complete Registration"
                } else {
                    if (isBengali) "লগইন করুন" else "Log In"
                },
                fontWeight = FontWeight.Bold,
                fontSize = 15.sp,
                color = DarkAccentText
            )
        }

        Spacer(modifier = Modifier.height(14.dp))

        // Toggle text link below the button
        Text(
            text = if (isSignUpMode) {
                if (isBengali) "ইতিমধ্যে একাউন্ট আছে? লগইন করুন" else "Already have an account? Log In"
            } else {
                if (isBengali) "নতুন একাউন্ট খুলতে চান? এখানে ক্লিক করুন" else "Need an account? Sign Up Here"
            },
            color = DarkAccentGold,
            fontSize = 13.sp,
            fontWeight = FontWeight.Bold,
            modifier = Modifier
                .clickable {
                    isSignUpMode = !isSignUpMode
                    errorMsg = ""
                }
                .padding(6.dp),
            textAlign = TextAlign.Center
        )

        Spacer(modifier = Modifier.height(28.dp))
        PoweredByRoFooter(
            isBengali = isBengali,
            badgeHeight = 18.dp,
            modifier = Modifier.fillMaxWidth().padding(bottom = 16.dp)
        )
    }
}

fun Modifier.scaleLogo(scale: Float): Modifier = this.padding(16.dp)

@Composable
fun LoggedInNavigator(viewModel: PharmacyViewModel, isBengali: Boolean) {
    val currentUser by viewModel.currentUser.collectAsState()

    if (currentUser.role == "super_admin") {
        SuperAdminPortalScreen(viewModel, isBengali)
        return
    }

    if (currentUser.role == "customer") {
        CustomerPortalScreen(viewModel, isBengali)
        return
    }

    var currentTab by remember { mutableStateOf(0) } // 0: ড্যাশবোর্ড, 1: বিক্রয়, 2: ইনভেন্টরি, 3: রিপোর্ট, 4: অ্যাকাউন্ট

    androidx.activity.compose.BackHandler(enabled = currentTab != 0) {
        currentTab = 0
    }

    val notifications by viewModel.notifications.collectAsState()
    val unreadNotifCount = notifications.count { !it.isRead }

    var showPortalSwitchDialog by remember { mutableStateOf(false) }
    var showStaffAddPharmacyDialog by remember { mutableStateOf(false) }

    Scaffold(
        containerColor = Color.Transparent,
        bottomBar = {
            NavigationBar(
                containerColor = Color.Transparent,
                modifier = Modifier
                    .windowInsetsPadding(WindowInsets.navigationBars)
                    .padding(horizontal = 14.dp, vertical = 10.dp)
                    .clip(RoundedCornerShape(26.dp))
                    .background(GlassFillStrong, RoundedCornerShape(26.dp))
                    .border(1.dp, GlassBorder, RoundedCornerShape(26.dp))
            ) {
                val tabs = listOf(
                    Triple(if (isBengali) "ড্যাশবোর্ড" else "Dashboard", Icons.Filled.Dashboard, Icons.Outlined.Dashboard),
                    Triple(if (isBengali) "বিক্রয়" else "Sales", Icons.Filled.ShoppingCart, Icons.Outlined.ShoppingCart),
                    Triple(if (isBengali) "ইনভেন্টরি" else "Inventory", Icons.Filled.ListAlt, Icons.Outlined.ListAlt),
                    Triple(if (isBengali) "রিপোর্ট" else "Reports", Icons.Filled.Assessment, Icons.Outlined.Assessment),
                    Triple(if (isBengali) "সেটিংস" else "Settings", Icons.Filled.Settings, Icons.Outlined.Settings)
                )

                tabs.forEachIndexed { index, (label, filledIcon, outlinedIcon) ->
                    NavigationBarItem(
                        selected = currentTab == index,
                        onClick = { currentTab = index },
                        label = { Text(label, fontSize = 9.sp, fontWeight = FontWeight.Bold, maxLines = 1) },
                        icon = {
                            Box {
                                Icon(
                                    imageVector = if (currentTab == index) filledIcon else outlinedIcon,
                                    contentDescription = label
                                )
                            }
                        },
                        colors = NavigationBarItemDefaults.colors(
                            selectedIconColor = if (isDarkModeGlobal) Color.Black else Color.White,
                            unselectedIconColor = DarkTextSecondary.copy(alpha = 0.6f),
                            selectedTextColor = DarkTextPrimary,
                            unselectedTextColor = DarkTextSecondary.copy(alpha = 0.5f),
                            indicatorColor = DarkAccentRed
                        )
                    )
                }
            }
        }
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .background(GlassBackgroundGradient)
        ) {
            if (currentUser.role == "staff" && currentUser.linkedAdminUsername.isBlank() && currentTab != 4) {
                StaffUnlinkedPharmacyScreen(
                    isBengali = isBengali,
                    onGoToSettings = { currentTab = 4 },
                    onAddPharmacy = { showStaffAddPharmacyDialog = true }
                )
            } else {
                AnimatedContent(
                    targetState = currentTab,
                    transitionSpec = {
                        (fadeIn(animationSpec = tween(220, easing = FastOutSlowInEasing)) +
                            slideInVertically(animationSpec = tween(260, easing = FastOutSlowInEasing)) { it / 18 })
                            .togetherWith(fadeOut(animationSpec = tween(140)))
                    },
                    label = "tabContent"
                ) { tab ->
                    when (tab) {
                        0 -> DashboardScreen(viewModel, isBengali)
                        1 -> SalesScreen(viewModel, isBengali)
                        2 -> InventoryScreen(viewModel, isBengali)
                        3 -> ReportsScreen(viewModel, isBengali)
                        4 -> AccountScreen(viewModel, isBengali)
                    }
                }
            }
        }

        if (showStaffAddPharmacyDialog) {
            StaffAddPharmacyDialog(
                viewModel = viewModel,
                isBengali = isBengali,
                onDismiss = { showStaffAddPharmacyDialog = false }
            )
        }

        if (showPortalSwitchDialog) {
            NikotPortalSwitchDialog(
                viewModel = viewModel,
                isBengali = isBengali,
                onDismiss = { showPortalSwitchDialog = false }
            )
        }
    }
}

@Composable
fun StaffUnlinkedPharmacyScreen(
    isBengali: Boolean,
    onGoToSettings: () -> Unit,
    onAddPharmacy: () -> Unit
) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(20.dp)
            .verticalScroll(rememberScrollState()),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        Box(
            modifier = Modifier
                .size(90.dp)
                .background(DarkAccentGold.copy(alpha = 0.12f), CircleShape)
                .border(2.dp, DarkAccentGold.copy(alpha = 0.4f), CircleShape),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = Icons.Default.Lock,
                contentDescription = "Locked",
                tint = DarkAccentGold,
                modifier = Modifier.size(46.dp)
            )
        }

        Spacer(modifier = Modifier.height(20.dp))

        Text(
            text = if (isBengali) "ফার্মেসী সংযুক্ত নেই" else "No Pharmacy Linked",
