                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = if (isBengali) "অনুমোদন অপেক্ষমাণ স্টক (${formatBengaliNumber(pendingStockIns.size)})" else "Pending Stock-In Requests (${pendingStockIns.size})",
