@Composable
fun SalesScreen(viewModel: PharmacyViewModel, isBengali: Boolean) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val medicines by viewModel.allMedicines.collectAsState()
    val cart by viewModel.cart.collectAsState()
    val todayBillList by viewModel.todayBills.collectAsState()
    val totalCartAmount = cart.sumOf { it.totalPrice }

    var salesTabState by remember { mutableStateOf(0) } // 0 = Manual Sale, 1 = Online Orders

    var searchQuery by remember { mutableStateOf("") }
    var selectedMedicineForAdd by remember { mutableStateOf<Medicine?>(null) }
    var showCameraSimulation by remember { mutableStateOf(false) }
    var showPreviewBill by remember { mutableStateOf(false) }

    var selectedOrderForReceipt by remember { mutableStateOf<CustomerOrder?>(null) }
    var orderBillNumber by remember { mutableStateOf("") }

    val filteredMedicines = if (searchQuery.trim().isEmpty()) {
        emptyList()
    } else {
        medicines.filter {
            it.name.contains(searchQuery, ignoreCase = true) ||
            it.fullName.contains(searchQuery, ignoreCase = true) ||
            it.genericName.contains(searchQuery, ignoreCase = true) ||
            it.barcode == searchQuery.trim()
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
    ) {
        RoLogoHeader()
        Spacer(modifier = Modifier.height(12.dp))

        // Dual-Tab selection row
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(bottom = 12.dp)
                .background(DarkSurface, RoundedCornerShape(10.dp))
                .padding(4.dp),
            horizontalArrangement = Arrangement.spacedBy(4.dp)
        ) {
            Button(
                onClick = { salesTabState = 0 },
                modifier = Modifier.weight(1f),
                colors = ButtonDefaults.buttonColors(
                    containerColor = if (salesTabState == 0) DarkAccentRed else Color.Transparent,
                    contentColor = if (salesTabState == 0) DarkAccentText else DarkTextSecondary
                ),
                shape = RoundedCornerShape(8.dp),
                contentPadding = PaddingValues(vertical = 8.dp)
            ) {
                Icon(Icons.Filled.ShoppingCart, contentDescription = null, modifier = Modifier.size(16.dp))
                Spacer(modifier = Modifier.width(6.dp))
                Text(
                    text = if (isBengali) "ম্যানুয়াল বিক্রয়" else "Manual Sale",
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Bold
                )
            }
            
            val pendingOrdersCount = remember(viewModel.allCustomerOrders.collectAsState().value) {
                viewModel.allCustomerOrders.value.filter { it.status == "Pending" }.size
            }
            
            Button(
                onClick = { salesTabState = 1 },
                modifier = Modifier.weight(1f),
                colors = ButtonDefaults.buttonColors(
                    containerColor = if (salesTabState == 1) DarkAccentRed else Color.Transparent,
                    contentColor = if (salesTabState == 1) DarkAccentText else DarkTextSecondary
                ),
                shape = RoundedCornerShape(8.dp),
                contentPadding = PaddingValues(vertical = 8.dp)
            ) {
                Icon(Icons.Filled.CloudDownload, contentDescription = null, modifier = Modifier.size(16.dp))
                Spacer(modifier = Modifier.width(6.dp))
                Text(
                    text = if (isBengali) "অনলাইন অর্ডার (${formatBengaliNumber(pendingOrdersCount)})" else "Online Orders ($pendingOrdersCount)",
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Bold
                )
            }
        }

        if (salesTabState == 0) {
            // --- TAB 0: MANUAL SALE ---
            // Search + Scanner trigger row
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically
            ) {
                OutlinedTextField(
                    value = searchQuery,
                    onValueChange = { searchQuery = it },
                    label = { Text(if (isBengali) "ওষুধ খুঁজুন (নাম/জেনেরিক/বারকোড)" else "Search Medicine (Name/Generic/Barcode)") },
                    modifier = Modifier.weight(1f),
                    textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = DarkAccentRed,
                        unfocusedBorderColor = DarkTextSecondary,
                        focusedLabelColor = DarkAccentRed,
                        unfocusedLabelColor = DarkTextSecondary
                    ),
                    trailingIcon = {
                        if (searchQuery.isNotEmpty()) {
                            IconButton(onClick = { searchQuery = "" }) {
                                Icon(Icons.Filled.Close, "clear", tint = DarkTextPrimary)
                            }
                        }
                    }
                )
                Spacer(modifier = Modifier.width(8.dp))
                IconButton(
                    onClick = { showCameraSimulation = true },
                    modifier = Modifier
                        .size(54.dp)
                        .background(DarkSurface, RoundedCornerShape(12.dp))
                        .border(1.dp, DarkAccentRed.copy(alpha = 0.5f), RoundedCornerShape(12.dp))
                ) {
                    Icon(Icons.Filled.CameraAlt, "scan barcode", tint = DarkAccentRed)
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Query results OR Cart header
            Box(modifier = Modifier.weight(1f)) {
                if (filteredMedicines.isNotEmpty()) {
                    Column(modifier = Modifier.fillMaxSize()) {
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                            Text(if (isBengali) "অনুসন্ধানের ফলাফল:" else "Search Results:", color = DarkTextSecondary, fontSize = 12.sp)
                            Text(if (isBengali) "ফলাফল বন্ধ করতে মুছে দিন" else "Clear to close matches", color = DarkAccentGold, fontSize = 11.sp, modifier = Modifier.clickable { searchQuery = "" })
                        }
                        Spacer(modifier = Modifier.height(6.dp))
                        LazyColumn {
                            items(filteredMedicines) { med ->
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 4.dp)
                                        .clickable {
                                            val isOutOfStock = when (med.type.lowercase().trim()) {
                                                "tablet" -> med.totalPiecesInStock <= 0
                                                "syrup" -> med.bottlesInStock <= 0
                                                "ointment" -> med.tubesInStock <= 0
                                                "injection" -> med.vialsInStock <= 0
                                                else -> med.otherQuantity <= 0.0
                                            }
                                            if (isOutOfStock) {
                                                android.widget.Toast.makeText(
                                                    context,
                                                    if (isBengali) "স্টক নেই, বিক্রয় সম্ভব নয়" else "Out of stock, sale not possible",
                                                    android.widget.Toast.LENGTH_LONG
                                                ).show()
                                            } else {
                                                selectedMedicineForAdd = med
                                            }
                                        },
                                    colors = CardDefaults.cardColors(containerColor = DarkSurface)
                                ) {
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(12.dp),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column {
                                            Text(med.fullName, color = DarkTextPrimary, fontWeight = FontWeight.Bold)
                                            Text("${med.genericName} | ${med.company}", color = DarkTextSecondary, fontSize = 11.sp)
                                            Text(
                                                text = "${if (isBengali) "মজুদ: " else "Stock: "}${formatMedicineStock(med, isBengali)}",
                                                color = DarkAccentGold,
                                                fontSize = 12.sp
                                            )
                                        }
                                        Icon(Icons.Filled.Add, "add", tint = DarkAccentRed)
                                    }
                                }
                            }
                        }
                    }
                } else {
                    // Cart overview List
                    Column(modifier = Modifier.fillMaxSize()) {
                        Text(if (isBengali) "বর্তমান কার্ট তালিকা:" else "Current Cart Items:", color = DarkTextSecondary, fontSize = 12.sp, modifier = Modifier.padding(bottom = 6.dp))
                        if (cart.isEmpty()) {
                            Box(modifier = Modifier.weight(1f), contentAlignment = Alignment.Center) {
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Icon(Icons.Filled.ShoppingCart, "cart empty", tint = DarkTextSecondary, modifier = Modifier.size(48.dp))
                                    Spacer(modifier = Modifier.height(8.dp))
                                    Text(
                                        if (isBengali) "কার্ট বর্তমানে খালি রয়েছে।\nওষুধ যুক্ত করার জন্য উপরে খুঁজুন।" else "Your cart is empty.\nSearch medicine above to add into cart.",
                                        color = DarkTextSecondary,
                                        textAlign = TextAlign.Center,
                                        fontSize = 13.sp
                                    )
                                }
                            }
                        } else {
                            LazyColumn(modifier = Modifier.weight(1f)) {
                                items(cart) { item ->
                                    val desc = when (item.medicine.type) {
                                        "tablet" -> {
                                            val parts = mutableListOf<String>()
                                            if (item.soldBoxes > 0) parts.add("${item.soldBoxes} বক্স")
                                            if (item.soldStrips > 0) parts.add("${item.soldStrips} পাতা")
                                            if (item.soldPcs > 0) parts.add("${item.soldPcs} পিস")
                                            parts.joinToString(" ")
                                        }
                                        "syrup" -> "${item.soldBottles} বোতল"
                                        "ointment" -> "${item.soldTubes} টিউব"
                                        "injection" -> "${item.soldVials} ভায়াল"
                                        else -> "${item.soldOtherQty} ${item.medicine.otherUnit}"
                                    }

                                    Card(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(vertical = 4.dp),
                                        colors = CardDefaults.cardColors(containerColor = DarkSurface)
                                    ) {
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(12.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Column {
                                                Text(item.medicine.fullName, color = DarkTextPrimary, fontWeight = FontWeight.Bold)
                                                Text(
                                                    text = if (isBengali) "পরিমাণ: $desc" else "Qty: $desc",
                                                    color = DarkTextSecondary,
                                                    fontSize = 12.sp
                                                )
                                            }
                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                Text(
                                                    text = "৳${if (isBengali) formatBengaliNumber(String.format("%.2f", item.totalPrice)) else String.format("%.2f", item.totalPrice)}",
                                                    color = DarkAccentGold,
                                                    fontWeight = FontWeight.Bold,
                                                    modifier = Modifier.padding(end = 8.dp)
                                                )
                                                IconButton(onClick = { viewModel.removeFromCart(item.medicine.id) }) {
                                                    Icon(Icons.Filled.Delete, "delete", tint = DarkAccentRed)
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Total pricing count panel at bottom
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 8.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(if (isBengali) "সর্বমোট টাকা:" else "Total Amount:", color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 16.sp)
                Text(
                    "৳${if (isBengali) formatBengaliNumber(String.format("%.2f", totalCartAmount)) else String.format("%.2f", totalCartAmount)}",
                    color = DarkAccentGold,
                    fontWeight = FontWeight.Black,
                    fontSize = 22.sp
                )
            }

            Button(
                onClick = { if (cart.isNotEmpty()) showPreviewBill = true },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(48.dp),
                colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed, contentColor = DarkAccentText),
                enabled = cart.isNotEmpty()
            ) {
                Icon(Icons.Filled.ListAlt, "bill preview", tint = DarkAccentText)
                Spacer(modifier = Modifier.width(6.dp))
                Text(if (isBengali) "বিল প্রিন্ট করুন" else "Print Bill Preview", fontWeight = FontWeight.Bold, color = DarkAccentText)
            }
        } else {
            // --- TAB 1: ONLINE ORDERS ---
            val pendingOrders = viewModel.allCustomerOrders.collectAsState().value.filter { it.status == "Pending" }
            if (pendingOrders.isEmpty()) {
                Box(modifier = Modifier.weight(1f).fillMaxWidth(), contentAlignment = Alignment.Center) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Icon(Icons.Filled.CloudDownload, "no orders", tint = DarkTextSecondary.copy(alpha = 0.5f), modifier = Modifier.size(64.dp))
                        Spacer(modifier = Modifier.height(12.dp))
                        Text(
                            text = if (isBengali) "বর্তমানে কোন পেন্ডিং অনলাইন অর্ডার নেই!" else "No pending online orders right now!",
                            color = DarkTextSecondary,
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Medium
                        )
                    }
                }
            } else {
                LazyColumn(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    items(pendingOrders) { ord ->
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = DarkSurface),
                            border = BorderStroke(1.dp, SleekBorderColor),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Column(modifier = Modifier.padding(14.dp)) {
                                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
                                    Text(
                                        text = "${if (isBengali) "অর্ডারকারী: " else "Customer: "}${ord.customerUsername}",
                                        color = DarkTextPrimary,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 14.sp
                                    )
                                    val dateFmt = if (isBengali) formatBengaliDate(ord.timestamp) else java.text.SimpleDateFormat("dd-MM-yyyy", java.util.Locale.US).format(java.util.Date(ord.timestamp))
                                    Text(
                                        text = dateFmt,
                                        color = DarkTextSecondary,
                                        fontSize = 11.sp
                                    )
                                }
                                Spacer(modifier = Modifier.height(8.dp))
                                Text(
                                    text = ord.medicineName,
                                    color = DarkAccentGold,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 16.sp
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                val medicine = viewModel.allMedicines.value.find { it.id == ord.medicineId }
                                val unitName = if (medicine != null) {
                                    when (medicine.type) {
                                        "tablet" -> if (isBengali) "পিস" else "pcs"
                                        "syrup" -> if (isBengali) "বোতল" else "bottles"
                                        "ointment" -> if (isBengali) "টিউব" else "tubes"
                                        "injection" -> if (isBengali) "ভায়াল" else "vials"
                                        else -> medicine.otherUnit
                                    }
                                } else {
                                    if (isBengali) "টি" else "unit"
                                }
                                val qtyDesc = if (isBengali) {
                                    "${formatBengaliNumber(ord.quantity)} $unitName"
                                } else {
                                    "${ord.quantity} $unitName"
                                }
                                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                    Text(
                                        text = "${if (isBengali) "পরিমাণ: " else "Quantity: "}$qtyDesc",
                                        color = DarkTextSecondary,
                                        fontSize = 13.sp
                                    )
                                    Text(
                                        text = "৳${if (isBengali) formatBengaliNumber(String.format("%.1f", ord.totalPrice)) else String.format("%.1f", ord.totalPrice)}",
                                        color = DarkTextPrimary,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 14.sp
                                    )
                                }
                                Spacer(modifier = Modifier.height(12.dp))
                                Divider(color = Color.White.copy(alpha = 0.05f))
                                Spacer(modifier = Modifier.height(10.dp))
                                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
                                    Button(
                                        onClick = {
                                            viewModel.cancelCustomerOrder(ord) {
                                                android.widget.Toast.makeText(
                                                    context,
                                                    if (isBengali) "অর্ডার বাতিল করা হয়েছে!" else "Order Cancelled!",
                                                    android.widget.Toast.LENGTH_SHORT
                                                ).show()
                                            }
                                        },
                                        colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed.copy(alpha = 0.1f), contentColor = DarkAccentRed),
                                        shape = RoundedCornerShape(8.dp),
                                        modifier = Modifier.height(36.dp),
                                        contentPadding = PaddingValues(horizontal = 12.dp, vertical = 0.dp)
                                    ) {
                                        Text(if (isBengali) "অর্ডার বাতিল" else "Cancel Order", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                    }
                                    
                                    Button(
                                        onClick = {
                                            selectedOrderForReceipt = ord
                                            orderBillNumber = "BILL-ON-${System.currentTimeMillis() % 1000000}"
                                        },
                                        colors = ButtonDefaults.buttonColors(containerColor = SuccessColor, contentColor = Color.White),
                                        shape = RoundedCornerShape(8.dp),
                                        modifier = Modifier.height(36.dp),
                                        contentPadding = PaddingValues(horizontal = 12.dp, vertical = 0.dp)
                                    ) {
                                        Icon(Icons.Filled.ListAlt, contentDescription = null, modifier = Modifier.size(14.dp))
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text(if (isBengali) "রিসিভ ও বিল প্রিন্ট" else "Confirm & Print Bill", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // Real camera barcode scanner (CameraX + ML Kit)
    if (showCameraSimulation) {
        BarcodeScannerDialog(medicines, isBengali, onSelectBarcode = { code ->
            searchQuery = code
            showCameraSimulation = false
        }, onDismiss = { showCameraSimulation = false })
    }

    // Medicine Cart adder dialog based on selected medicine type
    if (selectedMedicineForAdd != null) {
        val medicineToConfigure = selectedMedicineForAdd!!
        CartQuantityInputDialog(
            medicine = medicineToConfigure,
            isBengali = isBengali,
            onConfirm = { boxes, strips, pcs, bottles, tubes, vials, otherQty ->
                viewModel.addToCart(medicineToConfigure, boxes, strips, pcs, bottles, tubes, vials, otherQty)
                selectedMedicineForAdd = null
                searchQuery = "" // clear search to focus back on list
            },
            onDismiss = { selectedMedicineForAdd = null }
        )
    }

    // Final preview bill drawer dialog
    if (showPreviewBill) {
        val generatedBillNo = viewModel.generateNextBillNumber(todayBillList)
        BillPreviewDialog(
            viewModel = viewModel,
            billNumber = generatedBillNo,
            cartItems = cart,
            totalPrice = totalCartAmount,
            isBengali = isBengali,
            onConfirmed = {
                showPreviewBill = false
            },
            onDismiss = { showPreviewBill = false }
        )
    }

    // Online Order receipt drawer dialog
    if (selectedOrderForReceipt != null) {
        OnlineOrderReceiptDialog(
            viewModel = viewModel,
            order = selectedOrderForReceipt!!,
            billNumber = orderBillNumber,
            isBengali = isBengali,
            onConfirmed = {
                selectedOrderForReceipt = null
            },
            onDismiss = {
                selectedOrderForReceipt = null
            }
        )
    }
}

/**
 * Real barcode/QR scanner: CameraX preview + an ML Kit on-device analyzer, with a
 * glass-styled viewfinder overlay. Falls back to a manual-entry glass sheet when the
 * camera permission isn't granted. Replaces the old canvas-tap simulation.
 */
@OptIn(ExperimentalPermissionsApi::class)
@SuppressLint("MissingPermission")
@Composable
fun BarcodeScannerDialog(
    allMedicines: List<Medicine>,
    isBengali: Boolean,
    onSelectBarcode: (String) -> Unit,
    onDismiss: () -> Unit
) {
    val context = LocalContext.current
    val lifecycleOwner = LocalLifecycleOwner.current
    val cameraPermissionState = rememberPermissionState(Manifest.permission.CAMERA)
    var torchOn by remember { mutableStateOf(false) }
    var showManualEntry by remember { mutableStateOf(false) }
    var manualCode by remember { mutableStateOf("") }
    var hasScanned by remember { mutableStateOf(false) }
    var cameraRef by remember { mutableStateOf<Camera?>(null) }

    LaunchedEffect(Unit) {
        if (!cameraPermissionState.status.isGranted) {
            cameraPermissionState.launchPermissionRequest()
        }
    }

    LaunchedEffect(torchOn) {
        try {
            cameraRef?.cameraControl?.enableTorch(torchOn)
        } catch (e: Exception) { /* torch not supported on this device */ }
    }

    DisposableEffect(Unit) {
        onDispose {
            try {
                ProcessCameraProvider.getInstance(context).get().unbindAll()
            } catch (e: Exception) { /* camera already released */ }
        }
    }

    Dialog(onDismissRequest = onDismiss, properties = DialogProperties(usePlatformDefaultWidth = false)) {
        Box(modifier = Modifier.fillMaxSize().background(Color.Black)) {

            if (cameraPermissionState.status.isGranted && !showManualEntry) {
                AndroidView(
                    modifier = Modifier.fillMaxSize(),
                    factory = { ctx ->
                        val previewView = PreviewView(ctx).apply {
                            scaleType = PreviewView.ScaleType.FILL_CENTER
                        }
                        val cameraProviderFuture = ProcessCameraProvider.getInstance(ctx)
                        cameraProviderFuture.addListener({
                            val cameraProvider = cameraProviderFuture.get()
                            val preview = Preview.Builder().build().also {
                                it.setSurfaceProvider(previewView.surfaceProvider)
                            }
                            val scanner = BarcodeScanning.getClient()
                            val imageAnalysis = ImageAnalysis.Builder()
                                .setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST)
                                .build()
                            imageAnalysis.setAnalyzer(Executors.newSingleThreadExecutor()) { imageProxy ->
                                val mediaImage = imageProxy.image
                                if (mediaImage != null) {
                                    val inputImage = InputImage.fromMediaImage(mediaImage, imageProxy.imageInfo.rotationDegrees)
                                    scanner.process(inputImage)
                                        .addOnSuccessListener { barcodes ->
                                            val value = barcodes.firstOrNull { !it.rawValue.isNullOrBlank() }?.rawValue
                                            if (!value.isNullOrBlank() && !hasScanned) {
                                                hasScanned = true
                                                onSelectBarcode(value)
                                            }
                                        }
                                        .addOnCompleteListener { imageProxy.close() }
                                } else {
                                    imageProxy.close()
                                }
                            }
                            try {
                                cameraProvider.unbindAll()
                                cameraRef = cameraProvider.bindToLifecycle(
                                    lifecycleOwner,
                                    CameraSelector.DEFAULT_BACK_CAMERA,
                                    preview,
                                    imageAnalysis
                                )
                            } catch (e: Exception) { /* no camera available on this device */ }
                        }, ContextCompat.getMainExecutor(ctx))
                        previewView
                    }
                )

                Box(modifier = Modifier.fillMaxSize().background(Color.Black.copy(alpha = 0.12f)))

                Column(modifier = Modifier.fillMaxSize()) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .windowInsetsPadding(WindowInsets.statusBars)
                            .padding(16.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        GlassIconButton(onClick = onDismiss, icon = Icons.Filled.ArrowBack, contentDescription = "Back")
                        Text(
                            if (isBengali) "বারকোড স্ক্যান করুন" else "Scan Barcode",
                            color = Color.White,
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Bold
                        )
                        GlassIconButton(
                            onClick = { torchOn = !torchOn },
                            icon = Icons.Filled.FlashOn,
                            contentDescription = "Flash",
                            tint = if (torchOn) DarkAccentGold else Color.White
                        )
                    }

                    Box(modifier = Modifier.weight(1f).fillMaxWidth(), contentAlignment = Alignment.Center) {
                        ScannerViewfinderFrame(accent = DarkAccentGold)
                        Text(
                            if (isBengali) "বারকোডটি ফ্রেমের মধ্যে রাখুন" else "Align the barcode within the frame",
                            color = Color.White.copy(alpha = 0.85f),
                            fontSize = 12.sp,
                            modifier = Modifier
                                .align(Alignment.BottomCenter)
                                .padding(bottom = 90.dp)
                        )
                    }

                    GlassPanel(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(topStart = 26.dp, topEnd = 26.dp),
                        strong = true
                    ) {
                        Column(modifier = Modifier.padding(18.dp)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    if (isBengali) "সাম্প্রতিক বারকোড" else "Recent barcodes",
                                    color = DarkTextPrimary,
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Bold
                                )
                                TextButton(onClick = { showManualEntry = true }) {
                                    Text(
                                        if (isBengali) "ম্যানুয়াল এন্ট্রি" else "Enter manually",
                                        color = DarkAccentGold,
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold
                                    )
                                }
                            }
                            Spacer(modifier = Modifier.height(8.dp))
                            val recent = allMedicines.filter { it.barcode.isNotBlank() }.take(3)
                            if (recent.isEmpty()) {
                                Text(
                                    if (isBengali) "কোনো বারকোডযুক্ত ওষুধ নেই" else "No barcoded items yet",
                                    color = DarkTextSecondary,
                                    fontSize = 11.sp
                                )
                            } else {
                                recent.forEach { med ->
                                    Row(
                                        modifier = Modifier.fillMaxWidth().padding(vertical = 6.dp),
                                        horizontalArrangement = Arrangement.SpaceBetween
                                    ) {
                                        Text(med.name, color = DarkTextPrimary, fontSize = 12.5.sp)
                                        Text(med.barcode, color = DarkAccentGold, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                // Permission not granted yet, or the user chose manual entry.
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(GlassBackgroundGradient)
                        .padding(24.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    Icon(
                        imageVector = Icons.Filled.CameraAlt,
                        contentDescription = null,
                        tint = DarkAccentGold,
                        modifier = Modifier.size(48.dp)
                    )
                    Spacer(modifier = Modifier.height(16.dp))
                    Text(
                        text = if (!cameraPermissionState.status.isGranted)
                            (if (isBengali) "বারকোড স্ক্যান করতে ক্যামেরার অনুমতি দিন" else "Camera permission is needed to scan barcodes")
                        else
                            (if (isBengali) "বারকোড নম্বর লিখুন" else "Enter the barcode number"),
                        color = DarkTextPrimary,
                        fontSize = 14.sp,
                        fontWeight = FontWeight.Bold,
                        textAlign = TextAlign.Center
                    )
                    Spacer(modifier = Modifier.height(16.dp))
                    if (!cameraPermissionState.status.isGranted) {
                        Button(
                            onClick = { cameraPermissionState.launchPermissionRequest() },
                            colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed, contentColor = DarkAccentText)
                        ) {
                            Text(if (isBengali) "অনুমতি দিন" else "Grant permission", fontWeight = FontWeight.Bold)
                        }
                        Spacer(modifier = Modifier.height(14.dp))
                    }
                    OutlinedTextField(
                        value = manualCode,
                        onValueChange = { manualCode = it },
                        label = { Text(if (isBengali) "বারকোড" else "Barcode") },
                        singleLine = true,
                        modifier = Modifier.fillMaxWidth()
                    )
                    Spacer(modifier = Modifier.height(12.dp))
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                        OutlinedButton(onClick = onDismiss, modifier = Modifier.weight(1f)) {
                            Text(if (isBengali) "বাতিল" else "Cancel")
                        }
                        Button(
                            onClick = { if (manualCode.isNotBlank()) onSelectBarcode(manualCode.trim()) },
                            modifier = Modifier.weight(1f),
                            colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed, contentColor = DarkAccentText)
                        ) {
                            Text(if (isBengali) "নিশ্চিত করুন" else "Confirm", fontWeight = FontWeight.Bold)
                        }
                    }

                    if (allMedicines.any { it.barcode.isNotBlank() }) {
                        Spacer(modifier = Modifier.height(20.dp))
                        Text(
                            if (isBengali) "অথবা তালিকা থেকে বেছে নিন:" else "Or pick from inventory:",
                            color = DarkTextSecondary,
                            fontSize = 11.sp,
                            modifier = Modifier.fillMaxWidth()
                        )
                        Spacer(modifier = Modifier.height(6.dp))
                        LazyColumn(modifier = Modifier.height(130.dp)) {
                            items(allMedicines.filter { it.barcode.isNotBlank() }) { med ->
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { onSelectBarcode(med.barcode) }
                                        .padding(vertical = 6.dp, horizontal = 4.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text(med.name, color = DarkTextPrimary, fontSize = 13.sp)
                                    Text(med.barcode, color = DarkAccentGold, fontSize = 13.sp, fontWeight = FontWeight.Bold)
                                }
                                Divider(color = Color.LightGray.copy(alpha = 0.1f))
                            }
                        }
                    }
                }
            }
        }
    }
}

/** Animated glass viewfinder frame: four corner brackets + a sweeping scan line. */
@Composable
private fun ScannerViewfinderFrame(accent: Color) {
    val infiniteTransition = rememberInfiniteTransition(label = "scanline")
    val lineProgress by infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(durationMillis = 1600, easing = LinearEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "scanlineProgress"
    )
    Box(modifier = Modifier.size(250.dp)) {
        Canvas(modifier = Modifier.fillMaxSize()) {
            val corner = 28.dp.toPx()
            val strokeW = 4.dp.toPx()
            val w = size.width
            val h = size.height
            drawLine(accent, androidx.compose.ui.geometry.Offset(0f, corner), androidx.compose.ui.geometry.Offset(0f, 0f), strokeW, StrokeCap.Round)
            drawLine(accent, androidx.compose.ui.geometry.Offset(0f, 0f), androidx.compose.ui.geometry.Offset(corner, 0f), strokeW, StrokeCap.Round)
            drawLine(accent, androidx.compose.ui.geometry.Offset(w - corner, 0f), androidx.compose.ui.geometry.Offset(w, 0f), strokeW, StrokeCap.Round)
            drawLine(accent, androidx.compose.ui.geometry.Offset(w, 0f), androidx.compose.ui.geometry.Offset(w, corner), strokeW, StrokeCap.Round)
            drawLine(accent, androidx.compose.ui.geometry.Offset(0f, h - corner), androidx.compose.ui.geometry.Offset(0f, h), strokeW, StrokeCap.Round)
            drawLine(accent, androidx.compose.ui.geometry.Offset(0f, h), androidx.compose.ui.geometry.Offset(corner, h), strokeW, StrokeCap.Round)
            drawLine(accent, androidx.compose.ui.geometry.Offset(w - corner, h), androidx.compose.ui.geometry.Offset(w, h), strokeW, StrokeCap.Round)
            drawLine(accent, androidx.compose.ui.geometry.Offset(w, h), androidx.compose.ui.geometry.Offset(w, h - corner), strokeW, StrokeCap.Round)
        }
        Box(
            modifier = Modifier
                .align(Alignment.TopStart)
                .offset(y = (lineProgress * 220).dp)
                .fillMaxWidth()
                .height(2.dp)
                .background(accent.copy(alpha = 0.85f))
        )
    }
}

@Composable
fun CartQuantityInputDialog(
    medicine: Medicine,
    isBengali: Boolean,
    onConfirm: (boxes: Int, strips: Int, pcs: Int, bottles: Int, tubes: Int, vials: Int, otherQty: Double) -> Unit,
    onDismiss: () -> Unit
) {
    val context = androidx.compose.ui.platform.LocalContext.current

    // states
    var tBoxText by remember { mutableStateOf("0") }
    var tStripText by remember { mutableStateOf("0") }
    var tPcText by remember { mutableStateOf("0") }
    var sBotText by remember { mutableStateOf("1") }
    var oTubText by remember { mutableStateOf("1") }
    var iVialText by remember { mutableStateOf("1") }
    var othQtyText by remember { mutableStateOf("1") }

    // Handlers for reactive clamping
    fun handleTabletChange(b: String, s: String, p: String) {
        val boxVal = b.toIntOrNull() ?: 0
        val stripVal = s.toIntOrNull() ?: 0
        val pcVal = p.toIntOrNull() ?: 0
        
        val totalRequested = (boxVal * medicine.stripsPerBox * medicine.pcsPerStrip) +
                             (stripVal * medicine.pcsPerStrip) + pcVal
        val maxAvailable = medicine.totalPiecesInStock
        
        if (totalRequested > maxAvailable) {
            val maxBoxes = maxAvailable / (medicine.stripsPerBox * medicine.pcsPerStrip)
            val remAfterB = maxAvailable % (medicine.stripsPerBox * medicine.pcsPerStrip)
            val maxStrips = remAfterB / medicine.pcsPerStrip
            val maxPcs = remAfterB % medicine.pcsPerStrip
            
            tBoxText = maxBoxes.toString()
            tStripText = maxStrips.toString()
            tPcText = maxPcs.toString()
            
            android.widget.Toast.makeText(
                context,
                if (isBengali) "স্টকে মাত্র ${formatBengaliNumber(medicine.boxesInStock)} বক্স ${formatBengaliNumber(medicine.stripsInStock)} পাতা ${formatBengaliNumber(medicine.pcsInStock)} পিস আছে"
                else "Only ${medicine.boxesInStock} Box(es) ${medicine.stripsInStock} Strip(s) ${medicine.pcsInStock} Piece(s) in stock",
                android.widget.Toast.LENGTH_SHORT
            ).show()
        } else {
            tBoxText = b
            tStripText = s
            tPcText = p
        }
    }

    fun handleSyrupChange(valStr: String) {
        if (valStr.isEmpty()) {
            sBotText = ""
            return
        }
        val n = valStr.toIntOrNull() ?: 0
        if (n > medicine.bottlesInStock) {
            sBotText = medicine.bottlesInStock.toString()
            android.widget.Toast.makeText(
                context,
                if (isBengali) "স্টকে মাত্র ${formatBengaliNumber(medicine.bottlesInStock)} বোতল আছে"
                else "Only ${medicine.bottlesInStock} bottle(s) in stock",
                android.widget.Toast.LENGTH_SHORT
            ).show()
        } else {
            sBotText = valStr
        }
    }

    fun handleOintmentChange(valStr: String) {
        if (valStr.isEmpty()) {
            oTubText = ""
            return
        }
        val n = valStr.toIntOrNull() ?: 0
        if (n > medicine.tubesInStock) {
            oTubText = medicine.tubesInStock.toString()
            android.widget.Toast.makeText(
                context,
                if (isBengali) "স্টকে মাত্র ${formatBengaliNumber(medicine.tubesInStock)} টিউব আছে"
                else "Only ${medicine.tubesInStock} tube(s) in stock",
                android.widget.Toast.LENGTH_SHORT
            ).show()
        } else {
            oTubText = valStr
        }
    }

    fun handleInjectionChange(valStr: String) {
        if (valStr.isEmpty()) {
            iVialText = ""
            return
        }
        val n = valStr.toIntOrNull() ?: 0
        if (n > medicine.vialsInStock) {
            iVialText = medicine.vialsInStock.toString()
            android.widget.Toast.makeText(
                context,
                if (isBengali) "স্টকে মাত্র ${formatBengaliNumber(medicine.vialsInStock)} ভায়াল আছে"
                else "Only ${medicine.vialsInStock} vial(s) in stock",
                android.widget.Toast.LENGTH_SHORT
            ).show()
        } else {
            iVialText = valStr
        }
    }

    fun handleOtherChange(valStr: String) {
        if (valStr.isEmpty()) {
            othQtyText = ""
            return
        }
        val d = valStr.toDoubleOrNull() ?: 0.0
        if (d > medicine.otherQuantity) {
            val unit = medicine.otherUnit.ifBlank { if (isBengali) "পিস" else "Pcs" }
            android.widget.Toast.makeText(
                context,
                if (isBengali) "স্টকে মাত্র ${formatBengaliNumber(medicine.otherQuantity)} $unit আছে"
                else "Only ${medicine.otherQuantity} $unit in stock",
                android.widget.Toast.LENGTH_SHORT
            ).show()
            val checkInt = medicine.otherQuantity.toInt()
            othQtyText = if (medicine.otherQuantity == checkInt.toDouble()) checkInt.toString() else medicine.otherQuantity.toString()
        } else {
            othQtyText = valStr
        }
    }

    Dialog(onDismissRequest = onDismiss) {
        Card(
            colors = CardDefaults.cardColors(containerColor = DarkSurface),
            shape = RoundedCornerShape(16.dp),
            modifier = Modifier.fillMaxWidth()
        ) {
            Column(modifier = Modifier.padding(16.dp)) {
                Text(
                    text = medicine.fullName,
                    color = DarkAccentGold,
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold
                )
                Text(
                    text = "${if (isBengali) "ধরন: " else "Type: "}${medicine.type.uppercase()}",
                    color = DarkTextSecondary,
                    fontSize = 12.sp,
                    modifier = Modifier.padding(bottom = 6.dp)
                )

                // Current available stock segment
                val stockDisplay = when (medicine.type) {
                    "tablet" -> {
                        val sBox = if (isBengali) formatBengaliNumber(medicine.boxesInStock) else medicine.boxesInStock.toString()
                        val sStrip = if (isBengali) formatBengaliNumber(medicine.stripsInStock) else medicine.stripsInStock.toString()
                        val sPc = if (isBengali) formatBengaliNumber(medicine.pcsInStock) else medicine.pcsInStock.toString()
                        if (isBengali) "স্টকে আছে: $sBox বক্স | $sStrip পাতা | $sPc পিস" else "In Stock: $sBox Box | $sStrip Strip | $sPc Piece(s)"
                    }
                    "syrup" -> {
                        val sBot = if (isBengali) formatBengaliNumber(medicine.bottlesInStock) else medicine.bottlesInStock.toString()
                        if (isBengali) "স্টকে আছে: $sBot বোতল" else "In Stock: $sBot Bottle(s)"
                    }
                    "ointment" -> {
                        val sTube = if (isBengali) formatBengaliNumber(medicine.tubesInStock) else medicine.tubesInStock.toString()
                        if (isBengali) "স্টকে আছে: $sTube টিউব" else "In Stock: $sTube Tube(s)"
                    }
                    "injection" -> {
                        val sVial = if (isBengali) formatBengaliNumber(medicine.vialsInStock) else medicine.vialsInStock.toString()
                        if (isBengali) "স্টকে আছে: $sVial ভায়াল" else "In Stock: $sVial Vial(s)"
                    }
                    else -> {
                        val sQty = if (isBengali) formatBengaliNumber(medicine.otherQuantity) else medicine.otherQuantity.toString()
                        val unit = medicine.otherUnit.ifBlank { if (isBengali) "পিস" else "Pcs" }
                        if (isBengali) "স্টকে আছে: $sQty $unit" else "In Stock: $sQty $unit"
                    }
                }
                Text(
                    text = stockDisplay,
                    color = DarkAccentRed,
                    fontWeight = FontWeight.SemiBold,
                    fontSize = 13.sp,
                    modifier = Modifier.padding(bottom = 12.dp)
                )

                // Render dynamic inputs
                when (medicine.type) {
                    "tablet" -> {
                        Text(if (isBengali) "বিক্রয়ের পরিমাণ নির্ধারণ করুন:" else "Set Sold Quantities:", color = DarkTextPrimary, fontSize = 13.sp)
                        Spacer(modifier = Modifier.height(8.dp))
                        Row(modifier = Modifier.fillMaxWidth()) {
                            OutlinedTextField(
                                value = tBoxText,
                                onValueChange = { handleTabletChange(it, tStripText, tPcText) },
                                label = { Text(if (isBengali) "বক্স" else "Box") },
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                modifier = Modifier
                                    .weight(1f)
                                    .padding(2.dp),
                                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary)
                            )
                            OutlinedTextField(
                                value = tStripText,
                                onValueChange = { handleTabletChange(tBoxText, it, tPcText) },
                                label = { Text(if (isBengali) "পাতা" else "Strip") },
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                modifier = Modifier
                                    .weight(1f)
                                    .padding(2.dp),
                                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary)
                            )
                            OutlinedTextField(
                                value = tPcText,
                                onValueChange = { handleTabletChange(tBoxText, tStripText, it) },
                                label = { Text(if (isBengali) "পিস" else "Piece") },
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                modifier = Modifier
                                    .weight(1f)
                                    .padding(2.dp),
                                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary)
                            )
                        }
                    }
                    "syrup" -> {
                        OutlinedTextField(
                            value = sBotText,
                            onValueChange = { handleSyrupChange(it) },
                            label = { Text(if (isBengali) "বোতলের সংখ্যা" else "Bottles Count") },
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                            modifier = Modifier.fillMaxWidth(),
                            textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary)
                        )
                    }
                    "ointment" -> {
                        OutlinedTextField(
                            value = oTubText,
                            onValueChange = { handleOintmentChange(it) },
                            label = { Text(if (isBengali) "টিউবের সংখ্যা" else "Tubes Count") },
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                            modifier = Modifier.fillMaxWidth(),
                            textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary)
                        )
                    }
                    "injection" -> {
                        OutlinedTextField(
                            value = iVialText,
                            onValueChange = { handleInjectionChange(it) },
                            label = { Text(if (isBengali) "ভায়ালের সংখ্যা" else "Vials Count") },
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                            modifier = Modifier.fillMaxWidth(),
                            textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary)
                        )
                    }
                    else -> { // other
                        OutlinedTextField(
                            value = othQtyText,
                            onValueChange = { handleOtherChange(it) },
                            label = { Text(if (isBengali) "পরিমাণ" else "Quantity") },
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                            modifier = Modifier.fillMaxWidth(),
                            textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary)
                        )
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                // Real-time calculation mockup visualizer
                val calculatedPriceTotal = when (medicine.type) {
                    "tablet" -> {
                        val boxes = tBoxText.toIntOrNull() ?: 0
                        val strips = tStripText.toIntOrNull() ?: 0
                        val pcs = tPcText.toIntOrNull() ?: 0
                        (boxes * medicine.salePriceBox) +
                        (strips * medicine.salePriceStrip) +
                        (pcs * medicine.salePricePiece)
                    }
                    "syrup" -> (sBotText.toIntOrNull() ?: 0) * medicine.salePriceUnit
                    "ointment" -> (oTubText.toIntOrNull() ?: 0) * medicine.salePriceUnit
                    "injection" -> (iVialText.toIntOrNull() ?: 0) * medicine.salePriceUnit
                    else -> (othQtyText.toDoubleOrNull() ?: 0.0) * medicine.salePriceUnit
                }

                Text(
                    text = "${if (isBengali) "মোট টাকা: ৳" else "Total Price: ৳"}${if (isBengali) formatBengaliNumber(String.format("%.2f", calculatedPriceTotal)) else String.format("%.2f", calculatedPriceTotal)}",
                    color = DarkAccentGold,
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    modifier = Modifier.align(Alignment.End)
                )

                Spacer(modifier = Modifier.height(16.dp))

                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
                    TextButton(onClick = onDismiss) {
                        Text(if (isBengali) "বাতিল" else "Cancel", color = DarkTextSecondary)
                    }
                    Spacer(modifier = Modifier.width(8.dp))
                    Button(
                        colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed, contentColor = DarkAccentText),
                        onClick = {
                            val boxesVal = tBoxText.toIntOrNull() ?: 0
                            val stripsVal = tStripText.toIntOrNull() ?: 0
                            val pcsVal = tPcText.toIntOrNull() ?: 0
                            val bottlesVal = sBotText.toIntOrNull() ?: 0
                            val tubesVal = oTubText.toIntOrNull() ?: 0
                            val vialsVal = iVialText.toIntOrNull() ?: 0
                            val otherQtyVal = othQtyText.toDoubleOrNull() ?: 0.0

                            onConfirm(boxesVal, stripsVal, pcsVal, bottlesVal, tubesVal, vialsVal, otherQtyVal)
                        }
                    ) {
                        Text(if (isBengali) "যোগ করুন" else "Add to Cart", color = DarkAccentText)
                    }
                }
            }
        }
    }
}

@Composable
fun BillPreviewDialog(
    viewModel: PharmacyViewModel,
    billNumber: String,
    cartItems: List<PharmacyViewModel.CartItem>,
    totalPrice: Double,
    isBengali: Boolean,
    onConfirmed: () -> Unit,
    onDismiss: () -> Unit
) {
    val pharmacyName by viewModel.pharmacyName.collectAsState()
    val address by viewModel.pharmacyAddress.collectAsState()
    val phone by viewModel.pharmacyPhone.collectAsState()

    val now = System.currentTimeMillis()
    val dateStr = if (isBengali) {
        "${formatBengaliDate(now)} ${formatBengaliTime(now)}"
    } else {
        SimpleDateFormat("dd-MM-yyyy hh:mm a", Locale.US).format(Date(now))
    }

    var discountText by remember { mutableStateOf("") }
    val discountVal = discountText.toDoubleOrNull() ?: 0.0
    val netTotal = (totalPrice - discountVal).coerceAtLeast(0.0)

    Dialog(onDismissRequest = onDismiss) {
        Card(
            colors = CardDefaults.cardColors(containerColor = DarkSurface),
            shape = RoundedCornerShape(16.dp),
            border = BorderStroke(1.dp, DarkAccentGold.copy(alpha = 0.3f)),
            modifier = Modifier
                .fillMaxWidth()
                .fillMaxHeight(0.85f)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(16.dp)
            ) {
                // Receipt Header
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    RoLogoHeader()
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(pharmacyName, color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 16.sp)
                    Text(address, color = DarkTextSecondary, fontSize = 11.sp, textAlign = TextAlign.Center)
                    Text("Phone: $phone", color = DarkTextSecondary, fontSize = 11.sp)
                    Spacer(modifier = Modifier.height(8.dp))
                    Divider(color = Color.LightGray.copy(alpha = 0.2f))
                }

                Spacer(modifier = Modifier.height(8.dp))

                // Metadata
                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                    Text(text = "${if (isBengali) "বিল নম্বর: " else "Bill No: "}$billNumber", color = DarkTextPrimary, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                    Text(text = dateStr, color = DarkTextSecondary, fontSize = 11.sp)
                }

                Spacer(modifier = Modifier.height(8.dp))
                Divider(color = Color.LightGray.copy(alpha = 0.2f))
                Spacer(modifier = Modifier.height(8.dp))

                // Scrollable Medicine List
                LazyColumn(modifier = Modifier.weight(1f)) {
                    items(cartItems) { item ->
                        val qtyDesc = when (item.medicine.type) {
                            "tablet" -> {
                                val parts = mutableListOf<String>()
                                if (item.soldBoxes > 0) parts.add("${item.soldBoxes} বক্স")
                                if (item.soldStrips > 0) parts.add("${item.soldStrips} পাতা")
                                if (item.soldPcs > 0) parts.add("${item.soldPcs} পিস")
                                parts.joinToString(" ")
                            }
                            "syrup" -> "${item.soldBottles} বোতল"
                            "ointment" -> "${item.soldTubes} টিউব"
                            "injection" -> "${item.soldVials} ভায়াল"
                            else -> "${item.soldOtherQty} ${item.medicine.otherUnit}"
                        }

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Column(modifier = Modifier.weight(0.7f)) {
                                Text(item.medicine.fullName, color = DarkTextPrimary, fontSize = 13.sp, fontWeight = FontWeight.Bold)
                                Text(qtyDesc, color = DarkTextSecondary, fontSize = 11.sp)
                            }
                            Text(
                                text = "৳${if (isBengali) formatBengaliNumber(String.format("%.2f", item.totalPrice)) else String.format("%.2f", item.totalPrice)}",
                                color = DarkTextPrimary,
                                fontSize = 13.sp,
                                modifier = Modifier.weight(0.3f),
                                textAlign = TextAlign.End
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(8.dp))
                
                // Discount Input field
                OutlinedTextField(
                    value = discountText,
                    onValueChange = { input ->
                        if (input.isEmpty() || (input.all { it.isDigit() } && input.length <= 6)) {
                            discountText = input
                        }
                    },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text(if (isBengali) "ছাড় (৳)" else "Discount (৳)", color = DarkAccentGold, fontSize = 12.sp) },
                    placeholder = { Text("0", color = Color.White.copy(alpha = 0.4f)) },
                    singleLine = true,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = DarkAccentGold,
                        unfocusedBorderColor = Color.White.copy(alpha = 0.15f),
                        focusedLabelColor = DarkAccentGold,
                        unfocusedLabelColor = DarkTextSecondary
                    ),
                    shape = RoundedCornerShape(12.dp)
                )

                Spacer(modifier = Modifier.height(8.dp))
                Divider(color = Color.LightGray.copy(alpha = 0.2f))
                Spacer(modifier = Modifier.height(8.dp))

                // Receipt price summation
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text(if (isBengali) "মোট:" else "Total:", color = DarkTextSecondary, fontSize = 13.sp)
                        Text(
                            "৳${if (isBengali) formatBengaliNumber(String.format("%.2f", totalPrice)) else String.format("%.2f", totalPrice)}",
                            color = DarkTextPrimary,
                            fontSize = 13.sp
                        )
                    }
                    if (discountVal > 0.0) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Text(if (isBengali) "ছাড়:" else "Discount:", color = DarkAccentRed, fontSize = 13.sp)
                            Text(
                                "৳${if (isBengali) formatBengaliNumber(String.format("%.2f", discountVal)) else String.format("%.2f", discountVal)} ${if (isBengali) "(বিয়োগ)" else "(less)"}",
                                color = DarkAccentRed,
                                fontSize = 13.sp
                            )
                        }
                    }
                    Spacer(modifier = Modifier.height(4.dp))
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(if (isBengali) "নেট মোট:" else "Net Total:", color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                        Text(
                            "৳${if (isBengali) formatBengaliNumber(String.format("%.2f", netTotal)) else String.format("%.2f", netTotal)}",
                            color = DarkAccentGold,
                            fontWeight = FontWeight.Black,
                            fontSize = 18.sp
                        )
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                // Action Confirm/Cancel buttons row
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    OutlinedButton(
                        onClick = onDismiss,
                        modifier = Modifier
                            .weight(1f)
                            .height(44.dp)
                            .padding(end = 4.dp),
                        colors = ButtonDefaults.outlinedButtonColors(contentColor = DarkTextPrimary)
                    ) {
                        Text(if (isBengali) "❌ বাতিল" else "❌ Cancel")
                    }
                    Button(
                        onClick = {
                            viewModel.confirmSale(billNumber, discountVal) {
                                onConfirmed()
                            }
                        },
                        modifier = Modifier
                            .weight(1.2f)
                            .height(44.dp)
                            .padding(start = 4.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed, contentColor = DarkAccentText)
                    ) {
                        Text(if (isBengali) "✅ বিল কনফার্ম করুন" else "✅ Confirm Bill", color = DarkAccentText, fontWeight = FontWeight.Bold)
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun InventoryScreen(viewModel: PharmacyViewModel, isBengali: Boolean) {
    val medicines by viewModel.allMedicines.collectAsState()
    val currentUser by viewModel.currentUser.collectAsState()
    val context = androidx.compose.ui.platform.LocalContext.current

    var searchQuery by remember { mutableStateOf("") }
    var showAddMedicineForm by remember { mutableStateOf(false) }
    var scaffoldAddBarcode by remember { mutableStateOf("") }
    var showAddOptionsDialog by remember { mutableStateOf(false) }
    var showCameraSimulationForAdd by remember { mutableStateOf(false) }
    var selectedFilter by remember { mutableStateOf("name") } // "name", "stock", "expiry"

    // quick actions
    var medForQuickStockUpdate by remember { mutableStateOf<Medicine?>(null) }
    var medForQuickPriceUpdate by remember { mutableStateOf<Medicine?>(null) }
    var medForDeleteConfirmation by remember { mutableStateOf<Medicine?>(null) }

    var stockStatusTab by remember { mutableStateOf(0) } // 0: Available Stock, 1: Out of Stock (Zero)

    val filteredList = medicines.filter {
        val matchesSearch = it.name.contains(searchQuery, ignoreCase = true) ||
            it.fullName.contains(searchQuery, ignoreCase = true) ||
            it.genericName.contains(searchQuery, ignoreCase = true) ||
            it.barcode == searchQuery.trim()

        val isOutOfStock = when (it.type) {
            "tablet" -> it.totalPiecesInStock <= 0
            "syrup" -> it.bottlesInStock <= 0
            "ointment" -> it.tubesInStock <= 0
            "injection" -> it.vialsInStock <= 0
            else -> it.otherQuantity <= 0.0
        }

        val matchesTab = if (stockStatusTab == 0) !isOutOfStock else isOutOfStock

        matchesSearch && matchesTab
    }.sortedWith { a, b ->
        when (selectedFilter) {
            "stock" -> a.totalPiecesInStock.compareTo(b.totalPiecesInStock)
            "expiry" -> {
                try {
                    val sdf = SimpleDateFormat("yyyy-MM-dd", Locale.US)
                    val ad = sdf.parse(a.expiryDate)?.time ?: Long.MAX_VALUE
                    val bd = sdf.parse(b.expiryDate)?.time ?: Long.MAX_VALUE
                    ad.compareTo(bd)
                } catch (_: Exception) {
                    0
                }
            }
            "company" -> a.company.compareTo(b.company, ignoreCase = true)
            else -> a.name.compareTo(b.name, ignoreCase = true) // name A-Z
        }
    }

    val groupedMedicines = remember(filteredList) {
        filteredList.groupBy { it.name.trim() }
    }

    Box(modifier = Modifier.fillMaxSize()) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp)
        ) {
            RoLogoHeader()
            Spacer(modifier = Modifier.height(12.dp))

            // Inventory search + Camera button next to it
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically
            ) {
                OutlinedTextField(
                    value = searchQuery,
                    onValueChange = { searchQuery = it },
                    label = { Text(if (isBengali) "ওষুধ খুঁজুন..." else "Find medicine...") },
                    modifier = Modifier.weight(1f),
                    textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = DarkAccentRed,
                        unfocusedBorderColor = DarkTextSecondary,
                        focusedLabelColor = DarkAccentRed,
                        unfocusedLabelColor = DarkTextSecondary
                    ),
                    trailingIcon = {
                        if (searchQuery.isNotEmpty()) {
                            IconButton(onClick = { searchQuery = "" }) {
                                Icon(Icons.Filled.Close, "clear", tint = DarkTextPrimary)
                            }
                        }
                    }
                )
                Spacer(modifier = Modifier.width(8.dp))
                IconButton(
                    onClick = { showCameraSimulationForAdd = true },
                    modifier = Modifier
                        .size(54.dp)
                        .background(DarkSurface, RoundedCornerShape(12.dp))
                        .border(1.dp, DarkAccentRed.copy(alpha = 0.5f), RoundedCornerShape(12.dp))
                ) {
                    Icon(Icons.Filled.CameraAlt, "scan barcode", tint = DarkAccentRed)
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Stock status segmented control (মজুদ আছে vs স্টক শেষ)
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(DarkSurface, RoundedCornerShape(10.dp))
                    .border(1.dp, SleekBorderColor, RoundedCornerShape(10.dp))
                    .padding(4.dp),
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Box(
                    modifier = Modifier
                        .weight(1f)
                        .background(if (stockStatusTab == 0) DarkAccentRed else Color.Transparent, RoundedCornerShape(8.dp))
                        .clickable { stockStatusTab = 0 }
                        .padding(vertical = 10.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = if (isBengali) "মজুদ আছে (স্টক)" else "Available Stock",
                        color = if (stockStatusTab == 0) DarkAccentText else DarkTextSecondary,
                        fontWeight = FontWeight.Bold,
                        fontSize = 13.sp
                    )
                }
                Box(
                    modifier = Modifier
                        .weight(1f)
                        .background(if (stockStatusTab == 1) DarkAccentRed else Color.Transparent, RoundedCornerShape(8.dp))
                        .clickable { stockStatusTab = 1 }
                        .padding(vertical = 10.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = if (isBengali) "একেবারেই নাই (স্টক শেষ)" else "Out of Stock (Zero)",
                        color = if (stockStatusTab == 1) DarkAccentText else DarkTextSecondary,
                        fontWeight = FontWeight.Bold,
                        fontSize = 13.sp
                    )
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

        // Multi Filter Selection Options Row
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(if (isBengali) "ফিল্টার:" else "Filters:", color = DarkTextSecondary, fontSize = 12.sp)
            Spacer(modifier = Modifier.width(8.dp))
            Row(
                modifier = Modifier
                    .weight(1f)
                    .horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(4.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                FilterTabButton(
                    label = if (isBengali) "নাম (A → Z)" else "Name (A → Z)",
                    selected = selectedFilter == "name",
                    onClick = { selectedFilter = "name" }
                )
                FilterTabButton(
                    label = if (isBengali) "স্টক (কম → বেশি)" else "Stock (Low → High)",
                    selected = selectedFilter == "stock",
                    onClick = { selectedFilter = "stock" }
                )
                FilterTabButton(
                    label = if (isBengali) "মেয়াদ (নিকট → দূর)" else "Expiry (Soon → Far)",
                    selected = selectedFilter == "expiry",
                    onClick = { selectedFilter = "expiry" }
                )
                FilterTabButton(
                    label = if (isBengali) "কোম্পানি (A → Z)" else "Company (A → Z)",
                    selected = selectedFilter == "company",
                    onClick = { selectedFilter = "company" }
                )
            }
        }

        Spacer(modifier = Modifier.height(12.dp))

        // Medicine Card Grid Lists
        Box(modifier = Modifier.weight(1f)) {
            if (filteredList.isEmpty()) {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text(
                        if (isBengali) "ইনভেন্টরিতে কোনো ওষুধ নেই!\nওষুধ যুক্ত করতে '+' বাটন ট্যাপ করুন।" else "Inventory is empty!\nTap '+' to register dynamic items.",
                        color = DarkTextSecondary,
                        textAlign = TextAlign.Center,
                        fontSize = 13.sp
                    )
                }
            } else {
                LazyColumn(modifier = Modifier.fillMaxSize()) {
                    groupedMedicines.forEach { (brandName, medicinesInGroup) ->
                        item {
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 4.dp),
                                colors = CardDefaults.cardColors(containerColor = SleekBorderColor.copy(alpha = 0.3f)),
                                border = BorderStroke(1.dp, SleekBorderColor),
                                shape = RoundedCornerShape(10.dp)
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(horizontal = 12.dp, vertical = 6.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = brandName,
                                        color = DarkAccentGold,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 14.sp
                                    )
                                    val countStr = if (isBengali) "${formatBengaliNumber(medicinesInGroup.size)} টি ধরন" else "${medicinesInGroup.size} variant(s)"
                                    Text(
                                        text = countStr,
                                        color = DarkTextSecondary,
                                        fontSize = 11.sp
                                    )
                                }
                            }
                        }
                        items(medicinesInGroup) { med ->
                            MedicineCardItem(
                                med = med,
                                isBengali = isBengali,
                                isAdmin = viewModel.isMerchant(currentUser),
                                onUpdateStock = { medForQuickStockUpdate = med },
                                onChangePrice = { medForQuickPriceUpdate = med },
                                onDelete = { medForDeleteConfirmation = med }
                            )
                        }
                    }
                }
            }
        }
    }

    if (showCameraSimulationForAdd) {
        BarcodeScannerDialog(
            allMedicines = medicines,
            isBengali = isBengali,
            onSelectBarcode = { code ->
                scaffoldAddBarcode = code
                showCameraSimulationForAdd = false
                showAddMedicineForm = true
            },
            onDismiss = { showCameraSimulationForAdd = false }
        )
    }

    FloatingActionButton(
        onClick = {
            scaffoldAddBarcode = ""
            showAddMedicineForm = true
        },
        containerColor = DarkAccentRed,
        contentColor = Color.White,
        modifier = Modifier
            .align(Alignment.BottomEnd)
            .padding(20.dp)
            .size(56.dp)
    ) {
        Icon(Icons.Filled.Add, "add medicine options")
    }

    if (showAddMedicineForm) {
        AddMedicineFormDialog(
            isBengali = isBengali,
            existingMedicines = medicines,
            initialBarcode = scaffoldAddBarcode,
            onConfirmAdd = { newMed ->
                val existing = medicines.find { ext ->
                    (ext.name.equals(newMed.name, ignoreCase = true) &&
                     ext.dosageStrength.equals(newMed.dosageStrength, ignoreCase = true) &&
                     ext.type.equals(newMed.type, ignoreCase = true)) ||
                    (newMed.barcode.isNotBlank() && ext.barcode == newMed.barcode)
                }
                
                if (currentUser.role == "staff") {
                    viewModel.requestPendingMedicine(newMed, currentUser.username, existing?.id)
                    android.widget.Toast.makeText(
                        context,
                        if (isBengali) "অনুরোধটি অনুমোদনের জন্য মার্চেন্টের নিকট পাঠানো হয়েছে।" else "The request has been sent to the merchant for approval.",
                        android.widget.Toast.LENGTH_LONG
                    ).show()
                    showAddMedicineForm = false
                } else {
                    if (existing != null) {
                        val mergedMed = when (existing.type) {
                            "tablet" -> {
                                val oldTotal = existing.totalPiecesInStock
                                val addedTotal = (newMed.boxesInStock * newMed.stripsPerBox * newMed.pcsPerStrip) +
                                                 (newMed.stripsInStock * newMed.pcsPerStrip) +
                                                 newMed.pcsInStock
                                val combinedTotal = oldTotal + addedTotal
                                
                                val stripsPerBox = if (newMed.stripsPerBox > 0) newMed.stripsPerBox else existing.stripsPerBox
                                val pcsPerStrip = if (newMed.pcsPerStrip > 0) newMed.pcsPerStrip else existing.pcsPerStrip
                                val factor = stripsPerBox * pcsPerStrip
                                
                                val finalBoxes = if (factor > 0) combinedTotal / factor else 0
                                val remAfterBoxes = if (factor > 0) combinedTotal % factor else 0
                                val finalStrips = if (pcsPerStrip > 0) remAfterBoxes / pcsPerStrip else 0
                                val finalPcs = if (pcsPerStrip > 0) remAfterBoxes % pcsPerStrip else 0
                                
                                existing.copy(
                                    name = newMed.name,
                                    company = newMed.company,
                                    genericName = newMed.genericName,
                                    barcode = newMed.barcode,
                                    expiryDate = newMed.expiryDate,
                                    purchasePriceBox = newMed.purchasePriceBox,
                                    salePriceBox = newMed.salePriceBox,
                                    stripsPerBox = stripsPerBox,
                                    pcsPerStrip = pcsPerStrip,
                                    boxesInStock = finalBoxes,
                                    stripsInStock = finalStrips,
                                    pcsInStock = finalPcs
                                )
                            }
                            "syrup" -> {
                                existing.copy(
                                    name = newMed.name,
                                    company = newMed.company,
                                    genericName = newMed.genericName,
                                    barcode = newMed.barcode,
                                    expiryDate = newMed.expiryDate,
                                    mlPerBottle = newMed.mlPerBottle,
                                    purchasePriceUnit = newMed.purchasePriceUnit,
                                    salePriceUnit = newMed.salePriceUnit,
                                    bottlesInStock = existing.bottlesInStock + newMed.bottlesInStock
                                )
                            }
                            "ointment" -> {
                                existing.copy(
                                    name = newMed.name,
                                    company = newMed.company,
                                    genericName = newMed.genericName,
                                    barcode = newMed.barcode,
                                    expiryDate = newMed.expiryDate,
                                    gramsPerTube = newMed.gramsPerTube,
                                    purchasePriceUnit = newMed.purchasePriceUnit,
                                    salePriceUnit = newMed.salePriceUnit,
                                    tubesInStock = existing.tubesInStock + newMed.tubesInStock
                                )
                            }
                            "injection" -> {
                                existing.copy(
                                    name = newMed.name,
                                    company = newMed.company,
                                    genericName = newMed.genericName,
                                    barcode = newMed.barcode,
                                    expiryDate = newMed.expiryDate,
                                    purchasePriceUnit = newMed.purchasePriceUnit,
                                    salePriceUnit = newMed.salePriceUnit,
                                    vialsInStock = existing.vialsInStock + newMed.vialsInStock
                                )
                            }
                            else -> {
                                existing.copy(
                                    name = newMed.name,
                                    company = newMed.company,
                                    genericName = newMed.genericName,
                                    barcode = newMed.barcode,
                                    expiryDate = newMed.expiryDate,
                                    otherUnit = newMed.otherUnit,
                                    purchasePriceUnit = newMed.purchasePriceUnit,
                                    salePriceUnit = newMed.salePriceUnit,
                                    otherQuantity = existing.otherQuantity + newMed.otherQuantity
                                )
                            }
                        }
                        
                        viewModel.updateMedicine(mergedMed)
                        
                        val hasChangeInStock = (newMed.boxesInStock > 0 || newMed.stripsInStock > 0 || newMed.pcsInStock > 0 ||
                                               newMed.bottlesInStock > 0 || newMed.tubesInStock > 0 ||
                                               newMed.vialsInStock > 0 || newMed.otherQuantity > 0.0)
                        if (hasChangeInStock) {
                            val record = StockInRecord(
                                medicineId = existing.id,
                                medicineName = existing.name,
                                medicineType = existing.type,
                                timestamp = System.currentTimeMillis(),
                                addedBoxes = newMed.boxesInStock,
                                addedStrips = newMed.stripsInStock,
                                addedPcs = newMed.pcsInStock,
                                addedBottles = newMed.bottlesInStock,
                                addedTubes = newMed.tubesInStock,
                                addedVials = newMed.vialsInStock,
                                addedOtherQty = newMed.otherQuantity,
                                oldPurchasePrice = if (existing.type == "tablet") existing.purchasePriceBox else existing.purchasePriceUnit,
                                oldSalePrice = if (existing.type == "tablet") existing.salePriceBox else existing.salePriceUnit,
                                newPurchasePrice = if (existing.type == "tablet") newMed.purchasePriceBox else newMed.purchasePriceUnit,
                                newSalePrice = if (existing.type == "tablet") newMed.salePriceBox else newMed.salePriceUnit
                            )
                            viewModel.addStockInRecord(record)
                        }
                        showAddMedicineForm = false
                    } else {
                        viewModel.addMedicine(newMed) { newId ->
                            val hasChangeInStock = (newMed.boxesInStock > 0 || newMed.stripsInStock > 0 || newMed.pcsInStock > 0 ||
                                                   newMed.bottlesInStock > 0 || newMed.tubesInStock > 0 ||
                                                   newMed.vialsInStock > 0 || newMed.otherQuantity > 0.0)
                            if (hasChangeInStock) {
                                val record = StockInRecord(
                                    medicineId = newId,
                                    medicineName = newMed.name,
                                    medicineType = newMed.type,
                                    timestamp = System.currentTimeMillis(),
                                    addedBoxes = newMed.boxesInStock,
                                    addedStrips = newMed.stripsInStock,
                                    addedPcs = newMed.pcsInStock,
                                    addedBottles = newMed.bottlesInStock,
                                    addedTubes = newMed.tubesInStock,
                                    addedVials = newMed.vialsInStock,
                                    addedOtherQty = newMed.otherQuantity,
                                    oldPurchasePrice = 0.0,
                                    oldSalePrice = 0.0,
                                    newPurchasePrice = if (newMed.type == "tablet") newMed.purchasePriceBox else newMed.purchasePriceUnit,
                                    newSalePrice = if (newMed.type == "tablet") newMed.salePriceBox else newMed.salePriceUnit
                                )
                                viewModel.addStockInRecord(record)
                            }
                        }
                        showAddMedicineForm = false
                    }
                }
            },
            onDismiss = { showAddMedicineForm = false }
        )
    }

    if (medForQuickStockUpdate != null) {
        QuickStockUpdateDialog(
            med = medForQuickStockUpdate!!,
            isBengali = isBengali,
            onConfirmed = { b, s, p, bot, t, v, oQty, purchase, sale, lowStock ->
                if (currentUser.role == "staff") {
                    viewModel.requestPendingStockIn(
                        medicine = medForQuickStockUpdate!!,
                        addBoxes = b,
                        addStrips = s,
                        addPcs = p,
                        addBottles = bot,
                        addTubes = t,
                        addVials = v,
                        addOtherQty = oQty,
                        newPurchasePrice = purchase,
                        newSalePrice = sale,
                        staffUsername = currentUser.username
                    )
                    viewModel.updatePriceOnly(
                        medicine = medForQuickStockUpdate!!,
                        boxPurchase = medForQuickStockUpdate!!.purchasePriceBox,
                        boxSale = medForQuickStockUpdate!!.salePriceBox,
                        unitPurchase = medForQuickStockUpdate!!.purchasePriceUnit,
                        unitSale = medForQuickStockUpdate!!.salePriceUnit,
                        lowStockThreshold = lowStock
                    )
                    android.widget.Toast.makeText(
                        context,
                        if (isBengali) "স্টক যোগের অনুরোধ মার্চেন্টের অনুমোদনের জন্য পাঠানো হয়েছে।" else "Stock addition request sent for Merchant approval.",
                        android.widget.Toast.LENGTH_LONG
                    ).show()
                } else {
                    viewModel.addStockAndPrices(medForQuickStockUpdate!!, b, s, p, bot, t, v, oQty, purchase, sale, lowStock)
                }
                medForQuickStockUpdate = null
            },
            onDismiss = { medForQuickStockUpdate = null }
        )
    }

    if (medForQuickPriceUpdate != null) {
        QuickPriceChangeDialog(
            med = medForQuickPriceUpdate!!,
            isBengali = isBengali,
            onConfirmed = { bP, bS, uP, uS, lowStock ->
                viewModel.updatePriceOnly(medForQuickPriceUpdate!!, bP, bS, uP, uS, lowStock)
                medForQuickPriceUpdate = null
            },
            onDismiss = { medForQuickPriceUpdate = null }
        )
    }

    if (medForDeleteConfirmation != null) {
        val selectedMed = medForDeleteConfirmation!!
        Dialog(onDismissRequest = { medForDeleteConfirmation = null }) {
            Card(
                colors = CardDefaults.cardColors(containerColor = DarkSurface),
                shape = RoundedCornerShape(20.dp),
                border = BorderStroke(1.dp, DarkAccentRed.copy(alpha = 0.5f)),
                modifier = Modifier.fillMaxWidth().padding(16.dp)
            ) {
                Column(
                    modifier = Modifier.padding(20.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    // Warning icon
                    Icon(
                        imageVector = Icons.Filled.Warning,
                        contentDescription = "Warning",
                        tint = DarkAccentRed,
                        modifier = Modifier.size(48.dp)
                    )
                    Spacer(modifier = Modifier.height(16.dp))

                    Text(
                        text = if (isBengali) "ওষুধ ডিলিট নিশ্চিত করুন" else "Confirm Delete",
                        color = DarkAccentGold,
                        fontWeight = FontWeight.Bold,
                        fontSize = 18.sp,
                        textAlign = TextAlign.Center
                    )
                    Spacer(modifier = Modifier.height(12.dp))

                    Text(
                        text = if (isBengali) 
                            "আপনি কি নিশ্চিত যে আপনি '${selectedMed.fullName}' ইনভেন্টরি থেকে ডিলিট করতে চান?" 
                            else "Are you sure you want to delete '${selectedMed.fullName}' from the inventory?",
                        color = DarkTextPrimary,
                        fontSize = 14.sp,
                        textAlign = TextAlign.Center
                    )
                    Spacer(modifier = Modifier.height(24.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        // Dismiss Button
                        TextButton(
                            onClick = { medForDeleteConfirmation = null },
                            modifier = Modifier.weight(1f)
                        ) {
                            Text(if (isBengali) "বাতিল" else "Cancel", color = DarkTextSecondary)
                        }

                        // Confirm Button
                        Button(
                            onClick = {
                                viewModel.deleteMedicine(selectedMed)
                                medForDeleteConfirmation = null
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.weight(1f)
                        ) {
                            Text(if (isBengali) "ডিলিট" else "Delete", color = Color.White, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }
    }
    }
}

@Composable
fun FilterTabButton(label: String, selected: Boolean, onClick: () -> Unit) {
    Box(
        modifier = Modifier
            .clip(RoundedCornerShape(6.dp))
            .background(if (selected) DarkAccentRed else DarkSurface)
            .clickable { onClick() }
            .padding(horizontal = 10.dp, vertical = 6.dp)
    ) {
        Text(label, color = if (selected) DarkAccentText else DarkTextSecondary, fontSize = 11.sp, fontWeight = FontWeight.Bold)
    }
}

@Composable
fun MedicineCardItem(
    med: Medicine,
    isBengali: Boolean,
    isAdmin: Boolean = false,
    onUpdateStock: () -> Unit,
    onChangePrice: () -> Unit,
    onDelete: () -> Unit
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 6.dp),
        colors = CardDefaults.cardColors(containerColor = DarkCardBg),
        shape = RoundedCornerShape(20.dp),
        border = BorderStroke(1.dp, SleekBorderColor)
    ) {
        Column(modifier = Modifier.padding(14.dp)) {
            // Title block
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                Column {
                    Text(med.fullName, color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 16.sp)
                    Text("${med.genericName} | ${med.company}", color = DarkTextSecondary, fontSize = 11.sp)
                    Text("${if (isBengali) "বারকোড: " else "Barcode: "}${med.barcode} | ${if (isBengali) "মেয়াদ: " else "Exp: "}${med.expiryDate}", color = DarkTextSecondary, fontSize = 11.sp)
                }
                
                if (isAdmin) {
                    IconButton(onClick = onDelete, modifier = Modifier.size(24.dp)) {
                        Icon(Icons.Filled.Delete, "delete item", tint = DarkAccentRed.copy(alpha = 0.7f), modifier = Modifier.size(16.dp))
                    }
                }
            }

            Spacer(modifier = Modifier.height(10.dp))
            Divider(color = Color.LightGray.copy(alpha = 0.1f))
            Spacer(modifier = Modifier.height(10.dp))

            // stock summary line
            Text(
                formatMedicineStock(med, isBengali),
                color = DarkTextPrimary,
                fontWeight = FontWeight.Bold,
                fontSize = 13.sp
            )

            Spacer(modifier = Modifier.height(4.dp))

            // purchase/sales display breakdown
            if (med.type == "tablet") {
                val pB = if (isBengali) formatBengaliNumber(med.purchasePriceBox) else med.purchasePriceBox.toString()
                val pS = if (isBengali) formatBengaliNumber(String.format("%.2f", med.purchasePriceStrip)) else String.format("%.2f", med.purchasePriceStrip)
                val pP = if (isBengali) formatBengaliNumber(String.format("%.2f", med.purchasePricePiece)) else String.format("%.2f", med.purchasePricePiece)

                val sB = if (isBengali) formatBengaliNumber(med.salePriceBox) else med.salePriceBox.toString()
                val sS = if (isBengali) formatBengaliNumber(String.format("%.2f", med.salePriceStrip)) else String.format("%.2f", med.salePriceStrip)
                val sP = if (isBengali) formatBengaliNumber(String.format("%.2f", med.salePricePiece)) else String.format("%.2f", med.salePricePiece)

                val profitP = if (isBengali) formatBengaliNumber(String.format("%.2f", med.profitPerPiece)) else String.format("%.2f", med.profitPerPiece)
                val profitPct = if (isBengali) formatBengaliNumber(String.format("%.1f", med.profitPercentageTablet)) else String.format("%.1f", med.profitPercentageTablet)

                Column {
                    Text(
                        "${if (isBengali) "ক্রয়: বক্স ৳" else "Buy: Box ৳"}$pB | ${if (isBengali) "পাতা ৳" else "Strip ৳"}$pS | ${if (isBengali) "পিস ৳" else "Pc ৳"}$pP",
                        fontSize = 11.sp,
                        color = DarkTextSecondary
                    )
                    Text(
                        "${if (isBengali) "বিক্রয়: বক্স ৳" else "Sell: Box ৳"}$sB | ${if (isBengali) "পাতা ৳" else "Strip ৳"}$sS | ${if (isBengali) "পিস ৳" else "Pc ৳"}$sP",
                        fontSize = 11.sp,
                        color = DarkTextSecondary
                    )
                    Text(
                        "${if (isBengali) "লাভ: পিস প্রতি ৳" else "Profit: Per Pc ৳"}$profitP ($profitPct%)",
                        fontSize = 11.sp,
                        color = Color.Green,
                        fontWeight = FontWeight.SemiBold
                    )
                }
            } else {
                val buyU = if (isBengali) formatBengaliNumber(med.purchasePriceUnit) else med.purchasePriceUnit.toString()
                val sellU = if (isBengali) formatBengaliNumber(med.salePriceUnit) else med.salePriceUnit.toString()
                val profitU = if (isBengali) formatBengaliNumber(String.format("%.2f", med.profitPerUnit)) else String.format("%.2f", med.profitPerUnit)
                val profitPct = if (isBengali) formatBengaliNumber(String.format("%.1f", med.profitPercentageUnit)) else String.format("%.1f", med.profitPercentageUnit)

                Column {
                    Text("${if (isBengali) "ক্রয়: প্রতি ইউনিট ৳" else "Buy: Per Unit ৳"}$buyU | ${if (isBengali) "বিক্রয়: প্রতি ইউনিট ৳" else "Sell: Per Unit ৳"}$sellU", fontSize = 11.sp, color = DarkTextSecondary)
                    Text("${if (isBengali) "লাভ: ইউনিট প্রতি ৳" else "Profit: Per Unit ৳"}$profitU ($profitPct%)", fontSize = 11.sp, color = Color.Green, fontWeight = FontWeight.SemiBold)
                }
            }

            Spacer(modifier = Modifier.height(10.dp))

            // Update items configuration action triggers
            Row(modifier = Modifier.fillMaxWidth()) {
                OutlinedButton(
                    onClick = onUpdateStock,
                    modifier = Modifier
                        .weight(1f)
                        .height(34.dp)
                        .padding(end = 4.dp),
                    shape = RoundedCornerShape(6.dp),
                    colors = ButtonDefaults.outlinedButtonColors(contentColor = DarkTextPrimary)
                ) {
                    Icon(Icons.Filled.Edit, "edit stock", modifier = Modifier.size(12.dp))
                    Spacer(modifier = Modifier.width(4.dp))
                    Text(if (isBengali) "স্টক আপডেট" else "Update Stock", fontSize = 10.sp)
                }
                OutlinedButton(
                    onClick = onChangePrice,
                    modifier = Modifier
                        .weight(1f)
                        .height(34.dp)
                        .padding(start = 4.dp),
                    shape = RoundedCornerShape(6.dp),
                    colors = ButtonDefaults.outlinedButtonColors(contentColor = DarkTextPrimary)
                ) {
                    Icon(Icons.Filled.Edit, "price config", modifier = Modifier.size(12.dp))
                    Spacer(modifier = Modifier.width(4.dp))
                    Text(if (isBengali) "দাম পরিবর্তন" else "Change Price", fontSize = 10.sp)
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AddMedicineFormDialog(
    isBengali: Boolean,
    existingMedicines: List<Medicine>,
    initialBarcode: String = "",
    onConfirmAdd: (Medicine) -> Unit,
    onDismiss: () -> Unit
) {
    var step by remember { mutableStateOf(if (initialBarcode.isNotBlank()) 2 else 1) } // 1 to 4 steps
    var autoFilledForId by remember { mutableStateOf<Long?>(null) }

    // Step 1: Type Selection
    var mType by remember { mutableStateOf("tablet") } // tablet, syrup, ointment, injection, other
    var isSuggestionSelected by remember { mutableStateOf(false) }

    // Step 2: Info
    var name by remember { mutableStateOf("") }
    var dosageStrength by remember { mutableStateOf("") }
    var company by remember { mutableStateOf("") }
    var generic by remember { mutableStateOf("") }
    var barcode by remember { mutableStateOf(initialBarcode) }
    
    // Expiry Date states (Year and Month manually selected)
    val currentCalendar = remember { Calendar.getInstance() }
    val currentYearInt = currentCalendar.get(Calendar.YEAR)
    val currentMonthInt = currentCalendar.get(Calendar.MONTH) + 1
    var expYear by remember { mutableStateOf(currentYearInt.toString()) }
    var expMonth by remember { mutableStateOf(String.format(Locale.US, "%02d", currentMonthInt)) }

    // Step 3: Pricing
    var purchaseBoxStr by remember { mutableStateOf("0") }
    var saleBoxStr by remember { mutableStateOf("0") }
    var profitPercentBoxStr by remember { mutableStateOf("") }
    var purchaseUnitStr by remember { mutableStateOf("0") }
    var saleUnitStr by remember { mutableStateOf("0") }
    var profitPercentUnitStr by remember { mutableStateOf("") }
    var strPerBoxStr by remember { mutableStateOf("10") }
    var pcsPerStrStr by remember { mutableStateOf("10") }

    // Step 4: Stock Info Setup
    var nowBoxesText by remember { mutableStateOf("0") }
    var nowStripsText by remember { mutableStateOf("0") }
    var nowPcsText by remember { mutableStateOf("0") }
    var mlConBotText by remember { mutableStateOf("100") }
    var botStockText by remember { mutableStateOf("0") }
    var gmConTubText by remember { mutableStateOf("15") }
    var tubStockText by remember { mutableStateOf("0") }
    var vialStockText by remember { mutableStateOf("0") }
    var othConQtyText by remember { mutableStateOf("0") }
    var othConUnitText by remember { mutableStateOf("পিস") }
    var lowStockThresholdValueStr by remember { mutableStateOf("10") }
    var lowStockThresholdUnit by remember { mutableStateOf("pieces") } // "pieces", "strips", "boxes", "bottles", "tubes", "vials", "other"

    val matchedExisting = remember(name, dosageStrength, barcode, mType, existingMedicines) {
        val cleanName = name.trim()
        val cleanDose = dosageStrength.trim()
        val cleanBarcode = barcode.trim()
        
        if (cleanName.isBlank() && cleanBarcode.isBlank()) {
            null
        } else {
            existingMedicines.find { ext ->
                val nameMatch = cleanName.isNotBlank() && ext.name.equals(cleanName, ignoreCase = true) && ext.dosageStrength.equals(cleanDose, ignoreCase = true) && ext.type.equals(mType, ignoreCase = true)
                val barcodeMatch = cleanBarcode.isNotBlank() && ext.barcode.isNotBlank() && ext.barcode == cleanBarcode
                nameMatch || barcodeMatch
            }
        }
    }

    LaunchedEffect(mType) {
        if (matchedExisting == null) {
            when (mType) {
                "tablet" -> {
                    lowStockThresholdValueStr = "5"
                    lowStockThresholdUnit = "strips"
                }
                "syrup" -> {
                    lowStockThresholdValueStr = "5"
                    lowStockThresholdUnit = "bottles"
                }
                "ointment" -> {
                    lowStockThresholdValueStr = "5"
                    lowStockThresholdUnit = "tubes"
                }
                "injection" -> {
                    lowStockThresholdValueStr = "5"
                    lowStockThresholdUnit = "vials"
                }
                else -> {
                    lowStockThresholdValueStr = "5"
                    lowStockThresholdUnit = "other"
                }
            }
        }
    }

    LaunchedEffect(matchedExisting) {
        if (matchedExisting != null) {
            if (autoFilledForId != matchedExisting.id) {
                autoFilledForId = matchedExisting.id
                name = matchedExisting.name
                dosageStrength = matchedExisting.dosageStrength
                company = matchedExisting.company
                generic = matchedExisting.genericName
                barcode = matchedExisting.barcode
                mType = matchedExisting.type
                
                // Parse expiry date if formatted as YYYY-MM-DD
                val parts = matchedExisting.expiryDate.split("-")
                if (parts.size >= 2) {
                    expYear = parts[0]
                    expMonth = parts[1]
                }
                
                purchaseBoxStr = matchedExisting.purchasePriceBox.toString()
                saleBoxStr = matchedExisting.salePriceBox.toString()
                strPerBoxStr = matchedExisting.stripsPerBox.toString()
                pcsPerStrStr = matchedExisting.pcsPerStrip.toString()
                
                // Recalculate profit percent
                if (matchedExisting.purchasePriceBox > 0.0) {
                    val pct = ((matchedExisting.salePriceBox - matchedExisting.purchasePriceBox) / matchedExisting.purchasePriceBox) * 100.0
                    profitPercentBoxStr = String.format(Locale.US, "%.1f", pct)
                } else {
                    profitPercentBoxStr = ""
                }
                
                purchaseUnitStr = matchedExisting.purchasePriceUnit.toString()
                saleUnitStr = matchedExisting.salePriceUnit.toString()
                
                // Recalculate profit percent unit
                if (matchedExisting.purchasePriceUnit > 0.0) {
                    val pct = ((matchedExisting.salePriceUnit - matchedExisting.purchasePriceUnit) / matchedExisting.purchasePriceUnit) * 100.0
                    profitPercentUnitStr = String.format(Locale.US, "%.1f", pct)
                } else {
                    profitPercentUnitStr = ""
                }
                
                mlConBotText = matchedExisting.mlPerBottle.toString()
                gmConTubText = matchedExisting.gramsPerTube.toString()
                othConUnitText = matchedExisting.otherUnit
                
                val threshold = matchedExisting.lowStockThreshold
                if (matchedExisting.type == "tablet") {
                    val sPerBox = matchedExisting.stripsPerBox
                    val pPerStrip = matchedExisting.pcsPerStrip
                    val pcsPerBox = sPerBox * pPerStrip
                    if (pcsPerBox > 0 && threshold % pcsPerBox == 0) {
                        lowStockThresholdValueStr = (threshold / pcsPerBox).toString()
                        lowStockThresholdUnit = "boxes"
                    } else if (pPerStrip > 0 && threshold % pPerStrip == 0) {
                        lowStockThresholdValueStr = (threshold / pPerStrip).toString()
                        lowStockThresholdUnit = "strips"
                    } else {
                        lowStockThresholdValueStr = threshold.toString()
                        lowStockThresholdUnit = "pieces"
                    }
                } else {
                    lowStockThresholdValueStr = threshold.toString()
                    lowStockThresholdUnit = when (matchedExisting.type) {
                        "syrup" -> "bottles"
                        "ointment" -> "tubes"
                        "injection" -> "vials"
                        else -> "other"
                    }
                }
                
                // But stock fields reset to 0:
                nowBoxesText = "0"
                nowStripsText = "0"
                nowPcsText = "0"
                botStockText = "0"
                tubStockText = "0"
                vialStockText = "0"
                othConQtyText = "0"
                
                isSuggestionSelected = true
            }
        } else {
            autoFilledForId = null
        }
    }

    Dialog(onDismissRequest = onDismiss) {
        Card(
            colors = CardDefaults.cardColors(containerColor = DarkSurface),
            shape = RoundedCornerShape(16.dp),
            modifier = Modifier
                .fillMaxWidth()
                .fillMaxHeight(0.85f),
            border = BorderStroke(1.dp, DarkAccentRed.copy(alpha = 0.2f))
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(16.dp)
            ) {
                // Stepper Visualizer
                Text(
                    text = "${if (isBengali) "নতুন ওষুধ যোগ — ধাপ " else "Add Medicine — Step "}$step/৪",
                    color = DarkAccentGold,
                    fontWeight = FontWeight.Bold,
                    fontSize = 16.sp
                )
                Spacer(modifier = Modifier.height(12.dp))

                Column(modifier = Modifier.weight(1f).verticalScroll(rememberScrollState())) {
                    when (step) {
                        1 -> {
                            Text(if (isBengali) "ওষুধের ধরন নির্ধারণ করুন:" else "Select Medicine Type:", color = DarkTextPrimary, fontSize = 14.sp, modifier = Modifier.padding(bottom = 12.dp))
                            val typesList = listOf(
                                "tablet" to (if (isBengali) "💊 ট্যাবলেট / ক্যাপসুল" else "💊 Tablet/Capsule"),
                                "syrup" to (if (isBengali) "🧴 সিরাপ / ড্রপ" else "🧴 Syrup/Drop"),
                                "ointment" to (if (isBengali) "🟡 মলম / ক্রিম" else "🟡 Ointment/Cream"),
                                "injection" to (if (isBengali) "💉 ইনজেকশন " else "💉 Injection"),
                                "other" to (if (isBengali) "📦 অন্যান্য" else "📦 Other")
                            )
                            typesList.forEach { (key, titleText) ->
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 6.dp)
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(if (mType == key) DarkAccentRed else DarkBg)
                                        .clickable { 
                                            mType = key
                                            isSuggestionSelected = false
                                        }
                                        .padding(14.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    RadioButton(
                                        selected = mType == key,
                                        onClick = { 
                                            mType = key
                                            isSuggestionSelected = false
                                        },
                                        colors = RadioButtonDefaults.colors(selectedColor = if (mType == key) DarkAccentText else Color.White, unselectedColor = DarkTextSecondary)
                                    )
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text(titleText, color = if (mType == key) DarkAccentText else DarkTextPrimary, fontWeight = FontWeight.Bold)
                                }
                            }
                        }
                        2 -> {
                            Text(if (isBengali) "ওষুধের বিবরণ লিখুন:" else "Fill General Information:", color = DarkTextPrimary, fontSize = 14.sp, modifier = Modifier.padding(bottom = 12.dp))
                            OutlinedTextField(
                                value = name,
                                onValueChange = { 
                                    name = it
                                    isSuggestionSelected = false
                                },
                                label = { Text(if (isBengali) "ওষুধের নাম (ব্র্যান্ড যেমন: Seclo)" else "Medicine Name (Brand e.g. Seclo)") },
                                modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text)
                            )
                            
                            if (matchedExisting != null) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 4.dp)
                                        .background(Color.Green.copy(alpha = 0.15f), RoundedCornerShape(8.dp))
                                        .border(1.dp, Color.Green.copy(alpha = 0.5f), RoundedCornerShape(8.dp))
                                        .padding(8.dp)
                                ) {
                                    Text(
                                        text = if (isBengali) "✓ এই ওষুধটি ইতিমধ্যেই স্টকে আছে! পূর্ববর্তী তথ্য অটো-ফিল করা হয়েছে। নতুন স্টক সংখ্যা যোগ করুন।" 
                                               else "✓ Existing stock medicine found! Auto-filled metadata and prices. Add new stock.",
                                        color = Color.Green,
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold
                                    )
                                }
                            } else if (isSuggestionSelected) {
                                Text(
                                    text = if (isBengali) "✓ অটো-ফিল করা হয়েছে: $name ($dosageStrength)" else "✓ Auto-filled: $name ($dosageStrength)",
                                    color = Color.Green,
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    modifier = Modifier.padding(horizontal = 4.dp, vertical = 2.dp)
                                )
                            }
                            
                            // Auto-suggestions list underneath brand name field
                            val nameSuggestions = remember(name, mType, isSuggestionSelected) {
                                if (name.isBlank() || isSuggestionSelected || mType == "other") {
                                    emptyList()
                                } else {
                                    predefinedMedicineDatabase.filter {
                                        it.type.equals(mType, ignoreCase = true) &&
                                        it.name.contains(name, ignoreCase = true)
                                    }.take(4)
                                }
                            }
                            if (nameSuggestions.isNotEmpty()) {
                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 4.dp)
                                        .border(1.dp, SleekBorderColor, RoundedCornerShape(8.dp))
                                        .background(DarkSurface)
                                ) {
                                    Text(
                                        text = if (isBengali) "পরামর্শ তালিকা (স্পর্শ করে অটো-ফিল করুন):" else "Auto-fill suggestions (Tap to select):",
                                        color = DarkAccentGold,
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                                    )
                                    nameSuggestions.forEach { pred ->
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clickable {
                                                    name = pred.name
                                                    dosageStrength = pred.dose
                                                    company = pred.company
                                                    generic = pred.generic
                                                    mType = pred.type
                                                    pred.defaultStripsPerBox?.let { strPerBoxStr = it.toString() }
                                                    pred.defaultPcsPerStrip?.let { pcsPerStrStr = it.toString() }
                                                    pred.defaultMlPerBottle?.let { mlConBotText = it.toString() }
                                                    pred.defaultGramsPerTube?.let { gmConTubText = it.toString() }
                                                    isSuggestionSelected = true
                                                }
                                                .padding(horizontal = 12.dp, vertical = 8.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Column {
                                                Text(
                                                    text = "${pred.name} ${pred.dose}",
                                                    color = DarkTextPrimary,
                                                    fontSize = 13.sp,
                                                    fontWeight = FontWeight.Bold
                                                )
                                                Text(
                                                    text = "${pred.generic} | ${pred.company}",
                                                    color = DarkTextSecondary,
                                                    fontSize = 11.sp
                                                )
                                            }
                                            Text(
                                                text = pred.type.uppercase(),
                                                color = DarkAccentGold,
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold,
                                                modifier = Modifier
                                                    .border(1.dp, DarkAccentGold, RoundedCornerShape(4.dp))
                                                    .padding(horizontal = 4.dp, vertical = 2.dp)
                                            )
                                        }
                                        Divider(color = SleekBorderColor)
                                    }
                                }
                            }

                            OutlinedTextField(
                                value = dosageStrength,
                                onValueChange = { dosageStrength = it },
                                label = { Text(if (isBengali) "ডোজ/শক্তি (যেমন: 20mg, 40mg, 100ml)" else "Dosage/Strength (e.g. 20mg, 40mg, 100ml)") },
                                modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text)
                            )
                            OutlinedTextField(
                                value = company,
                                onValueChange = { company = it },
                                label = { Text(if (isBengali) "কোম্পানির নাম" else "Company Name") },
                                modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text)
                            )
                            OutlinedTextField(
                                value = generic,
                                onValueChange = { generic = it },
                                label = { Text(if (isBengali) "জেনেরিক নাম" else "Generic Name") },
                                modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text)
                            )
                            OutlinedTextField(
                                value = barcode,
                                onValueChange = { barcode = it },
                                label = { Text(if (isBengali) "বারকোড নম্বর" else "Barcode standard No.") },
                                modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                                textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text)
                            )
                            Text(
                                text = if (isBengali) "ওষুধের মেয়াদকাল নির্ধারণ করুন:" else "Set Expiry Date:",
                                color = DarkAccentGold,
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                modifier = Modifier.padding(top = 8.dp, bottom = 4.dp)
                            )
                            Row(
                                modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                // Month Selector
                                Box(modifier = Modifier.weight(1f)) {
                                    var showMonthMenu by remember { mutableStateOf(false) }
                                    val monthLabels = listOf(
                                        "01" to (if (isBengali) "জানুয়ারি (০১)" else "Jan (01)"),
                                        "02" to (if (isBengali) "ফেব্রুয়ারি (০২)" else "Feb (02)"),
                                        "03" to (if (isBengali) "মার্চ (০৩)" else "Mar (03)"),
                                        "04" to (if (isBengali) "এপ্রিল (০৪)" else "Apr (04)"),
                                        "05" to (if (isBengali) "মে (০৫)" else "May (05)"),
                                        "06" to (if (isBengali) "জুন (০৬)" else "Jun (06)"),
                                        "07" to (if (isBengali) "জুলাই (০৭)" else "Jul (07)"),
                                        "08" to (if (isBengali) "আগস্ট (০৮)" else "Aug (08)"),
                                        "09" to (if (isBengali) "সেপ্টেম্বর (০৯)" else "Sep (09)"),
                                        "10" to (if (isBengali) "অক্টোবর (১০)" else "Oct (10)"),
                                        "11" to (if (isBengali) "নভেম্বর (১১)" else "Nov (11)"),
                                        "12" to (if (isBengali) "ডিসেম্বর (১২)" else "Dec (12)")
                                    )
                                    val selectedMonthLabel = monthLabels.find { it.first == expMonth }?.second ?: expMonth

                                    OutlinedCard(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clickable { showMonthMenu = true },
                                        colors = CardDefaults.outlinedCardColors(containerColor = DarkBg),
                                        border = BorderStroke(1.dp, SleekBorderColor)
                                    ) {
                                        Row(
                                            modifier = Modifier.padding(horizontal = 12.dp, vertical = 14.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Column(modifier = Modifier.weight(1f)) {
                                                Text(if (isBengali) "মাস" else "Month", fontSize = 10.sp, color = DarkTextSecondary)
                                                Text(selectedMonthLabel, fontSize = 13.sp, color = DarkTextPrimary, fontWeight = FontWeight.Bold)
                                            }
                                            Icon(Icons.Default.ArrowDropDown, contentDescription = null, tint = DarkAccentGold)
                                        }
                                    }

                                    DropdownMenu(
                                        expanded = showMonthMenu,
                                        onDismissRequest = { showMonthMenu = false },
                                        modifier = Modifier.background(DarkSurface).border(1.dp, SleekBorderColor)
                                    ) {
