                                    text = "${if (isBengali) "ইউজারনেম:" else "Username:"} @${staff.username} | ${if (isBengali) "ফোন:" else "Phone:"} ${staff.phone}",
                                    color = DarkTextSecondary,
                                    fontSize = 12.sp
                                )
