                    Triple(if (isBengali) "আমার কার্ট" else "My Cart", Icons.Filled.ShoppingCart, Icons.Outlined.ShoppingCart),
                    Triple(if (isBengali) "অর্ডার ইতিহাস" else "Orders", Icons.Filled.ListAlt, Icons.Outlined.ListAlt),
                    Triple(if (isBengali) "নোটিফিকেশন" else "Notifications", Icons.Filled.Notifications, Icons.Outlined.Notifications),
                    Triple(if (isBengali) "সেটিংস" else "Settings", Icons.Filled.Settings, Icons.Outlined.Settings)
                )

                tabs.forEachIndexed { index, (label, filledIcon, outlinedIcon) ->
                    val finalLabel = if (index == 1) {
                        if (isBengali) "আমার কার্ট (${formatBengaliNumber(customerCart.size)})" else "My Cart (${customerCart.size})"
                    } else if (index == 2) {
                        val count = customerOrders.filter { it.customerUsername == currentUser.username }.size
                        if (isBengali) "অর্ডার হিস্ট্রি (${formatBengaliNumber(count)})" else "My Orders (${count})"
                    } else {
                        label
                    }
                    NavigationBarItem(
                        selected = activeTab == index,
                        onClick = { activeTab = index },
                        label = { Text(finalLabel, fontSize = 9.sp, fontWeight = FontWeight.Bold, maxLines = 1, overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis) },
                        icon = {
                            Box {
                                Icon(
                                    imageVector = if (activeTab == index) filledIcon else outlinedIcon,
                                    contentDescription = label
                                )
                                if (index == 3 && unreadNotifCount > 0) {
                                    Box(
                                        modifier = Modifier
                                            .align(Alignment.TopEnd)
                                            .offset(x = 6.dp, y = (-6).dp)
                                            .size(16.dp)
                                            .background(DarkAccentRed, androidx.compose.foundation.shape.CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(
                                            text = if (isBengali) formatBengaliNumber(unreadNotifCount) else unreadNotifCount.toString(),
                                            color = Color.White,
                                            fontSize = 9.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }
                        },
                        colors = NavigationBarItemDefaults.colors(
                            selectedIconColor = if (isDarkModeGlobal) Color.Black else Color.White,
                            unselectedIconColor = DarkTextSecondary.copy(alpha = 0.6f),
                            selectedTextColor = DarkTextPrimary,
                            unselectedTextColor = DarkTextSecondary.copy(alpha = 0.5f),
                            indicatorColor = DarkAccentRed
                        )
                    )
                }
            }
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .background(GlassBackgroundGradient)
        ) {
            // TAB PANELS INTERCHANGING
            if (activeTab == 0) {
                // PANEL 1: SELECTION & MEDICINE SEARCH MAP RETRIEVER
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(horizontal = 16.dp)
                ) {
                    Spacer(modifier = Modifier.height(10.dp))

                    // Consumer Location Status Card
                    val hasLocation = currentUser.isLocationSet || (userLatitude != null && userLatitude != 0.0)
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { showLocationSettingsDialog = true },
                        colors = CardDefaults.cardColors(
                            containerColor = if (hasLocation) Color(0xFF1E2620) else Color(0xFF261D1D)
                        ),
                        border = BorderStroke(1.dp, if (hasLocation) SuccessColor.copy(alpha = 0.5f) else DarkAccentGold.copy(alpha = 0.5f)),
                        shape = RoundedCornerShape(10.dp)
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 12.dp, vertical = 8.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.weight(1f)) {
                                Icon(
                                    imageVector = if (hasLocation) Icons.Filled.LocationOn else Icons.Filled.LocationOff,
                                    contentDescription = "Location",
                                    tint = if (hasLocation) SuccessColor else DarkAccentGold,
                                    modifier = Modifier.size(20.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Column {
                                    Text(
                                        text = if (hasLocation) {
                                            if (currentUser.address.isNotBlank()) currentUser.address
                                            else if (currentUser.ward.isNotBlank()) "${currentUser.ward}, ${currentUser.neighborhood}"
                                            else if (isBengali) "লাইভ GPS লোকেশন সক্রিয়" else "Live GPS Location Active"
                                        } else {
                                            if (isBengali) "লোকেশন সেট করা হয়নি" else "Location Not Set"
                                        },
                                        color = DarkTextPrimary,
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        maxLines = 1,
                                        overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                                    )
                                    Text(
                                        text = if (hasLocation) {
                                            if (isBengali) "আপনার নিজস্ব লোকেশন অনুযায়ী ফলাফল দেখানো হচ্ছে" else "Showing results based on your set location"
                                        } else {
                                            if (isBengali) "একাউন্টে লোকেশন সেট করুন (অন্য কোনো লোকেশন দেখানো হবে না)" else "Set your location in Account (no other location used)"
                                        },
                                        color = DarkTextSecondary,
                                        fontSize = 10.sp,
                                        maxLines = 1,
                                        overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                                    )
                                }
                            }
                            Spacer(modifier = Modifier.width(6.dp))
                            Box(
                                modifier = Modifier
                                    .background(
                                        if (hasLocation) SuccessColor.copy(alpha = 0.15f) else DarkAccentGold.copy(alpha = 0.15f),
                                        RoundedCornerShape(6.dp)
                                    )
                                    .padding(horizontal = 8.dp, vertical = 4.dp)
                            ) {
                                Text(
                                    text = if (hasLocation) (if (isBengali) "পরিবর্তন" else "Change") else (if (isBengali) "সেট করুন" else "Set"),
                                    color = if (hasLocation) Color(0xFF81C784) else DarkAccentGold,
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(10.dp))

                    OutlinedTextField(
                        value = searchQuery,
                        onValueChange = { searchQuery = it },
                        label = { Text(if (isBengali) "কাঙ্ক্ষিত ওষুধের নাম দিয়ে খুঁজুন..." else "Type medicine or chemical name...") },
                        leadingIcon = { Icon(Icons.Filled.ListAlt, contentDescription = "Search icon") },
                        textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                        modifier = Modifier.fillMaxWidth(),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = DarkAccentRed,
                            unfocusedBorderColor = DarkTextSecondary.copy(alpha = 0.5f),
                            focusedLabelColor = DarkAccentRed,
                            unfocusedLabelColor = DarkTextSecondary
                        ),
                        shape = RoundedCornerShape(12.dp)
                    )

                    Spacer(modifier = Modifier.height(10.dp))

                    if (searchQuery.trim().isEmpty()) {
                        Box(
                            modifier = Modifier
                                .weight(1f)
                                .fillMaxWidth()
                                .padding(24.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Column(
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.Search,
                                    contentDescription = "Search Prompt Icon",
                                    tint = DarkTextSecondary.copy(alpha = 0.6f),
                                    modifier = Modifier.size(64.dp)
                                )
                                Spacer(modifier = Modifier.height(12.dp))
                                Text(
                                    text = if (isBengali) "ওষুধের নাম বা জেনেরিক নাম লিখে খুঁজুন" else "Search medicines by name or generic formula",
                                    color = DarkTextSecondary,
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.Medium,
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                    } else {
                        LazyColumn(
                            modifier = Modifier.weight(1f),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            if (groupedMedicines.isEmpty()) {
                                item {
                                    Box(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(24.dp),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(
                                            text = if (isBengali) "দুঃখিত, কোনো ওষুধ খুঁজে পাওয়া যায়নি!" else "No matching items found!",
                                            color = DarkTextSecondary,
                                            fontSize = 14.sp
                                        )
                                    }
                                }
                            } else {
                                items(groupedMedicines.size) { index ->
                                    val medGroup = groupedMedicines[index]
                                    CustomerMedicineCard(
                                        medGroup = medGroup,
                                        isBengali = isBengali,
                                        userProfiles = userProfiles,
                                        currentLat = currentLat,
                                        currentLon = currentLon,
                                        onAddToCart = { targetMed ->
                                            medicineToAddToCart = targetMed
                                            addToCartQty = 1
                                            showAddToCartDialog = true
                                        },
                                        onOrderNow = { targetMed, targetPharmacy ->
                                            selectedLocatorMedicine = targetMed
                                            chosenPharmacyForOrder = targetPharmacy
                                            orderQuantity = 1
                                            showOrderDialog = true
                                        }
                                    )
                                }
                            }
                        }
                    }
                }
            } else if (activeTab == 1) {
                // PANEL 3: CUSTOMER CART VIEW
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(horizontal = 16.dp)
                ) {
                    Text(
                        text = if (isBengali) "আমার কার্ট তালিকা (ফার্মেসি অনুযায়ী বিভক্ত):" else "My Cart (Grouped by Sourced Pharmacies):",
                        color = DarkTextPrimary,
                        fontWeight = FontWeight.Bold,
                        fontSize = 14.sp
                    )
                    Spacer(modifier = Modifier.height(8.dp))

                    if (customerCart.isEmpty()) {
                        Box(
                            modifier = Modifier.weight(1f).fillMaxWidth(),
                            contentAlignment = Alignment.Center
                        ) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                Icon(
                                    imageVector = Icons.Filled.ShoppingCart,
                                    contentDescription = null,
                                    tint = DarkTextSecondary,
                                    modifier = Modifier.size(54.dp)
                                )
                                Spacer(modifier = Modifier.height(10.dp))
                                Text(
                                    text = if (isBengali) "আপনার কার্ট বর্তমানে খালি রয়েছে!\nওষুধের তালিকা থেকে ওষুধ কার্টে যুক্ত করুন।" else "Your cart is empty!\nAdd medicines from the search list.",
                                    color = DarkTextSecondary,
                                    fontSize = 13.sp,
                                    textAlign = androidx.compose.ui.text.style.TextAlign.Center
                                )
                            }
                        }
                    } else if (cartItemsGroupedByPharmacy.isEmpty()) {
                        Box(
                            modifier = Modifier.weight(1f).fillMaxWidth(),
                            contentAlignment = Alignment.Center
                        ) {
                            Column(
                                horizontalAlignment = Alignment.CenterHorizontally,
                                modifier = Modifier.padding(16.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.Warning,
                                    contentDescription = null,
                                    tint = DarkAccentRed,
                                    modifier = Modifier.size(54.dp)
                                )
                                Spacer(modifier = Modifier.height(10.dp))
                                Text(
                                    text = if (isBengali) 
                                        "আপনার কার্টের ওষুধগুলো বর্তমানে ডাটাবেজে পাওয়া যাচ্ছে না অথবা আউট অব স্টক রয়েছে!\nঅনুগ্রহ করে কার্ট খালি করে আবার নতুন ওষুধ যুক্ত করুন।"
                                    else 
                                        "The medicines in your cart are currently not found in the database or are out of stock!\nPlease clear your cart and add them again.",
                                    color = DarkTextSecondary,
                                    fontSize = 13.sp,
                                    textAlign = androidx.compose.ui.text.style.TextAlign.Center
                                )
                                Spacer(modifier = Modifier.height(16.dp))
                                Button(
                                    onClick = {
                                        viewModel.clearCustomerCart()
                                    },
                                    colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed),
                                    shape = RoundedCornerShape(8.dp)
                                ) {
                                    Text(
                                        text = if (isBengali) "কার্ট খালি করুন" else "Clear Cart",
                                        color = Color.White,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 13.sp
                                    )
                                }
                            }
                        }
                    } else {
                        var expandedPharmacyMapName by remember { mutableStateOf<String?>(null) }

                        val sortedGroupedCart = remember(cartItemsGroupedByPharmacy, isSharingLocation, userLatitude, userLongitude) {
                            cartItemsGroupedByPharmacy.toList().sortedWith(
                                compareByDescending<Pair<SimulatedPharmacy, List<Pair<Medicine, Int>>>> { (pharmacy, items) ->
                                    val isFullySatisfied = items.all { (med, qty) ->
                                        val stock = when (med.type) {
                                            "tablet" -> med.totalPiecesInStock
                                            "syrup" -> med.bottlesInStock
                                            "ointment" -> med.tubesInStock
                                            "injection" -> med.vialsInStock
                                            else -> med.otherQuantity.toInt()
                                        }
                                        stock >= qty
                                    }
                                    isFullySatisfied
                                }.thenBy { (pharmacy, _) ->
                                    calculateDiffDistance(pharmacy.lat, pharmacy.lLng) ?: 999999.0
                                }
                            )
                        }

                        LazyColumn(
                            modifier = Modifier.weight(1f),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {

                            sortedGroupedCart.forEach { (pharmacy, items) ->
                                val pharmacyDistance = calculateDiffDistance(pharmacy.lat, pharmacy.lLng)

                                val isMapOpen = expandedPharmacyMapName == pharmacy.name

                                val pharmacyAllInStock = items.all { (med, qty) ->
                                    val stock = when (med.type) {
                                        "tablet" -> med.totalPiecesInStock
                                        "syrup" -> med.bottlesInStock
                                        "ointment" -> med.tubesInStock
                                        "injection" -> med.vialsInStock
                                        else -> med.otherQuantity.toInt()
                                    }
                                    stock >= qty
                                }

                                item {
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        colors = CardDefaults.cardColors(containerColor = DarkSurface),
                                        border = BorderStroke(1.5.dp, SuccessColor.copy(alpha = 0.3f)),
                                        shape = RoundedCornerShape(14.dp)
                                    ) {
                                        Column(modifier = Modifier.padding(14.dp)) {
                                            // Pharmacy Header
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.Top
                                            ) {
                                                Column(modifier = Modifier.weight(0.7f)) {
                                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                                        Box(
                                                            modifier = Modifier
                                                                .size(10.dp)
                                                                .background(if (pharmacyAllInStock) SuccessColor else DarkAccentRed, RoundedCornerShape(50.dp))
                                                        )
                                                        Spacer(modifier = Modifier.width(6.dp))
                                                        Text(
                                                            text = if (isBengali) pharmacy.name else pharmacy.nameEn,
                                                            color = DarkTextPrimary,
                                                            fontWeight = FontWeight.Bold,
                                                            fontSize = 14.sp
                                                        )
                                                        Spacer(modifier = Modifier.width(8.dp))
                                                        Box(
                                                            modifier = Modifier
                                                                .background(
                                                                    color = if (pharmacyAllInStock) SuccessColor.copy(alpha = 0.15f) else DarkAccentRed.copy(alpha = 0.15f),
                                                                    shape = RoundedCornerShape(4.dp)
                                                                )
                                                                .padding(horizontal = 6.dp, vertical = 2.dp)
                                                        ) {
                                                            Text(
                                                                text = if (pharmacyAllInStock) {
                                                                    if (isBengali) "পূর্ণ স্টক" else "Full Stock"
                                                                } else {
                                                                    if (isBengali) "কম স্টক" else "Low Stock"
                                                                },
                                                                color = if (pharmacyAllInStock) SuccessColor else DarkAccentRed,
                                                                fontSize = 9.sp,
                                                                fontWeight = FontWeight.Bold
                                                            )
                                                        }
                                                    }
                                                    Text(
                                                        text = if (isBengali) pharmacy.description else pharmacy.descriptionEn,
                                                        color = DarkTextSecondary,
                                                        fontSize = 11.sp
                                                    )
                                                }
                                                Column(horizontalAlignment = Alignment.End) {
                                                    if (pharmacyDistance != null) {
                                                        Text(
                                                            text = "${if (isBengali) "দূরত্ব: " else "Dist: "}${formatBengaliNumber(String.format("%.2f", pharmacyDistance))} কি.মি.",
                                                            color = InfoColor,
                                                            fontWeight = FontWeight.Bold,
                                                            fontSize = 12.sp
                                                        )
                                                    } else {
                                                        Text(
                                                            text = if (isBengali) "দূরত্ব: সেট নেই" else "Dist: Not set",
                                                            color = DarkTextSecondary.copy(alpha = 0.7f),
                                                            fontSize = 11.sp
                                                        )
                                                    }
                                                }
                                            }

                                            Spacer(modifier = Modifier.height(8.dp))
                                            Divider(color = Color.White.copy(alpha = 0.05f))
                                            Spacer(modifier = Modifier.height(8.dp))

                                            // Medicines from this pharmacy
                                            items.forEach { (med, qty) ->
                                                val stock = when (med.type) {
                                                    "tablet" -> med.totalPiecesInStock
                                                    "syrup" -> med.bottlesInStock
                                                    "ointment" -> med.tubesInStock
                                                    "injection" -> med.vialsInStock
                                                    else -> med.otherQuantity.toInt()
                                                }
                                                val hasEnoughStock = stock >= qty

                                                Row(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .padding(vertical = 4.dp),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Column(modifier = Modifier.weight(0.7f)) {
                                                        Text(
                                                            text = med.name + (if (med.dosageStrength.isNotEmpty()) " ${med.dosageStrength}" else ""),
                                                            color = DarkTextPrimary,
                                                            fontWeight = FontWeight.Medium,
                                                            fontSize = 13.sp
                                                        )
                                                        Text(
                                                            text = "${if (isBengali) "পরিমাণ: " else "Qty: "}${med.formatQuantityString(qty, isBengali)}",
                                                            color = DarkTextSecondary,
                                                            fontSize = 11.sp
                                                        )

                                                        // Stock availability status message
                                                        if (!hasEnoughStock) {
                                                            Text(
                                                                text = if (isBengali) "[ স্টকে আছে ${med.formatQuantityString(stock, isBengali)} ]" else "[ In stock: ${med.formatQuantityString(stock, isBengali)} ]",
                                                                color = DarkAccentRed,
                                                                fontSize = 10.5.sp,
                                                                fontWeight = FontWeight.Bold
                                                            )
                                                        }

                                                        val priceHint = if (med.type == "tablet") {
                                                            if (isBengali) {
                                                                "বক্স: ৳${formatBengaliNumber(String.format("%.1f", med.salePriceBox))} | পাতা: ৳${formatBengaliNumber(String.format("%.1f", med.salePriceStrip))} | পিস: ৳${formatBengaliNumber(String.format("%.1f", med.salePricePiece))}"
                                                            } else {
                                                                "Box: ৳${String.format("%.1f", med.salePriceBox)} | Strip: ৳${String.format("%.1f", med.salePriceStrip)} | Pc: ৳${String.format("%.1f", med.salePricePiece)}"
                                                            }
                                                        } else {
                                                            if (isBengali) {
                                                                "৳${formatBengaliNumber(String.format("%.1f", med.salePriceUnit))} / পিস"
                                                            } else {
                                                                "৳${String.format("%.1f", med.salePriceUnit)} / Pc"
                                                            }
                                                        }
                                                        Text(
                                                            text = priceHint,
                                                            color = DarkTextSecondary.copy(alpha = 0.7f),
                                                            fontSize = 10.sp
                                                        )
                                                    }
                                                    Row(
                                                        verticalAlignment = Alignment.CenterVertically,
                                                        modifier = Modifier.weight(0.3f),
                                                        horizontalArrangement = Arrangement.End
                                                    ) {
                                                        Text(
                                                            text = "৳${formatBengaliNumber(String.format("%.1f", med.calculatePriceForQuantity(qty)))}",
                                                            color = DarkAccentGold,
                                                            fontWeight = FontWeight.Bold,
                                                            fontSize = 13.sp
                                                        )
                                                        Spacer(modifier = Modifier.width(8.dp))
                                                        IconButton(
                                                            onClick = {
                                                                // Remove all cart entries matching this name and dosage strength
                                                                val matchingCartIds = customerCart.keys.filter { cartId ->
                                                                    val m = medicines.find { it.id == cartId }
                                                                    m != null && m.name.equals(med.name, ignoreCase = true) && m.dosageStrength.equals(med.dosageStrength, ignoreCase = true)
                                                                }
                                                                matchingCartIds.forEach { id ->
                                                                    viewModel.removeFromCustomerCart(id)
                                                                }
                                                            },
                                                            modifier = Modifier.size(24.dp)
                                                        ) {
                                                            Icon(Icons.Filled.Delete, contentDescription = "Remove", tint = DarkAccentRed, modifier = Modifier.size(16.dp))
                                                        }
                                                    }
                                                }
                                            }

                                            Spacer(modifier = Modifier.height(8.dp))
                                            Divider(color = Color.White.copy(alpha = 0.05f))
                                            Spacer(modifier = Modifier.height(8.dp))

                                            // Subtotal for this pharmacy
                                            val groupTotal = items.sumOf { (med, qty) -> med.calculatePriceForQuantity(qty) }
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Text(
                                                    text = if (isBengali) "ফার্মেসির মোট বিল:" else "Pharmacy Subtotal:",
                                                    color = DarkTextPrimary,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 13.sp
                                                )
                                                Text(
                                                    text = "৳${formatBengaliNumber(String.format("%.1f", groupTotal))}",
                                                    color = DarkAccentGold,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 15.sp
                                                )
                                            }

                                            Spacer(modifier = Modifier.height(12.dp))

                                            // Pharmacy Map Toggle & Online Order Button Row
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                                            ) {
                                                // Map Toggle
                                                OutlinedButton(
                                                    onClick = {
                                                        expandedPharmacyMapName = if (isMapOpen) null else pharmacy.name
                                                    },
                                                    border = BorderStroke(1.dp, InfoColor.copy(alpha = 0.5f)),
                                                    colors = ButtonDefaults.outlinedButtonColors(contentColor = InfoColor),
                                                    shape = RoundedCornerShape(8.dp),
                                                    modifier = Modifier.weight(1f).height(32.dp),
                                                    contentPadding = PaddingValues(0.dp)
                                                ) {
                                                    Icon(Icons.Filled.LocationOn, contentDescription = null, modifier = Modifier.size(14.dp))
                                                    Spacer(modifier = Modifier.width(4.dp))
                                                    Text(
                                                        text = if (isMapOpen) {
                                                            if (isBengali) "ম্যাপ লুকান" else "Hide Map"
                                                        } else {
                                                            if (isBengali) "লোকেশন ম্যাপ" else "View Location"
                                                        },
                                                        fontSize = 11.sp,
                                                        fontWeight = FontWeight.Bold
                                                    )
                                                }

                                                // Online Order Placer
                                                Button(
                                                    onClick = {
                                                        viewModel.placeGroupedOrder(items, if (isBengali) pharmacy.name else pharmacy.nameEn)
                                                        android.widget.Toast.makeText(
                                                            context,
                                                            if (isBengali) "অনলাইন অর্ডারটি সফলভাবে সম্পন্ন হয়েছে!" else "Online order placed successfully!",
                                                            android.widget.Toast.LENGTH_LONG
                                                        ).show()
                                                    },
                                                    colors = ButtonDefaults.buttonColors(containerColor = SuccessColor, contentColor = Color.White),
                                                    shape = RoundedCornerShape(8.dp),
                                                    modifier = Modifier.weight(1.2f).height(32.dp),
                                                    contentPadding = PaddingValues(0.dp)
                                                ) {
                                                    Icon(Icons.Filled.Check, contentDescription = null, modifier = Modifier.size(14.dp))
                                                    Spacer(modifier = Modifier.width(4.dp))
                                                    Text(
                                                        text = if (isBengali) "অনলাইন অর্ডার করুন" else "Order Online",
                                                        fontSize = 11.sp,
                                                        fontWeight = FontWeight.Bold
                                                    )
                                                }
                                            }

                                            // Map section
                                            if (isMapOpen) {
                                                Spacer(modifier = Modifier.height(12.dp))
                                                if (currentLat != null && currentLon != null) {
                                                    Card(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .height(130.dp),
                                                        colors = CardDefaults.cardColors(containerColor = DarkBg),
                                                        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.05f)),
                                                        shape = RoundedCornerShape(8.dp)
                                                    ) {
                                                        Canvas(modifier = Modifier.fillMaxSize()) {
                                                            val w = size.width
                                                            val h = size.height

                                                            // Draw simulated map streets grid
                                                            val colGrid = Color(0xFF303030)
                                                            for (x in 0..w.toInt() step 30) {
                                                                drawLine(colGrid, start = androidx.compose.ui.geometry.Offset(x.toFloat(), 0f), end = androidx.compose.ui.geometry.Offset(x.toFloat(), h))
                                                            }
                                                            for (y in 0..h.toInt() step 30) {
                                                                drawLine(colGrid, start = androidx.compose.ui.geometry.Offset(0f, y.toFloat()), end = androidx.compose.ui.geometry.Offset(w, y.toFloat()))
                                                            }

                                                            // Draw major roads
                                                            drawLine(Color(0xFF4E3629), start = androidx.compose.ui.geometry.Offset(0f, h/2), end = androidx.compose.ui.geometry.Offset(w, h/2), strokeWidth = 6f)
                                                            drawLine(Color(0xFF4E3629), start = androidx.compose.ui.geometry.Offset(w/2, 0f), end = androidx.compose.ui.geometry.Offset(w/2, h), strokeWidth = 6f)

                                                            // User Marker (Blue)
                                                            val centerOffset = androidx.compose.ui.geometry.Offset(w/2, h/2)
                                                            drawCircle(InfoColor.copy(alpha = 0.2f), radius = 20f, center = centerOffset)
                                                            drawCircle(InfoColor, radius = 4f, center = centerOffset)

                                                            // Pharmacy Marker (Green)
                                                            val latDiff = pharmacy.lat - currentLat
                                                            val lngDiff = pharmacy.lLng - currentLon
                                                            val pX = (w / 2) + (lngDiff * 4000).toFloat().coerceIn(-w/2 + 20f, w/2 - 20f)
                                                            val pY = (h / 2) - (latDiff * 4000).toFloat().coerceIn(-h/2 + 20f, h/2 - 20f)
                                                            val pOffset = androidx.compose.ui.geometry.Offset(pX, pY)

                                                            drawLine(InfoColor, start = centerOffset, end = pOffset, strokeWidth = 2f, pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(5f, 5f), 0f))
                                                            drawCircle(SuccessColor.copy(alpha = 0.3f), radius = 12f, center = pOffset)
                                                            drawCircle(SuccessColor, radius = 5f, center = pOffset)
                                                        }
                                                    }
                                                } else {
                                                    Card(
                                                        modifier = Modifier.fillMaxWidth(),
                                                        colors = CardDefaults.cardColors(containerColor = DarkBg),
                                                        border = BorderStroke(1.dp, DarkAccentGold.copy(alpha = 0.3f)),
                                                        shape = RoundedCornerShape(8.dp)
                                                    ) {
                                                        Column(
                                                            modifier = Modifier
                                                                .fillMaxWidth()
                                                                .padding(14.dp),
                                                            horizontalAlignment = Alignment.CenterHorizontally
                                                        ) {
                                                            Icon(Icons.Filled.LocationOff, null, tint = DarkAccentGold, modifier = Modifier.size(24.dp))
                                                            Spacer(modifier = Modifier.height(4.dp))
                                                            Text(
                                                                text = if (isBengali) "একাউন্টে কোনো লোকেশন সেট নেই" else "Location not set in Account",
                                                                color = DarkTextPrimary,
                                                                fontWeight = FontWeight.Bold,
                                                                fontSize = 12.sp
                                                            )
                                                            Text(
                                                                text = if (isBengali) "ম্যাপে দূরত্ব ও সঠিক রুট দেখতে সেটিংসে গিয়ে নিজের লোকেশন সেট করুন।" else "Set your location in Settings to view route and distance on map.",
                                                                color = DarkTextSecondary,
                                                                fontSize = 10.5.sp,
                                                                textAlign = TextAlign.Center
                                                            )
                                                            Spacer(modifier = Modifier.height(8.dp))
                                                            Button(
                                                                onClick = { showLocationSettingsDialog = true },
                                                                colors = ButtonDefaults.buttonColors(containerColor = DarkAccentGold, contentColor = Color.Black),
                                                                shape = RoundedCornerShape(8.dp),
                                                                contentPadding = PaddingValues(horizontal = 14.dp, vertical = 4.dp),
                                                                modifier = Modifier.height(34.dp)
                                                            ) {
                                                                Text(if (isBengali) "📍 লোকেশন সেট করুন" else "📍 Set Location", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else if (activeTab == 2) {
                // PANEL 2: COMPLETED ORDER HISTORIES
                val userOrders = customerOrders.filter { it.customerUsername == currentUser.username }

                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(horizontal = 16.dp)
                ) {
                    Text(
                        text = if (isBengali) "আমার অতীত ও বর্তমান অর্ডারসমূহ:" else "History of Placed Orders:",
                        color = DarkTextPrimary,
                        fontWeight = FontWeight.Bold,
                        fontSize = 14.sp
                    )
                    Spacer(modifier = Modifier.height(8.dp))

                    LazyColumn(
                        modifier = Modifier.weight(1f),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        if (userOrders.isEmpty()) {
                            item {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(40.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = if (isBengali) "আপনি এখনও কোনো ওষুধের অর্ডার করেননি!" else "No placed orders found! Search medicines and tap order.",
                                        color = DarkTextSecondary,
                                        fontSize = 13.sp,
                                        textAlign = androidx.compose.ui.text.style.TextAlign.Center
                                    )
                                }
                            }
                        } else {
                            items(userOrders.size) { index ->
                                val ord = userOrders[index]

                                val statusColor = when (ord.status) {
                                    "Confirmed" -> SuccessColor
                                    "Cancelled" -> DarkAccentRed
                                    else -> WarningColor // Pending
                                }

                                val displayedStatusStr = when (ord.status) {
                                    "Confirmed" -> if (isBengali) "নিশ্চিত" else "Confirmed"
                                    "Cancelled" -> if (isBengali) "বাতিল" else "Cancelled"
                                    else -> if (isBengali) "অপেক্ষমাণ" else "Pending"
                                }

                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    colors = CardDefaults.cardColors(containerColor = DarkSurface),
                                    border = BorderStroke(1.dp, Color.White.copy(alpha = 0.05f)),
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Column(modifier = Modifier.padding(14.dp)) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.Top
                                        ) {
                                            Column {
                                                Text(
                                                    text = ord.medicineName,
                                                    color = DarkTextPrimary,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 15.sp
                                                )
                                                Text(
                                                    text = "${if (isBengali) "ফার্মেসি: " else "Pharmacy: "}${ord.pharmacyName}",
                                                    color = InfoColor,
                                                    fontSize = 12.sp,
                                                    fontWeight = FontWeight.Medium
                                                )
                                                Text(
                                                    text = "${if (isBengali) "তারিখ: " else "Date: "}${ord.dateString}",
                                                    color = DarkTextSecondary,
                                                    fontSize = 11.sp
                                                )
                                            }

                                            Box(
                                                modifier = Modifier
                                                    .background(statusColor.copy(alpha = 0.15f), RoundedCornerShape(4.dp))
                                                    .padding(horizontal = 8.dp, vertical = 4.dp)
                                            ) {
                                                Text(
                                                    text = displayedStatusStr,
                                                    color = statusColor,
                                                    fontSize = 11.sp,
                                                    fontWeight = FontWeight.Bold
                                                )
                                            }
                                        }

                                        Spacer(modifier = Modifier.height(10.dp))
                                        Divider(color = Color.White.copy(alpha = 0.05f))
                                        Spacer(modifier = Modifier.height(8.dp))

                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = "${if (isBengali) "পরিমাণ: " else "Qty: "}${formatBengaliNumber(ord.quantity)} পিস",
                                                color = DarkTextSecondary,
                                                fontSize = 12.sp
                                            )
                                            
                                            Text(
                                                text = "৳${formatBengaliNumber(String.format("%.1f", ord.totalPrice))}",
                                                color = DarkAccentGold,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 14.sp
                                            )
                                        }

                                        // Cancel order if Pending
                                        if (ord.status == "Pending") {
                                            Spacer(modifier = Modifier.height(10.dp))
                                            OutlinedButton(
                                                onClick = {
                                                    viewModel.deleteCustomerOrder(ord)
                                                    android.widget.Toast.makeText(context, if (isBengali) "অর্ডারটি সফলভাবে বাতিল করা হয়েছে!" else "Order has been cancelled!", android.widget.Toast.LENGTH_SHORT).show()
                                                },
                                                border = BorderStroke(1.dp, DarkAccentRed.copy(alpha = 0.3f)),
                                                colors = ButtonDefaults.outlinedButtonColors(contentColor = DarkAccentRed),
                                                shape = RoundedCornerShape(8.dp),
                                                modifier = Modifier.fillMaxWidth().height(32.dp),
                                                contentPadding = PaddingValues(0.dp)
                                            ) {
                                                Text(
                                                    text = if (isBengali) "অর্ডার বাতিল করুন" else "Cancel Order Request",
                                                    fontSize = 11.sp,
                                                    fontWeight = FontWeight.Bold
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else if (activeTab == 3) {
                NotificationsScreen(viewModel = viewModel, isBengali = isBengali)
            } else {
                AccountScreenForCustomer(viewModel = viewModel, isBengali = isBengali)
            }
        }
    }

    // CONFIRM MEDICINE ORDERING DIALOG DIALOGUE
    if (showOrderDialog && chosenPharmacyForOrder != null && selectedLocatorMedicine != null) {
        val med = selectedLocatorMedicine!!
        val pharm = chosenPharmacyForOrder!!
        val unitPrice = med.salePriceUnit
        val calcTotalPrice = unitPrice * orderQuantity

        Dialog(onDismissRequest = { showOrderDialog = false }) {
            Card(
                colors = CardDefaults.cardColors(containerColor = DarkSurface),
                border = BorderStroke(1.dp, Color.White.copy(alpha = 0.1f)),
                shape = RoundedCornerShape(16.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp)
            ) {
                Column(modifier = Modifier.padding(18.dp)) {
                    Text(
                        text = if (isBengali) "📦 ওষুধ অর্ডারের বিবরণ" else "📦 Confirm Medicine Order",
                        color = DarkTextPrimary,
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold
                    )
                    Spacer(modifier = Modifier.height(12.dp))

                    Text(
                        text = "${if (isBengali) "ওষুধের নাম: " else "Medicine: "}${med.name}",
                        color = DarkTextPrimary,
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Medium
                    )
                    Text(
                        text = "${if (isBengali) "ফার্মেসি: " else "Pharmacy: "}${if (isBengali) pharm.name else pharm.nameEn}",
                        color = InfoColor,
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Medium
                    )
                    Text(
                        text = "${if (isBengali) "ইউনিট মূল্য: " else "Unit Price: "}৳${formatBengaliNumber(String.format("%.1f", unitPrice))}",
                        color = DarkTextSecondary,
                        fontSize = 12.sp
                    )

                    Spacer(modifier = Modifier.height(14.dp))
                    Divider(color = Color.White.copy(alpha = 0.05f))
                    Spacer(modifier = Modifier.height(14.dp))

                    // QUANTITY SELECTION ACTION ROW
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = if (isBengali) "অর্ডারের পরিমাণ:" else "Order Quantity:",
                            color = DarkTextPrimary,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold
                        )

                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Button(
                                onClick = { if (orderQuantity > 1) orderQuantity-- },
                                colors = ButtonDefaults.buttonColors(containerColor = Color.White.copy(alpha = 0.1f)),
                                modifier = Modifier.size(32.dp),
                                contentPadding = PaddingValues(0.dp),
                                shape = RoundedCornerShape(4.dp)
                            ) {
                                Text("-", color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 16.sp)
                            }

                            Text(
                                text = formatBengaliNumber(orderQuantity),
                                modifier = Modifier.padding(horizontal = 14.dp),
                                color = DarkTextPrimary,
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp
                            )

                            Button(
                                onClick = { if (orderQuantity < 100) orderQuantity++ },
                                colors = ButtonDefaults.buttonColors(containerColor = Color.White.copy(alpha = 0.1f)),
                                modifier = Modifier.size(32.dp),
                                contentPadding = PaddingValues(0.dp),
                                shape = RoundedCornerShape(4.dp)
                            ) {
                                Text("+", color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 16.sp)
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = if (isBengali) "সর্বমোট মূল্য:" else "Total Price:",
                            color = DarkTextPrimary,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold
                        )
                        Text(
                            text = "৳${formatBengaliNumber(String.format("%.1f", calcTotalPrice))}",
                            color = DarkAccentGold,
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }

                    Spacer(modifier = Modifier.height(20.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.End
                    ) {
                        OutlinedButton(
                            onClick = { showOrderDialog = false },
                            border = BorderStroke(1.dp, Color.White.copy(alpha = 0.2f)),
                            colors = ButtonDefaults.outlinedButtonColors(contentColor = DarkTextSecondary),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.height(36.dp)
                        ) {
                            Text(if (isBengali) "বাতিল" else "Cancel", fontSize = 12.sp)
                        }

                        Spacer(modifier = Modifier.width(10.dp))

                        Button(
                            onClick = {
                                viewModel.placeOrder(
                                    medicine = med,
                                    qty = orderQuantity,
                                    pharmacyName = if (isBengali) pharm.name else pharm.nameEn,
                                    totalPrice = calcTotalPrice
                                )
                                showOrderDialog = false
                                android.widget.Toast.makeText(
                                    context,
                                    if (isBengali) "অর্ডার সফল হয়েছে! আপনার হিস্ট্রিতে দেখতে পাবেন।" else "Order placed successfully! Verified in history.",
                                    android.widget.Toast.LENGTH_LONG
                                ).show()
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = SuccessColor, contentColor = Color.White),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.height(36.dp)
                        ) {
                            Text(if (isBengali) "অর্ডার নিশ্চিত করুন" else "Place Order", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }
    }

    // ADD TO CART QUANTITY SELECTION DIALOG
    if (showAddToCartDialog && medicineToAddToCart != null) {
        val med = medicineToAddToCart!!
        val unitPrice = med.salePriceUnit

        var boxesSelected by remember(med.id) { mutableStateOf(0) }
        var stripsSelected by remember(med.id) { mutableStateOf(0) }
        var piecesSelected by remember(med.id) { mutableStateOf(1) } // Default to 1 piece

        val totalQtySelected = if (med.type == "tablet") {
            val pcsPerBox = med.stripsPerBox * med.pcsPerStrip
            (boxesSelected * pcsPerBox) + (stripsSelected * med.pcsPerStrip) + piecesSelected
        } else {
            addToCartQty
        }

        val calcTotalPrice = if (med.type == "tablet") {
            (boxesSelected * med.salePriceBox) + (stripsSelected * med.salePriceStrip) + (piecesSelected * med.salePricePiece)
        } else {
            unitPrice * addToCartQty
        }

        Dialog(onDismissRequest = { showAddToCartDialog = false }) {
            Card(
                colors = CardDefaults.cardColors(containerColor = DarkSurface),
                border = BorderStroke(1.dp, Color.White.copy(alpha = 0.1f)),
                shape = RoundedCornerShape(16.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp)
            ) {
                Column(modifier = Modifier.padding(18.dp)) {
                    Text(
                        text = if (isBengali) "🛒 কার্টে ওষুধ যুক্ত করুন" else "🛒 Add Medicine to Cart",
                        color = DarkTextPrimary,
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold
                    )
                    Spacer(modifier = Modifier.height(12.dp))

                    Text(
                        text = "${if (isBengali) "ওষুধের নাম: " else "Medicine: "}${med.name}",
                        color = DarkTextPrimary,
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Medium
                    )
                    val sourcePharmacy = getPharmacyForMedicine(med)
                    Text(
                        text = "${if (isBengali) "উৎস ফার্মেসি: " else "Sourced Pharmacy: "}${if (isBengali) sourcePharmacy.name else sourcePharmacy.nameEn}",
                        color = InfoColor,
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Medium
                    )
                    
                    val priceLabel = if (med.type == "tablet") {
                        if (isBengali) {
                            "বক্স: ৳${formatBengaliNumber(String.format("%.1f", med.salePriceBox))} | পাতা: ৳${formatBengaliNumber(String.format("%.1f", med.salePriceStrip))} | পিস: ৳${formatBengaliNumber(String.format("%.1f", med.salePricePiece))}"
                        } else {
                            "Box: ৳${String.format("%.1f", med.salePriceBox)} | Strip: ৳${String.format("%.1f", med.salePriceStrip)} | Pc: ৳${String.format("%.1f", med.salePricePiece)}"
                        }
                    } else {
                        "${if (isBengali) "ইউনিট মূল্য: " else "Unit Price: "}৳${formatBengaliNumber(String.format("%.1f", unitPrice))}"
                    }
                    Text(
                        text = priceLabel,
                        color = DarkTextSecondary,
                        fontSize = 12.sp
                    )

                    Spacer(modifier = Modifier.height(14.dp))
                    Divider(color = Color.White.copy(alpha = 0.05f))
                    Spacer(modifier = Modifier.height(14.dp))

                    if (med.type == "tablet") {
                        // Display packing info
                        Card(
                            colors = CardDefaults.cardColors(containerColor = DarkBg),
                            border = BorderStroke(1.dp, Color.White.copy(alpha = 0.05f)),
                            modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                            shape = RoundedCornerShape(8.dp)
                        ) {
                            Column(modifier = Modifier.padding(10.dp)) {
                                Text(
                                    text = if (isBengali) {
                                        "📦 প্যাকিং তথ্য: ১ বক্স = ${formatBengaliNumber(med.stripsPerBox)} পাতা | ১ পাতা = ${formatBengaliNumber(med.pcsPerStrip)} পিস"
                                    } else {
                                        "📦 Packing: 1 Box = ${med.stripsPerBox} Strips | 1 Strip = ${med.pcsPerStrip} Pcs"
                                    },
                                    color = InfoColor,
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Medium
                                )
                            }
                        }

                        Spacer(modifier = Modifier.height(10.dp))

                        // Selected Items Breakdown Summary
                        Text(
                            text = if (isBengali) "কার্ট সংযোজন পরিমাণ:" else "Adding Quantity Breakdown:",
                            color = DarkTextSecondary,
                            fontSize = 11.sp
                        )
                        Text(
                            text = med.formatQuantityString(totalQtySelected, isBengali),
                            color = DarkAccentGold,
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Bold,
                            modifier = Modifier.padding(bottom = 8.dp)
                        )

                        // 1. Box Selector
                        Row(
                            modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column {
                                Text(
                                    text = if (isBengali) "বক্স (Box)" else "Box",
                                    color = DarkTextPrimary,
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.SemiBold
                                )
                                Text(
                                    text = if (isBengali) "৳${formatBengaliNumber(String.format("%.1f", med.salePriceBox))} / বক্স" else "৳${String.format("%.1f", med.salePriceBox)} / Box",
                                    color = DarkTextSecondary,
                                    fontSize = 11.sp
                                )
                            }

                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Button(
                                    onClick = { if (boxesSelected > 0) boxesSelected-- },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color.White.copy(alpha = 0.1f)),
                                    modifier = Modifier.size(28.dp),
                                    contentPadding = PaddingValues(0.dp),
                                    shape = RoundedCornerShape(4.dp)
                                ) {
                                    Text("-", color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                }

                                Text(
                                    text = formatBengaliNumber(boxesSelected),
                                    modifier = Modifier.padding(horizontal = 12.dp),
                                    color = DarkTextPrimary,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 14.sp
                                )

                                Button(
                                    onClick = { if (boxesSelected < 50) boxesSelected++ },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color.White.copy(alpha = 0.1f)),
                                    modifier = Modifier.size(28.dp),
                                    contentPadding = PaddingValues(0.dp),
                                    shape = RoundedCornerShape(4.dp)
                                ) {
                                    Text("+", color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                }
                            }
                        }

                        // 2. Strip Selector
                        Row(
                            modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column {
                                Text(
                                    text = if (isBengali) "পাতা (Strip)" else "Strip",
                                    color = DarkTextPrimary,
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.SemiBold
                                )
                                Text(
                                    text = if (isBengali) "৳${formatBengaliNumber(String.format("%.1f", med.salePriceStrip))} / পাতা" else "৳${String.format("%.1f", med.salePriceStrip)} / Strip",
                                    color = DarkTextSecondary,
                                    fontSize = 11.sp
                                )
                            }

                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Button(
                                    onClick = { if (stripsSelected > 0) stripsSelected-- },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color.White.copy(alpha = 0.1f)),
                                    modifier = Modifier.size(28.dp),
                                    contentPadding = PaddingValues(0.dp),
                                    shape = RoundedCornerShape(4.dp)
                                ) {
                                    Text("-", color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                }

                                Text(
                                    text = formatBengaliNumber(stripsSelected),
                                    modifier = Modifier.padding(horizontal = 12.dp),
                                    color = DarkTextPrimary,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 14.sp
                                )

                                Button(
                                    onClick = { if (stripsSelected < 100) stripsSelected++ },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color.White.copy(alpha = 0.1f)),
                                    modifier = Modifier.size(28.dp),
                                    contentPadding = PaddingValues(0.dp),
                                    shape = RoundedCornerShape(4.dp)
                                ) {
                                    Text("+", color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                }
                            }
                        }

                        // 3. Piece Selector
                        Row(
                            modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column {
                                Text(
                                    text = if (isBengali) "পিস (Piece)" else "Piece",
                                    color = DarkTextPrimary,
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.SemiBold
                                )
                                Text(
                                    text = if (isBengali) "৳${formatBengaliNumber(String.format("%.1f", med.salePricePiece))} / পিস" else "৳${String.format("%.1f", med.salePricePiece)} / Pc",
                                    color = DarkTextSecondary,
                                    fontSize = 11.sp
                                )
                            }

                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Button(
                                    onClick = { if (piecesSelected > 0) piecesSelected-- },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color.White.copy(alpha = 0.1f)),
                                    modifier = Modifier.size(28.dp),
                                    contentPadding = PaddingValues(0.dp),
                                    shape = RoundedCornerShape(4.dp)
                                ) {
                                    Text("-", color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                }

                                Text(
                                    text = formatBengaliNumber(piecesSelected),
                                    modifier = Modifier.padding(horizontal = 12.dp),
                                    color = DarkTextPrimary,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 14.sp
                                )

                                Button(
                                    onClick = { if (piecesSelected < 500) piecesSelected++ },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color.White.copy(alpha = 0.1f)),
                                    modifier = Modifier.size(28.dp),
                                    contentPadding = PaddingValues(0.dp),
                                    shape = RoundedCornerShape(4.dp)
                                ) {
                                    Text("+", color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                }
                            }
                        }
                    } else {
                        // Standard Single Quantity Selection for other medicines (Syrup, Ointment, Injection, etc.)
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = if (isBengali) "পরিমাণ নির্ধারণ:" else "Select Quantity:",
                                color = DarkTextPrimary,
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold
                            )

                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Button(
                                    onClick = { if (addToCartQty > 1) addToCartQty-- },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color.White.copy(alpha = 0.1f)),
                                    modifier = Modifier.size(32.dp),
                                    contentPadding = PaddingValues(0.dp),
                                    shape = RoundedCornerShape(4.dp)
                                ) {
                                    Text("-", color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 16.sp)
                                }

                                Text(
                                    text = formatBengaliNumber(addToCartQty),
                                    modifier = Modifier.padding(horizontal = 14.dp),
                                    color = DarkTextPrimary,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 15.sp
                                )

                                Button(
                                    onClick = { if (addToCartQty < 100) addToCartQty++ },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color.White.copy(alpha = 0.1f)),
                                    modifier = Modifier.size(32.dp),
                                    contentPadding = PaddingValues(0.dp),
                                    shape = RoundedCornerShape(4.dp)
                                ) {
                                    Text("+", color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 16.sp)
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = if (isBengali) "মোট মূল্য:" else "Subtotal Price:",
                            color = DarkTextPrimary,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold
                        )
                        Text(
                            text = "৳${formatBengaliNumber(String.format("%.1f", calcTotalPrice))}",
                            color = DarkAccentGold,
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }

                    Spacer(modifier = Modifier.height(20.dp))

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.End
                    ) {
                        OutlinedButton(
                            onClick = { showAddToCartDialog = false },
                            border = BorderStroke(1.dp, Color.White.copy(alpha = 0.2f)),
                            colors = ButtonDefaults.outlinedButtonColors(contentColor = DarkTextSecondary),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.height(36.dp)
                        ) {
                            Text(if (isBengali) "বাতিল" else "Cancel", fontSize = 12.sp)
                        }

                        Spacer(modifier = Modifier.width(10.dp))

                        Button(
                            onClick = {
                                if (totalQtySelected <= 0) {
                                    android.widget.Toast.makeText(
                                        context,
                                        if (isBengali) "অনুগ্রহ করে অন্তত ১ পিস ওষুধ নির্বাচন করুন।" else "Please select at least 1 piece of medicine.",
                                        android.widget.Toast.LENGTH_SHORT
                                    ).show()
                                } else {
                                    viewModel.addToCustomerCart(med.id, totalQtySelected)
                                    showAddToCartDialog = false
                                    android.widget.Toast.makeText(
                                        context,
                                        if (isBengali) "${med.name} কার্টে যোগ করা হয়েছে!" else "${med.name} added to cart!",
                                        android.widget.Toast.LENGTH_SHORT
                                    ).show()
                                }
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = SuccessColor, contentColor = Color.White),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.height(36.dp)
                        ) {
                            Text(if (isBengali) "কার্টে যোগ করুন" else "Add to Cart", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }
    }

    if (showEditProfileDialog) {
        CustomerEditProfileDialog(
            viewModel = viewModel,
            isBengali = isBengali,
            onDismiss = { showEditProfileDialog = false }
        )
    }

    if (showPortalSwitchDialog) {
        NikotPortalSwitchDialog(
            viewModel = viewModel,
            isBengali = isBengali,
            onDismiss = { showPortalSwitchDialog = false }
        )
    }

    if (showLocationSettingsDialog) {
        CustomerLocationSettingsDialog(
            viewModel = viewModel,
            isBengali = isBengali,
            onDismiss = { showLocationSettingsDialog = false }
        )
    }
}

data class SimulatedPharmacy(
    val name: String,
    val nameEn: String,
    val lat: Double,
    val lLng: Double,
    val stockAvailable: Boolean,
    val baseDistanceKm: Double,
    val description: String,
    val descriptionEn: String,
    val ownerUsername: String = ""
)

data class CustomerGroupedMedicine(
    val groupKey: String,
    val name: String,
    val dosageStrength: String,
    val genericName: String,
    val type: String,
    val salePriceBox: Double,
    val salePriceStrip: Double,
    val salePricePiece: Double,
    val salePriceUnit: Double,
    val pharmacyOfferings: List<Medicine>
)

@Composable
fun CustomerMedicineCard(
    medGroup: CustomerGroupedMedicine,
    isBengali: Boolean,
    userProfiles: Map<String, PharmacyViewModel.UserProfile>,
    currentLat: Double?,
    currentLon: Double?,
    onAddToCart: (Medicine) -> Unit,
    onOrderNow: (Medicine, SimulatedPharmacy) -> Unit
) {
    var showPharmacies by remember(medGroup.groupKey) { mutableStateOf(false) }

    val inStockOfferings = remember(medGroup) {
        medGroup.pharmacyOfferings.filter { med ->
            when (med.type.lowercase().trim()) {
                "tablet" -> med.totalPiecesInStock > 0
                "syrup" -> med.bottlesInStock > 0
                "ointment" -> med.tubesInStock > 0
                "injection" -> med.vialsInStock > 0
                else -> med.otherQuantity > 0.0
            }
        }
    }
    val isAvailable = inStockOfferings.isNotEmpty()

    Card(
        modifier = Modifier.fillMaxWidth(),
        colors = CardDefaults.cardColors(containerColor = DarkSurface),
        border = BorderStroke(1.dp, if (isAvailable) DarkAccentGold.copy(alpha = 0.25f) else Color.White.copy(alpha = 0.08f)),
        shape = RoundedCornerShape(14.dp)
    ) {
        Column(modifier = Modifier.padding(14.dp)) {
            // Header Row: Medicine Name, Dosage, Generic & Stock Badge
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.Top
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = medGroup.name + (if (medGroup.dosageStrength.isNotEmpty()) " ${medGroup.dosageStrength}" else ""),
                        color = DarkTextPrimary,
                        fontWeight = FontWeight.Bold,
                        fontSize = 17.sp
                    )
                    Spacer(modifier = Modifier.height(2.dp))
                    Text(
                        text = "${medGroup.genericName} • ${medGroup.type}",
                        color = DarkTextSecondary,
                        fontSize = 12.5.sp
                    )
                }

                Box(
                    modifier = Modifier
                        .background(
                            color = if (isAvailable) SuccessColor.copy(alpha = 0.15f) else DarkAccentRed.copy(alpha = 0.15f),
                            shape = RoundedCornerShape(6.dp)
                        )
                        .padding(horizontal = 8.dp, vertical = 4.dp)
                ) {
                    Text(
                        text = if (isAvailable) {
                            if (isBengali) "স্টকে আছে (${formatBengaliNumber(inStockOfferings.size)}টি ফার্মেসী)" else "In Stock (${inStockOfferings.size} Pharmacies)"
                        } else {
                            if (isBengali) "স্টক শেষ" else "Out of Stock"
                        },
                        color = if (isAvailable) SuccessColor else DarkAccentGold,
                        fontSize = 10.5.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            }

            Spacer(modifier = Modifier.height(10.dp))

            // PRICING SECTION - BOX, STRIP, PIECE
            // যে ঔষধ সার্চ করবে সুধু ঔষধ দেখাবে এবং বক্স এর দাম, পাতার দাম ও প্রতি পিস
            if (medGroup.type.lowercase().trim() == "tablet") {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    // Box Price
                    Card(
                        modifier = Modifier.weight(1f),
                        colors = CardDefaults.cardColors(containerColor = DarkBg.copy(alpha = 0.7f)),
                        border = BorderStroke(1.dp, SleekBorderColor),
                        shape = RoundedCornerShape(8.dp)
                    ) {
                        Column(
                            modifier = Modifier.padding(horizontal = 6.dp, vertical = 8.dp),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            Text(
                                text = if (isBengali) "📦 বক্সের দাম" else "📦 Box Price",
                                color = DarkTextSecondary,
                                fontSize = 10.5.sp,
                                fontWeight = FontWeight.Medium
                            )
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = "৳${formatBengaliNumber(String.format("%.1f", medGroup.salePriceBox))}",
                                color = DarkAccentGold,
                                fontSize = 13.5.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }

                    // Strip Price
                    Card(
                        modifier = Modifier.weight(1f),
                        colors = CardDefaults.cardColors(containerColor = DarkBg.copy(alpha = 0.7f)),
                        border = BorderStroke(1.dp, SleekBorderColor),
                        shape = RoundedCornerShape(8.dp)
                    ) {
                        Column(
                            modifier = Modifier.padding(horizontal = 6.dp, vertical = 8.dp),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            Text(
                                text = if (isBengali) "📄 পাতার দাম" else "📄 Strip Price",
                                color = DarkTextSecondary,
                                fontSize = 10.5.sp,
                                fontWeight = FontWeight.Medium
                            )
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = "৳${formatBengaliNumber(String.format("%.1f", medGroup.salePriceStrip))}",
                                color = DarkAccentGold,
                                fontSize = 13.5.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }

                    // Per Piece Price
                    Card(
                        modifier = Modifier.weight(1f),
                        colors = CardDefaults.cardColors(containerColor = DarkBg.copy(alpha = 0.7f)),
                        border = BorderStroke(1.dp, SleekBorderColor),
                        shape = RoundedCornerShape(8.dp)
                    ) {
                        Column(
                            modifier = Modifier.padding(horizontal = 6.dp, vertical = 8.dp),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            Text(
                                text = if (isBengali) "💊 প্রতি পিস" else "💊 Per Piece",
                                color = DarkTextSecondary,
                                fontSize = 10.5.sp,
                                fontWeight = FontWeight.Medium
                            )
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = "৳${formatBengaliNumber(String.format("%.1f", medGroup.salePricePiece))}",
                                color = DarkAccentGold,
                                fontSize = 13.5.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                }
            } else {
                val unitSuffix = when (medGroup.type.lowercase().trim()) {
                    "syrup" -> if (isBengali) "প্রতি বোতল" else "per bottle"
                    "ointment" -> if (isBengali) "প্রতি টিউব" else "per tube"
                    "injection" -> if (isBengali) "প্রতি ভায়াল" else "per vial"
                    else -> if (isBengali) "প্রতি পিস" else "per pc"
                }
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    colors = CardDefaults.cardColors(containerColor = DarkBg.copy(alpha = 0.7f)),
                    border = BorderStroke(1.dp, SleekBorderColor),
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 8.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "${if (isBengali) "মূল্য (" else "Price ("}$unitSuffix):",
                            color = DarkTextSecondary,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Medium
                        )
                        Text(
                            text = "৳${formatBengaliNumber(String.format("%.1f", medGroup.salePriceUnit))}",
                            color = DarkAccentGold,
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // ACTION BUTTONS: Pharmacy view & Quick Add to Cart
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                OutlinedButton(
                    onClick = { showPharmacies = !showPharmacies },
                    colors = ButtonDefaults.outlinedButtonColors(
                        contentColor = if (showPharmacies) DarkAccentRed else Color.White
                    ),
                    border = BorderStroke(1.dp, if (showPharmacies) DarkAccentRed else SleekBorderColor),
                    shape = RoundedCornerShape(8.dp),
                    modifier = Modifier.weight(1f).height(38.dp),
                    contentPadding = PaddingValues(horizontal = 6.dp, vertical = 0.dp)
                ) {
                    Icon(
                        imageVector = if (showPharmacies) Icons.Default.ArrowDropUp else Icons.Default.LocalPharmacy,
                        contentDescription = null,
                        modifier = Modifier.size(16.dp)
                    )
                    Spacer(modifier = Modifier.width(4.dp))
                    Text(
                        text = if (showPharmacies) {
                            if (isBengali) "ফার্মেসী লুকান" else "Hide Stores"
                        } else {
                            if (isBengali) "ফার্মেসী তালিকা (${formatBengaliNumber(medGroup.pharmacyOfferings.size)})" else "Stores (${medGroup.pharmacyOfferings.size})"
                        },
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold
                    )
                }

                Button(
                    onClick = {
                        val target = inStockOfferings.firstOrNull() ?: medGroup.pharmacyOfferings.first()
                        onAddToCart(target)
                    },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (isAvailable) SuccessColor else Color.Gray.copy(alpha = 0.4f),
                        contentColor = Color.White
                    ),
                    shape = RoundedCornerShape(8.dp),
                    modifier = Modifier.weight(1f).height(38.dp),
                    enabled = isAvailable,
                    contentPadding = PaddingValues(horizontal = 6.dp, vertical = 0.dp)
                ) {
                    Icon(Icons.Filled.ShoppingCart, contentDescription = null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(4.dp))
                    Text(
                        text = if (isBengali) "কার্টে যোগ করুন" else "Add to Cart",
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            }

            // PHARMACIES EXPANDABLE SECTION
            if (showPharmacies) {
                Spacer(modifier = Modifier.height(10.dp))
                Divider(color = Color.White.copy(alpha = 0.08f))
                Spacer(modifier = Modifier.height(8.dp))

                Text(
                    text = if (isBengali) "যেসব ফার্মেসীতে এই ওষুধ পাওয়া যাচ্ছে:" else "Pharmacies carrying this medicine:",
                    color = DarkAccentGold,
                    fontSize = 11.5.sp,
                    fontWeight = FontWeight.Bold
                )
                Spacer(modifier = Modifier.height(6.dp))

                Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                    medGroup.pharmacyOfferings.forEach { pharmMed ->
                        val pProfile = userProfiles[pharmMed.pharmacyOwnerUsername]
                        val pName = pProfile?.pharmacyName ?: (if (pharmMed.pharmacyOwnerUsername == "admin") "আমার ফার্মেসী" else pharmMed.pharmacyOwnerUsername)
                        val pAddr = pProfile?.address ?: "সিলেট সিটি"
                        val pLat = pProfile?.latitude ?: 24.9015
                        val pLng = pProfile?.longitude ?: 91.8683

                        val dist = if (currentLat != null && currentLon != null) {
                            val latDiff = pLat - currentLat
                            val lonDiff = pLng - currentLon
                            val rawDist = Math.sqrt(latDiff * latDiff + lonDiff * lonDiff) * 111.0f
                            if (rawDist <= 0.05) 0.15 else rawDist
                        } else null

                        val stock = when (pharmMed.type.lowercase().trim()) {
                            "tablet" -> pharmMed.totalPiecesInStock
                            "syrup" -> pharmMed.bottlesInStock
                            "ointment" -> pharmMed.tubesInStock
                            "injection" -> pharmMed.vialsInStock
                            else -> pharmMed.otherQuantity.toInt()
                        }
                        val hasStock = stock > 0

                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = DarkBg.copy(alpha = 0.6f)),
                            border = BorderStroke(1.dp, if (hasStock) SuccessColor.copy(alpha = 0.3f) else Color.White.copy(alpha = 0.05f)),
                            shape = RoundedCornerShape(8.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth().padding(10.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Box(
                                            modifier = Modifier
                                                .size(8.dp)
                                                .background(if (hasStock) SuccessColor else DarkAccentRed, RoundedCornerShape(50.dp))
                                        )
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text(pName, color = DarkTextPrimary, fontWeight = FontWeight.Bold, fontSize = 13.sp)
                                        if (dist != null) {
                                            Spacer(modifier = Modifier.width(6.dp))
                                            Text(
                                                text = "• ${formatBengaliNumber(String.format("%.1f", dist))} কি.মি.",
                                                color = InfoColor,
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Medium
                                            )
                                        }
                                    }
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Text(
                                        text = if (hasStock) {
                                            if (isBengali) "স্টকে আছে (${pharmMed.formatQuantityString(stock, true)})" else "In stock (${pharmMed.formatQuantityString(stock, false)})"
                                        } else {
                                            if (isBengali) "স্টক শেষ" else "Out of stock"
                                        },
                                        color = if (hasStock) SuccessColor else DarkAccentRed,
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Medium
                                    )
                                }

                                Row(
                                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    IconButton(
                                        onClick = { onAddToCart(pharmMed) },
                                        enabled = hasStock,
                                        modifier = Modifier.size(32.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.ShoppingCart,
                                            contentDescription = "Add to cart",
                                            tint = if (hasStock) SuccessColor else Color.Gray.copy(alpha = 0.4f),
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }

                                    Button(
                                        onClick = {
                                            val pObj = SimulatedPharmacy(
                                                name = pName,
                                                nameEn = pName,
                                                lat = pLat,
                                                lLng = pLng,
                                                stockAvailable = hasStock,
                                                baseDistanceKm = dist ?: 0.0,
                                                description = pAddr,
                                                descriptionEn = pAddr,
                                                ownerUsername = pharmMed.pharmacyOwnerUsername
                                            )
                                            onOrderNow(pharmMed, pObj)
                                        },
                                        enabled = hasStock,
                                        colors = ButtonDefaults.buttonColors(
                                            containerColor = if (hasStock) DarkAccentRed else Color.Gray.copy(alpha = 0.3f),
                                            contentColor = Color.White
                                        ),
                                        shape = RoundedCornerShape(6.dp),
                                        contentPadding = PaddingValues(horizontal = 8.dp, vertical = 0.dp),
                                        modifier = Modifier.height(28.dp)
                                    ) {
                                        Text(if (isBengali) "অর্ডার" else "Order", fontSize = 10.5.sp, fontWeight = FontWeight.Bold)
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun AccountScreenForCustomer(viewModel: PharmacyViewModel, isBengali: Boolean) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val currentUser by viewModel.currentUser.collectAsState()
    var showEditProfile by remember { mutableStateOf(false) }
    var showPortalSwitchDialog by remember { mutableStateOf(false) }
    var showLocationSettingsDialog by remember { mutableStateOf(false) }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
            .verticalScroll(rememberScrollState())
    ) {
        // Portal Switch Settings Card
        Card(
            modifier = Modifier
                .fillMaxWidth()
                .padding(bottom = 14.dp),
            colors = CardDefaults.cardColors(containerColor = DarkSurface),
            border = BorderStroke(1.2.dp, DarkAccentGold),
            shape = RoundedCornerShape(16.dp)
        ) {
            Column(modifier = Modifier.padding(16.dp)) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Box(
                        modifier = Modifier
                            .size(40.dp)
                            .background(DarkAccentGold.copy(alpha = 0.15f), RoundedCornerShape(10.dp)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.SwapHoriz,
                            contentDescription = "Switch Portal",
                            tint = DarkAccentGold,
                            modifier = Modifier.size(24.dp)
                        )
                    }
                    Spacer(modifier = Modifier.width(12.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = if (isBengali) "পোর্টাল পরিবর্তন সেটিংস" else "Portal Switch Settings",
                            color = DarkTextPrimary,
                            fontWeight = FontWeight.Bold,
                            fontSize = 15.sp
                        )
                        Text(
                            text = if (isBengali) "স্টাফ বা মার্চেন্ট পোর্টালে যেতে ট্যাপ করুন" else "Switch to Staff or Merchant portal",
                            color = DarkTextSecondary,
                            fontSize = 11.5.sp
                        )
                    }
                }
                Spacer(modifier = Modifier.height(12.dp))
                Button(
                    onClick = { showPortalSwitchDialog = true },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(44.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = DarkBg),
                    shape = RoundedCornerShape(10.dp),
                    border = BorderStroke(1.2.dp, DarkAccentGold)
                ) {
                    Icon(Icons.Default.SwapHoriz, "switch portal", tint = DarkAccentGold, modifier = Modifier.size(18.dp))
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = if (isBengali) "🔄 পোর্টাল পরিবর্তন করুন (স্টাফ / মার্চেন্ট)" else "🔄 Switch Portal (Staff / Merchant)",
                        color = DarkAccentGold,
                        fontWeight = FontWeight.Bold,
                        fontSize = 13.5.sp
                    )
                }
            }
        }

        // Customer Profile Details Card
        Card(
            modifier = Modifier.fillMaxWidth(),
            colors = CardDefaults.cardColors(containerColor = DarkSurface),
            border = BorderStroke(1.dp, SleekBorderColor),
            shape = RoundedCornerShape(16.dp)
        ) {
            Column(modifier = Modifier.padding(16.dp)) {
                Text(
                    text = if (isBengali) "কনজিউমার প্রোফাইল বিবরণ" else "Consumer Profile Details",
                    color = DarkAccentGold,
                    fontWeight = FontWeight.Bold,
                    fontSize = 16.sp
                )
                Spacer(modifier = Modifier.height(12.dp))
                
                DetailRow(label = if (isBengali) "সম্পূর্ণ নাম (Name)" else "Name", value = currentUser.ownerName, isBengali = isBengali)
                DetailRow(label = if (isBengali) "মোবাইল নম্বর" else "Phone Number", value = currentUser.phone, isBengali = isBengali)
                DetailRow(
                    label = if (isBengali) "লোকেশন" else "Location",
                    value = if (currentUser.isLocationSet) currentUser.address.ifBlank { "${currentUser.ward}, ${currentUser.neighborhood}" } else (if (isBengali) "লোকেশন সেট করা হয়নি" else "Location not set"),
                    isBengali = isBengali
                )
            }
        }

        Spacer(modifier = Modifier.height(14.dp))

        // Dedicated Location Settings Card
        Card(
            modifier = Modifier.fillMaxWidth(),
            colors = CardDefaults.cardColors(containerColor = DarkSurface),
            border = BorderStroke(1.2.dp, if (currentUser.isLocationSet) SuccessColor.copy(alpha = 0.6f) else DarkAccentGold),
            shape = RoundedCornerShape(16.dp)
        ) {
            Column(modifier = Modifier.padding(16.dp)) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Box(
                            modifier = Modifier
                                .size(36.dp)
                                .background(
                                    if (currentUser.isLocationSet) SuccessColor.copy(alpha = 0.15f) else DarkAccentGold.copy(alpha = 0.15f),
                                    RoundedCornerShape(8.dp)
                                ),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = if (currentUser.isLocationSet) Icons.Filled.LocationOn else Icons.Filled.LocationOff,
                                contentDescription = "Location",
                                tint = if (currentUser.isLocationSet) SuccessColor else DarkAccentGold,
                                modifier = Modifier.size(20.dp)
                            )
                        }
                        Spacer(modifier = Modifier.width(10.dp))
                        Column {
                            Text(
                                text = if (isBengali) "আমার লোকেশন সেটিংস" else "My Location Settings",
                                color = DarkTextPrimary,
                                fontWeight = FontWeight.Bold,
                                fontSize = 14.5.sp
                            )
                            Text(
                                text = if (currentUser.isLocationSet) {
                                    if (isBengali) "লোকেশন সক্রিয় আছে" else "Location is set"
                                } else {
                                    if (isBengali) "লোকেশন সেট করা হয়নি" else "Location not set"
                                },
                                color = if (currentUser.isLocationSet) SuccessColor else DarkAccentGold,
                                fontSize = 11.5.sp,
                                fontWeight = FontWeight.Medium
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(10.dp))

                if (currentUser.isLocationSet) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(DarkBg.copy(alpha = 0.6f), RoundedCornerShape(8.dp))
                            .border(1.dp, Color.White.copy(alpha = 0.08f), RoundedCornerShape(8.dp))
                            .padding(10.dp)
                    ) {
                        Column {
                            if (currentUser.address.isNotBlank()) {
                                Text(
                                    text = "${if (isBengali) "সংরক্ষিত ঠিকানা: " else "Saved Address: "}${currentUser.address}",
                                    color = DarkTextPrimary,
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Medium
                                )
                            }
                            if (currentUser.ward.isNotBlank() || currentUser.neighborhood.isNotBlank()) {
                                Spacer(modifier = Modifier.height(2.dp))
                                Text(
                                    text = "${if (isBengali) "এলাকা: " else "Area: "}${currentUser.ward} • ${currentUser.neighborhood}",
                                    color = DarkTextSecondary,
                                    fontSize = 11.sp
                                )
                            }
                        }
                    }
                    Spacer(modifier = Modifier.height(10.dp))
                } else {
                    Text(
                        text = if (isBengali) 
                            "একাউন্টে নিজে থেকে লোকেশন সেট না করা পর্যন্ত কোনো ডিফল্ট বা অন্য কোনো লোকেশন দেখানো হবে না।" 
                        else 
                            "No default location will be used until you set your own location.",
                        color = DarkTextSecondary,
                        fontSize = 11.5.sp
                    )
                    Spacer(modifier = Modifier.height(10.dp))
                }

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Button(
                        onClick = { showLocationSettingsDialog = true },
                        modifier = Modifier.weight(1f).height(40.dp),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = if (currentUser.isLocationSet) DarkSurface else DarkAccentGold,
                            contentColor = if (currentUser.isLocationSet) Color.White else Color.Black
                        ),
                        border = if (currentUser.isLocationSet) BorderStroke(1.dp, DarkAccentGold) else null,
                        shape = RoundedCornerShape(8.dp),
                        contentPadding = PaddingValues(0.dp)
                    ) {
                        Icon(Icons.Filled.EditLocation, contentDescription = null, modifier = Modifier.size(16.dp))
                        Spacer(modifier = Modifier.width(6.dp))
                        Text(
                            text = if (currentUser.isLocationSet) {
                                if (isBengali) "লোকেশন পরিবর্তন করুন" else "Change Location"
                            } else {
                                if (isBengali) "লোকেশন সেট করুন" else "Set Location"
                            },
                            fontWeight = FontWeight.Bold,
                            fontSize = 12.sp
                        )
                    }

                    if (currentUser.isLocationSet) {
                        OutlinedButton(
                            onClick = {
                                viewModel.clearCustomerLocation()
                            },
                            modifier = Modifier.height(40.dp),
                            colors = ButtonDefaults.outlinedButtonColors(contentColor = DarkAccentRed),
                            border = BorderStroke(1.dp, DarkAccentRed.copy(alpha = 0.5f)),
                            shape = RoundedCornerShape(8.dp),
                            contentPadding = PaddingValues(horizontal = 10.dp)
                        ) {
                            Text(if (isBengali) "রিসেট / মুছুন" else "Reset", fontSize = 11.5.sp, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        // Language toggle controls
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = if (isBengali) "ভাষা সিলেক্ট করুন:" else "Select Language:",
                color = DarkTextPrimary,
                fontWeight = FontWeight.Medium,
                fontSize = 13.sp
            )
            Row {
                Button(
                    onClick = { viewModel.setLanguage(true) },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (isBengali) DarkAccentRed else DarkSurface,
                        contentColor = if (isBengali) DarkAccentText else DarkTextPrimary
                    ),
                    shape = RoundedCornerShape(8.dp),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                ) {
                    Text("বাংলা", fontSize = 12.sp, fontWeight = if (isBengali) FontWeight.Bold else FontWeight.Normal)
                }
                Spacer(modifier = Modifier.width(6.dp))
                Button(
                    onClick = { viewModel.setLanguage(false) },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (!isBengali) DarkAccentRed else DarkSurface,
                        contentColor = if (!isBengali) DarkAccentText else DarkTextPrimary
                    ),
                    shape = RoundedCornerShape(8.dp),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                ) {
                    Text("English", fontSize = 12.sp, fontWeight = if (!isBengali) FontWeight.Bold else FontWeight.Normal)
                }
            }
        }

        Spacer(modifier = Modifier.height(14.dp))

        // Theme toggle controls
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = if (isBengali) "থিম সিলেক্ট করুন:" else "Select Theme:",
                color = DarkTextPrimary,
                fontWeight = FontWeight.Medium,
                fontSize = 13.sp
            )
            Row {
                Button(
                    onClick = { viewModel.setDarkMode(false) },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (!isDarkModeGlobal) DarkAccentRed else DarkSurface,
                        contentColor = if (!isDarkModeGlobal) DarkAccentText else DarkTextPrimary
                    ),
                    shape = RoundedCornerShape(8.dp),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                ) {
                    Text(
                        text = if (isBengali) "লাইট" else "Light",
                        fontSize = 12.sp,
                        fontWeight = if (!isDarkModeGlobal) FontWeight.Bold else FontWeight.Normal
                    )
                }
                Spacer(modifier = Modifier.width(6.dp))
                Button(
                    onClick = { viewModel.setDarkMode(true) },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (isDarkModeGlobal) DarkAccentRed else DarkSurface,
                        contentColor = if (isDarkModeGlobal) DarkAccentText else DarkTextPrimary
                    ),
                    shape = RoundedCornerShape(8.dp),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                ) {
                    Text(
                        text = if (isBengali) "ডার্ক" else "Dark",
                        fontSize = 12.sp,
                        fontWeight = if (isDarkModeGlobal) FontWeight.Bold else FontWeight.Normal
                    )
                }
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        // Portal Switch Button
        Button(
            onClick = { showPortalSwitchDialog = true },
            modifier = Modifier
                .fillMaxWidth()
                .height(48.dp),
            colors = ButtonDefaults.buttonColors(containerColor = DarkSurface),
            shape = RoundedCornerShape(12.dp),
            border = BorderStroke(1.2.dp, DarkAccentGold)
        ) {
            Icon(Icons.Default.SwapHoriz, "switch portal", tint = DarkAccentGold)
            Spacer(modifier = Modifier.width(8.dp))
            Text(
                text = if (isBengali) "🔄 পোর্টাল পরিবর্তন (মার্চেন্ট / স্টাফ / কনজিউমার)" else "🔄 Switch Portal (Merchant / Staff / Consumer)",
                color = DarkAccentGold,
                fontWeight = FontWeight.Bold,
                fontSize = 13.5.sp
            )
        }

        Spacer(modifier = Modifier.height(10.dp))

        // Edit Profile Button
        Button(
            onClick = { showEditProfile = true },
            modifier = Modifier
                .fillMaxWidth()
                .height(44.dp),
            colors = ButtonDefaults.buttonColors(containerColor = DarkSurface),
            shape = RoundedCornerShape(12.dp),
            border = BorderStroke(1.dp, SleekBorderColor)
        ) {
            Icon(Icons.Filled.Edit, "edit profile", tint = DarkTextPrimary)
            Spacer(modifier = Modifier.width(6.dp))
            Text(if (isBengali) "প্রোফাইল পরিবর্তন" else "Change Profile", color = DarkTextPrimary, fontWeight = FontWeight.Bold)
        }

        Spacer(modifier = Modifier.height(12.dp))

        // Logout Button
        Button(
            onClick = { viewModel.logout() },
            modifier = Modifier
                .fillMaxWidth()
                .height(44.dp),
            colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed, contentColor = DarkAccentText),
            shape = RoundedCornerShape(12.dp)
        ) {
            Text(if (isBengali) "লগআউট করুন" else "Log Out", fontWeight = FontWeight.Bold, color = DarkAccentText)
        }

        Spacer(modifier = Modifier.height(32.dp))
        PoweredByRoFooter(
            isBengali = isBengali,
            badgeHeight = 18.dp,
            modifier = Modifier.fillMaxWidth().padding(bottom = 16.dp)
        )
    }

    if (showEditProfile) {
        CustomerEditProfileDialog(
            viewModel = viewModel,
            isBengali = isBengali,
            onDismiss = { showEditProfile = false }
        )
    }

    if (showPortalSwitchDialog) {
        NikotPortalSwitchDialog(
            viewModel = viewModel,
            isBengali = isBengali,
            onDismiss = { showPortalSwitchDialog = false }
        )
    }

    if (showLocationSettingsDialog) {
        CustomerLocationSettingsDialog(
            viewModel = viewModel,
            isBengali = isBengali,
            onDismiss = { showLocationSettingsDialog = false }
        )
    }
}

@Composable
fun NikotPortalSwitchDialog(
    viewModel: PharmacyViewModel,
    isBengali: Boolean,
    onDismiss: () -> Unit
) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val currentUser by viewModel.currentUser.collectAsState()
    var selectedCustomization by remember { mutableStateOf<String?>(null) } // null, "admin_custom", "staff_custom"

    var adminPharmacyName by remember { mutableStateOf(currentUser.pharmacyName.ifBlank { "নিকট ফার্মেসী" }) }
    var staffPharmacyName by remember { mutableStateOf(currentUser.pharmacyName.ifBlank { "নিকট ফার্মেসী" }) }
    var staffOwnerName by remember { mutableStateOf(currentUser.ownerName.ifBlank { currentUser.username }) }
    var staffSecurityCode by remember { mutableStateOf(currentUser.securityCode) }
    var errorMsg by remember { mutableStateOf("") }

    Dialog(onDismissRequest = onDismiss) {
        Card(
            colors = CardDefaults.cardColors(containerColor = DarkSurface),
            border = BorderStroke(1.5.dp, DarkAccentGold),
            shape = RoundedCornerShape(20.dp),
            modifier = Modifier
                .fillMaxWidth()
                .padding(4.dp)
        ) {
            Column(
                modifier = Modifier
                    .padding(20.dp)
                    .verticalScroll(rememberScrollState()),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                // Header Logo and Close Button
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    RoLogoHeader(height = 30.dp)
                    IconButton(
                        onClick = onDismiss,
                        modifier = Modifier.size(28.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Close,
                            contentDescription = "Close",
                            tint = DarkTextSecondary
                        )
                    }
                }

                Spacer(modifier = Modifier.height(10.dp))

                Text(
                    text = if (isBengali) "পোর্টাল পরিবর্তন / সুইচ করুন" else "Switch & Enter Portal",
                    color = DarkTextPrimary,
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold
                )

                Text(
                    text = if (isBengali) "যে কোনো সময় আপনি কনজিউমার, স্টাফ বা মার্চেন্ট পোর্টালে সহজেই যেতে পারবেন" else "You can switch freely between Consumer, Staff, and Merchant portals anytime",
                    color = DarkTextSecondary,
                    fontSize = 11.5.sp,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(top = 4.dp, bottom = 12.dp)
                )

                if (selectedCustomization == null) {
                    // Option 1: Consumer Portal
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 5.dp)
                            .clickable {
                                viewModel.switchPortalDirectly("customer")
                                onDismiss()
                                android.widget.Toast.makeText(
                                    context,
                                    if (isBengali) "কনজিউমার পোর্টালে সফলভাবে প্রবেশ করেছেন!" else "Switched to Consumer Portal!",
                                    android.widget.Toast.LENGTH_SHORT
                                ).show()
                            },
                        colors = CardDefaults.cardColors(
                            containerColor = if (currentUser.role == "customer") Color(0xFF0288D1).copy(alpha = 0.15f) else DarkBg
                        ),
                        border = BorderStroke(
                            width = if (currentUser.role == "customer") 1.8.dp else 1.dp,
                            color = if (currentUser.role == "customer") Color(0xFF0288D1) else SleekBorderColor
                        ),
                        shape = RoundedCornerShape(14.dp)
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(14.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(44.dp)
                                    .background(Color(0xFF0288D1).copy(alpha = 0.2f), RoundedCornerShape(10.dp)),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Default.ShoppingCart,
                                    contentDescription = "Consumer",
                                    tint = Color(0xFF0288D1),
                                    modifier = Modifier.size(24.dp)
                                )
                            }
                            Spacer(modifier = Modifier.width(12.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Text(
                                        text = if (isBengali) "কনজিউমার পোর্টাল" else "Consumer Portal",
                                        color = DarkTextPrimary,
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.Bold
                                    )
                                    if (currentUser.role == "customer") {
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text(
                                            text = if (isBengali) "● বর্তমান" else "● Active",
                                            color = Color(0xFF0288D1),
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                                Text(
                                    text = if (isBengali) "ওষুধ অনুসন্ধান, কার্ট ও অনলাইন অর্ডার" else "Search meds, cart & online order",
                                    color = DarkTextSecondary,
                                    fontSize = 11.5.sp
                                )
                            }
                            Icon(
                                imageVector = Icons.Default.ChevronRight,
                                contentDescription = null,
                                tint = DarkTextSecondary
                            )
                        }
                    }

                    // Option 2: Staff Portal
                    val (canStaff, staffBlockReason) = viewModel.canSwitchToPortal("staff", currentUser)
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 5.dp)
                            .clickable {
                                if (canStaff) {
                                    viewModel.switchPortalDirectly("staff")
                                    onDismiss()
                                    android.widget.Toast.makeText(
                                        context,
                                        if (isBengali) "স্টাফ পোর্টালে সফলভাবে প্রবেশ করেছেন!" else "Switched to Staff Portal!",
                                        android.widget.Toast.LENGTH_SHORT
                                    ).show()
                                } else {
                                    android.widget.Toast.makeText(
                                        context,
                                        staffBlockReason,
                                        android.widget.Toast.LENGTH_LONG
                                    ).show()
                                }
                            },
                        colors = CardDefaults.cardColors(
                            containerColor = when {
                                !canStaff -> DarkBg.copy(alpha = 0.45f)
                                currentUser.role == "staff" -> Color(0xFF2E7D32).copy(alpha = 0.15f)
                                else -> DarkBg
                            }
                        ),
                        border = BorderStroke(
                            width = if (currentUser.role == "staff") 1.8.dp else 1.dp,
                            color = when {
                                !canStaff -> SleekBorderColor.copy(alpha = 0.35f)
                                currentUser.role == "staff" -> Color(0xFF2E7D32)
                                else -> SleekBorderColor
                            }
                        ),
                        shape = RoundedCornerShape(14.dp)
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(14.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(44.dp)
                                    .background(
                                        if (canStaff) Color(0xFF2E7D32).copy(alpha = 0.2f) else DarkSurface,
                                        RoundedCornerShape(10.dp)
                                    ),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = if (canStaff) Icons.Default.People else Icons.Default.Lock,
                                    contentDescription = "Staff",
                                    tint = if (canStaff) Color(0xFF2E7D32) else DarkTextSecondary.copy(alpha = 0.6f),
                                    modifier = Modifier.size(24.dp)
                                )
                            }
                            Spacer(modifier = Modifier.width(12.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Text(
                                        text = if (isBengali) "স্টাফ পোর্টাল" else "Staff Portal",
                                        color = if (canStaff) DarkTextPrimary else DarkTextSecondary,
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.Bold
                                    )
                                    if (currentUser.role == "staff") {
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text(
                                            text = if (isBengali) "● বর্তমান" else "● Active",
                                            color = Color(0xFF2E7D32),
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    } else if (!canStaff) {
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text(
                                            text = if (isBengali) "🔒 বন্ধ" else "🔒 Locked",
                                            color = DarkAccentRed,
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                                Text(
                                    text = if (!canStaff) {
                                        if (isBengali) "মার্চেন্ট একাউন্ট স্টাফ পোর্টালে যেতে পারবে না" else "Merchant account cannot switch to Staff"
                                    } else {
                                        if (isBengali) "ফার্মেসী কর্মী, সেলস বিল ও স্টক ইন" else "Pharmacy employee, billing & stock"
                                    },
                                    color = DarkTextSecondary.copy(alpha = if (canStaff) 1f else 0.7f),
                                    fontSize = 11.5.sp
                                )
                            }
                            Icon(
                                imageVector = if (canStaff) Icons.Default.ChevronRight else Icons.Default.Block,
                                contentDescription = null,
                                tint = if (canStaff) DarkTextSecondary else DarkAccentRed.copy(alpha = 0.7f)
                            )
                        }
                    }

                    // Option 3: Merchant Portal
                    val (canMerchant, merchantBlockReason) = viewModel.canSwitchToPortal("admin", currentUser)
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 5.dp)
                            .clickable {
                                if (!canMerchant) {
                                    android.widget.Toast.makeText(
                                        context,
                                        merchantBlockReason,
                                        android.widget.Toast.LENGTH_LONG
                                    ).show()
                                } else if (currentUser.role == "customer" || currentUser.pharmacyName.isBlank()) {
                                    adminPharmacyName = currentUser.pharmacyName.ifBlank { "" }
                                    selectedCustomization = "admin_custom"
                                } else {
                                    viewModel.switchPortalDirectly("admin", currentUser.pharmacyName)
                                    onDismiss()
                                    android.widget.Toast.makeText(
                                        context,
                                        if (isBengali) "মার্চেন্ট পোর্টালে সফলভাবে প্রবেশ করেছেন!" else "Switched to Merchant Portal!",
                                        android.widget.Toast.LENGTH_SHORT
                                    ).show()
                                }
                            },
                        colors = CardDefaults.cardColors(
                            containerColor = when {
                                !canMerchant -> DarkBg.copy(alpha = 0.45f)
                                currentUser.role == "admin" || currentUser.role == "merchant" -> DarkAccentRed.copy(alpha = 0.15f)
                                else -> DarkBg
                            }
                        ),
                        border = BorderStroke(
                            width = if (currentUser.role == "admin" || currentUser.role == "merchant") 1.8.dp else 1.dp,
                            color = when {
                                !canMerchant -> SleekBorderColor.copy(alpha = 0.35f)
                                currentUser.role == "admin" || currentUser.role == "merchant" -> DarkAccentRed
                                else -> SleekBorderColor
                            }
                        ),
                        shape = RoundedCornerShape(14.dp)
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(14.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(44.dp)
                                    .background(
                                        if (canMerchant) DarkAccentRed.copy(alpha = 0.2f) else DarkSurface,
                                        RoundedCornerShape(10.dp)
                                    ),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = if (canMerchant) Icons.Default.Storefront else Icons.Default.Lock,
                                    contentDescription = "Merchant",
                                    tint = if (canMerchant) DarkAccentRed else DarkTextSecondary.copy(alpha = 0.6f),
                                    modifier = Modifier.size(24.dp)
                                )
                            }
                            Spacer(modifier = Modifier.width(12.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Text(
                                        text = if (isBengali) "মার্চেন্ট পোর্টাল" else "Merchant Portal",
                                        color = if (canMerchant) DarkTextPrimary else DarkTextSecondary,
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.Bold
                                    )
                                    if (currentUser.role == "admin" || currentUser.role == "merchant") {
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text(
                                            text = if (isBengali) "● বর্তমান" else "● Active",
                                            color = DarkAccentRed,
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    } else if (!canMerchant) {
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text(
                                            text = if (isBengali) "🔒 বন্ধ" else "🔒 Locked",
                                            color = DarkAccentRed,
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                                Text(
                                    text = if (!canMerchant) {
                                        if (isBengali) "স্টাফ একাউন্ট মার্চেন্ট পোর্টাল তৈরি করতে পারবে না" else "Staff account cannot switch to Merchant"
                                    } else {
                                        if (isBengali) "ফার্মেসী মালিক, পূর্ণ কন্ট্রোল ও রিপোর্ট" else "Pharmacy owner, full dashboard & reports"
                                    },
                                    color = DarkTextSecondary.copy(alpha = if (canMerchant) 1f else 0.7f),
                                    fontSize = 11.5.sp
                                )
                            }
                            Icon(
                                imageVector = if (canMerchant) Icons.Default.ChevronRight else Icons.Default.Block,
                                contentDescription = null,
                                tint = if (canMerchant) DarkTextSecondary else DarkAccentRed.copy(alpha = 0.7f)
                            )
                        }
                    }
                } else if (selectedCustomization == "admin_custom") {
                    // Pharmacy Name Input when switching to Merchant Portal
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 4.dp),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Box(
                            modifier = Modifier
                                .size(52.dp)
                                .background(DarkAccentRed.copy(alpha = 0.2f), RoundedCornerShape(14.dp)),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Default.Storefront,
                                contentDescription = "Merchant",
                                tint = DarkAccentRed,
                                modifier = Modifier.size(28.dp)
                            )
                        }
                        Spacer(modifier = Modifier.height(10.dp))
                        Text(
                            text = if (isBengali) "মার্চেন্ট পোর্টাল পরিবর্তন" else "Switch to Merchant Portal",
                            color = DarkTextPrimary,
                            fontSize = 17.sp,
                            fontWeight = FontWeight.Bold
                        )
                        Text(
                            text = if (isBengali) "মার্চেন্ট পোর্টালে যেতে আপনার ফার্মেসীর নাম প্রদান করুন:" else "Enter your pharmacy name to switch to Merchant Portal:",
                            color = DarkTextSecondary,
                            fontSize = 12.sp,
                            textAlign = TextAlign.Center,
                            modifier = Modifier.padding(top = 4.dp, bottom = 14.dp)
                        )

                        OutlinedTextField(
                            value = adminPharmacyName,
                            onValueChange = {
                                adminPharmacyName = it
                                errorMsg = ""
                            },
                            label = { Text(if (isBengali) "ফার্মেসীর নাম (Pharmacy Name)" else "Pharmacy Name") },
                            placeholder = { Text(if (isBengali) "যেমন: সেবা ফার্মেসী, লাজ ফার্মা..." else "e.g. Popular Pharmacy") },
                            leadingIcon = {
                                Icon(Icons.Default.LocalPharmacy, contentDescription = null, tint = DarkAccentRed)
                            },
                            textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                            modifier = Modifier.fillMaxWidth(),
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedBorderColor = DarkAccentRed,
                                unfocusedBorderColor = DarkTextSecondary.copy(alpha = 0.5f),
                                focusedLabelColor = DarkAccentRed,
                                unfocusedLabelColor = DarkTextSecondary
                            ),
                            shape = RoundedCornerShape(12.dp),
                            singleLine = true
                        )

                        if (errorMsg.isNotEmpty()) {
                            Text(
                                text = errorMsg,
                                color = DarkAccentRed,
                                fontSize = 12.sp,
                                modifier = Modifier.padding(top = 6.dp)
                            )
                        }

                        Spacer(modifier = Modifier.height(16.dp))

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            OutlinedButton(
                                onClick = {
                                    selectedCustomization = null
                                    errorMsg = ""
                                },
                                modifier = Modifier.weight(1f).height(44.dp),
                                shape = RoundedCornerShape(10.dp),
                                border = BorderStroke(1.dp, SleekBorderColor)
                            ) {
                                Text(if (isBengali) "পিছনে" else "Back", color = DarkTextSecondary)
                            }

                            Button(
                                onClick = {
                                    if (adminPharmacyName.trim().isEmpty()) {
                                        errorMsg = if (isBengali) "অনুগ্রহ করে আপনার ফার্মেসীর নাম লিখুন!" else "Please enter your pharmacy name!"
                                    } else {
                                        viewModel.switchPortalDirectly("admin", adminPharmacyName.trim())
                                        onDismiss()
                                        android.widget.Toast.makeText(
                                            context,
                                            if (isBengali) "মার্চেন্ট পোর্টালে সফলভাবে প্রবেশ করেছেন!" else "Switched to Merchant Portal!",
                                            android.widget.Toast.LENGTH_SHORT
                                        ).show()
                                    }
                                },
                                modifier = Modifier.weight(1.5f).height(44.dp),
                                colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed),
                                shape = RoundedCornerShape(10.dp)
                            ) {
                                Icon(Icons.Default.ArrowForward, contentDescription = null, modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(
                                    text = if (isBengali) "পোর্টালে প্রবেশ" else "Enter Portal",
                                    color = DarkAccentText,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun DetailRow(label: String, value: String, isBengali: Boolean) {
    Column(modifier = Modifier.padding(vertical = 6.dp)) {
        Text(text = label, color = DarkTextSecondary, fontSize = 11.sp, fontWeight = FontWeight.Medium)
        Text(text = value, color = DarkTextPrimary, fontSize = 14.sp, fontWeight = FontWeight.Bold)
        Spacer(modifier = Modifier.height(4.dp))
        Divider(color = Color.White.copy(alpha = 0.05f))
    }
}

@Composable
fun CustomerEditProfileDialog(
    viewModel: PharmacyViewModel,
    isBengali: Boolean,
    onDismiss: () -> Unit
) {
    val currentUser by viewModel.currentUser.collectAsState()

    var name by remember { mutableStateOf(currentUser.ownerName) }
    var address by remember { mutableStateOf(currentUser.address) }
    var phone by remember { mutableStateOf(currentUser.phone) }
    var password by remember { mutableStateOf(currentUser.pass) }
    var role by remember { mutableStateOf(currentUser.role) }

    Dialog(onDismissRequest = onDismiss) {
        Card(
            colors = CardDefaults.cardColors(containerColor = DarkSurface),
            border = BorderStroke(1.dp, SleekBorderColor),
            shape = RoundedCornerShape(16.dp),
            modifier = Modifier.fillMaxWidth()
        ) {
            Column(modifier = Modifier.padding(16.dp).verticalScroll(rememberScrollState())) {
                Text(
                    text = if (isBengali) "গ্রাহক প্রোফাইল ও ক্যাটাগরি পরিবর্তন" else "Edit Profile & Category",
                    color = DarkAccentGold,
                    fontSize = 16.sp,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.padding(bottom = 12.dp)
                )

                OutlinedTextField(
                    value = name,
                    onValueChange = { name = it },
                    label = { Text(if (isBengali) "আপনার নাম (Name)" else "Your Name") },
                    textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                    modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = DarkAccentRed,
                        unfocusedBorderColor = DarkTextSecondary.copy(alpha = 0.5f),
                        focusedLabelColor = DarkAccentRed,
                        unfocusedLabelColor = DarkTextSecondary
                    ),
                    shape = RoundedCornerShape(12.dp)
                )

                OutlinedTextField(
                    value = address,
                    onValueChange = { address = it },
                    label = { Text(if (isBengali) "ঠিকানা (Address)" else "Address") },
                    textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                    modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = DarkAccentRed,
                        unfocusedBorderColor = DarkTextSecondary.copy(alpha = 0.5f),
                        focusedLabelColor = DarkAccentRed,
                        unfocusedLabelColor = DarkTextSecondary
                    ),
                    shape = RoundedCornerShape(12.dp)
                )

                OutlinedTextField(
                    value = phone,
                    onValueChange = { phone = it },
                    label = { Text(if (isBengali) "ফোন নম্বর (Phone)" else "Phone Number") },
                    textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                    modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = DarkAccentRed,
                        unfocusedBorderColor = DarkTextSecondary.copy(alpha = 0.5f),
                        focusedLabelColor = DarkAccentRed,
                        unfocusedLabelColor = DarkTextSecondary
                    ),
                    shape = RoundedCornerShape(12.dp)
                )

                OutlinedTextField(
                    value = password,
                    onValueChange = { password = it },
                    label = { Text(if (isBengali) "নিরাপত্তা পাসওয়ার্ড (Password)" else "Password") },
                    textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                    modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = DarkAccentRed,
                        unfocusedBorderColor = DarkTextSecondary.copy(alpha = 0.5f),
                        focusedLabelColor = DarkAccentRed,
                        unfocusedLabelColor = DarkTextSecondary
                    ),
                    shape = RoundedCornerShape(12.dp)
                )

                Spacer(modifier = Modifier.height(20.dp))

                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
                    TextButton(onClick = onDismiss) { Text(if (isBengali) "বাতিল" else "Cancel", color = DarkTextSecondary) }
                    Spacer(modifier = Modifier.width(8.dp))
                    Button(
                        colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed, contentColor = DarkAccentText),
                        onClick = {
                            viewModel.updateProfile(
                                name = currentUser.pharmacyName,
                                addr = address,
                                phone = phone,
                                owner = name,
                                pass = password,
                                openTime = currentUser.openTime,
                                closeTime = currentUser.closeTime,
                                role = role
                            )
                            onDismiss()
                        }
                    ) {
                        Text(if (isBengali) "সংরক্ষণ করুন" else "Save", color = DarkAccentText)
                    }
                }
            }
        }
    }
}

@Composable
fun CustomerLocationSettingsDialog(
    viewModel: PharmacyViewModel,
    isBengali: Boolean,
    onDismiss: () -> Unit
) {
    val currentUser by viewModel.currentUser.collectAsState()
    var selectedWardIndex by remember {
        val wIdx = sylhetAreas.indexOfFirst { it.ward == currentUser.ward || it.wardEn == currentUser.ward }
        mutableStateOf(if (wIdx >= 0) wIdx else 0)
    }
    var selectedNeighborhoodIndex by remember {
        val activeWard = sylhetAreas.getOrElse(selectedWardIndex) { sylhetAreas[0] }
        val nIdx = activeWard.neighborhoods.indexOfFirst { it.name == currentUser.neighborhood || it.nameEn == currentUser.neighborhood }
        mutableStateOf(if (nIdx >= 0) nIdx else 0)
    }
    var manualAddressText by remember { mutableStateOf(currentUser.address) }
    var lat by remember { mutableStateOf(currentUser.latitude) }
    var lng by remember { mutableStateOf(currentUser.longitude) }
    val context = LocalContext.current

    Dialog(onDismissRequest = onDismiss) {
        Card(
            colors = CardDefaults.cardColors(containerColor = DarkSurface),
            border = BorderStroke(1.dp, SleekBorderColor),
            shape = RoundedCornerShape(16.dp),
            modifier = Modifier.fillMaxWidth()
        ) {
            Column(modifier = Modifier.padding(16.dp).verticalScroll(rememberScrollState())) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.padding(bottom = 10.dp)
                ) {
                    Icon(
                        imageVector = Icons.Filled.LocationOn,
                        contentDescription = null,
                        tint = DarkAccentGold,
                        modifier = Modifier.size(22.dp)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = if (isBengali) "সেটিংস: স্থায়ী লোকেশন সেট করুন" else "Settings: Set Location",
                        color = DarkAccentGold,
                        fontSize = 15.5.sp,
                        fontWeight = FontWeight.Bold
                    )
                }

                Text(
                    text = if (isBengali) "এখানে সেট করা লোকেশন ডিফল্ট হিসেবে আপনার প্রোফাইলে ও ওষুধ খোঁজার জন্য ব্যবহার করা হবে।" else "This location will be saved to your profile and used for pharmacy search.",
                    color = DarkTextSecondary,
                    fontSize = 11.5.sp,
                    modifier = Modifier.padding(bottom = 12.dp)
                )

                // Current Saved Location Status
                if (currentUser.isLocationSet) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color.White.copy(alpha = 0.04f), RoundedCornerShape(8.dp))
                            .border(1.dp, Color.White.copy(alpha = 0.1f), RoundedCornerShape(8.dp))
                            .padding(horizontal = 10.dp, vertical = 6.dp)
                    ) {
                        Text(
                            text = "${if (isBengali) "বর্তমান সেভ করা লোকেশন: " else "Currently saved: "}${currentUser.address}",
                            color = DarkAccentGold,
                            fontSize = 11.5.sp
                        )
                    }
                    Spacer(modifier = Modifier.height(10.dp))
                } else {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color(0xFF261D1D), RoundedCornerShape(8.dp))
                            .border(1.dp, DarkAccentGold.copy(alpha = 0.3f), RoundedCornerShape(8.dp))
                            .padding(horizontal = 10.dp, vertical = 8.dp)
                    ) {
                        Text(
                            text = if (isBengali) "⚠️ বর্তমানে কোনো লোকেশন সেট করা নেই। নিচে আপনার নিজস্ব ঠিকানা লিখুন অথবা এলাকা বেছে নিয়ে সেভ করুন।" else "⚠️ No location is currently set. Enter your address or choose your area below and save.",
                            color = DarkAccentGold,
                            fontSize = 11.5.sp
                        )
                    }
                    Spacer(modifier = Modifier.height(10.dp))
                }

                // Live GPS button
                Button(
                    onClick = {
                        try {
                            val locationManager = context.getSystemService(android.content.Context.LOCATION_SERVICE) as android.location.LocationManager
                            val lastKnown = locationManager.getLastKnownLocation(android.location.LocationManager.GPS_PROVIDER)
                                ?: locationManager.getLastKnownLocation(android.location.LocationManager.NETWORK_PROVIDER)
                            if (lastKnown != null) {
                                lat = lastKnown.latitude
                                lng = lastKnown.longitude
                                if (manualAddressText.isBlank()) {
                                    manualAddressText = "লাইভ জিপিএস লোকেশন (${String.format("%.4f", lat)}, ${String.format("%.4f", lng)})"
                                }
                                android.widget.Toast.makeText(context, if (isBengali) "জিপিএস লোকেশন পাওয়া গেছে!" else "GPS Location acquired!", android.widget.Toast.LENGTH_SHORT).show()
                            } else {
                                android.widget.Toast.makeText(context, if (isBengali) "জিপিএস সিগন্যাল মেলেনি। ম্যানুয়াল ঠিকানা লিখুন।" else "GPS not available. Please type address manually.", android.widget.Toast.LENGTH_SHORT).show()
                            }
                        } catch (e: SecurityException) {
                            android.widget.Toast.makeText(context, if (isBengali) "লোকেশন পারমিশন নেই।" else "Location permission required.", android.widget.Toast.LENGTH_SHORT).show()
                        }
                    },
                    modifier = Modifier.fillMaxWidth().height(38.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = DarkBg),
                    border = BorderStroke(1.dp, InfoColor.copy(alpha = 0.5f)),
                    shape = RoundedCornerShape(8.dp),
                    contentPadding = PaddingValues(0.dp)
                ) {
                    Icon(Icons.Filled.MyLocation, contentDescription = null, tint = InfoColor, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(if (isBengali) "📍 বর্তমান ডিভাইস জিপিএস (GPS) লোকেশন নিন" else "📍 Get Device GPS Location", color = InfoColor, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                }

                Spacer(modifier = Modifier.height(10.dp))

                // Manual Address Input Field
                OutlinedTextField(
                    value = manualAddressText,
                    onValueChange = { manualAddressText = it },
                    label = { Text(if (isBengali) "ঠিকানা লিখুন (বাড়ি/রোড/এলাকা)" else "Type Address (House/Road/Area)") },
                    textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                    modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = DarkAccentRed,
                        unfocusedBorderColor = DarkTextSecondary.copy(alpha = 0.5f),
                        focusedLabelColor = DarkAccentRed,
                        unfocusedLabelColor = DarkTextSecondary
                    ),
                    shape = RoundedCornerShape(12.dp)
                )

                Spacer(modifier = Modifier.height(8.dp))
                Divider(color = Color.White.copy(alpha = 0.08f))
                Spacer(modifier = Modifier.height(8.dp))

                Text(
                    text = if (isBengali) "অথবা সিলেট সিটি এরিয়া নির্বাচন করুন:" else "Or Select Sylhet City Area:",
                    color = Color.White,
                    fontSize = 12.5.sp,
                    fontWeight = FontWeight.SemiBold
                )
                Spacer(modifier = Modifier.height(6.dp))

                var showWardMenu by remember { mutableStateOf(false) }
                var showNeighborhoodMenu by remember { mutableStateOf(false) }

                // Ward selector
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(Color.White.copy(alpha = 0.05f), RoundedCornerShape(8.dp))
                        .border(1.dp, Color.White.copy(alpha = 0.15f), RoundedCornerShape(8.dp))
                        .clickable { showWardMenu = true }
                        .padding(horizontal = 12.dp, vertical = 10.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = if (isBengali) sylhetAreas[selectedWardIndex].ward else sylhetAreas[selectedWardIndex].wardEn,
                            color = Color.White,
                            fontSize = 12.sp
                        )
                        Icon(Icons.Default.ArrowDropDown, contentDescription = null, tint = Color.White)
                    }
                    DropdownMenu(
                        expanded = showWardMenu,
                        onDismissRequest = { showWardMenu = false },
                        modifier = Modifier.background(DarkSurface)
                    ) {
                        sylhetAreas.forEachIndexed { idx, area ->
                            DropdownMenuItem(
                                text = { Text(if (isBengali) area.ward else area.wardEn, color = Color.White, fontSize = 12.sp) },
                                onClick = {
                                    selectedWardIndex = idx
                                    selectedNeighborhoodIndex = 0
                                    showWardMenu = false
                                    val nh = area.neighborhoods[0]
                                    lat = nh.lat
                                    lng = nh.lon
                                    if (manualAddressText.trim().isEmpty() || manualAddressText.contains("সিলেট")) {
                                        manualAddressText = "সিলেট সিটি কর্পোরেশন, ${area.ward}, ${nh.name}"
                                    }
                                }
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(8.dp))

                // Neighborhood selector
                val activeWard = sylhetAreas[selectedWardIndex]
                val currentNeighborhood = activeWard.neighborhoods.getOrElse(selectedNeighborhoodIndex) { activeWard.neighborhoods[0] }
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(Color.White.copy(alpha = 0.05f), RoundedCornerShape(8.dp))
                        .border(1.dp, Color.White.copy(alpha = 0.15f), RoundedCornerShape(8.dp))
                        .clickable { showNeighborhoodMenu = true }
                        .padding(horizontal = 12.dp, vertical = 10.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = if (isBengali) currentNeighborhood.name else currentNeighborhood.nameEn,
                            color = Color.White,
                            fontSize = 12.sp
                        )
                        Icon(Icons.Default.ArrowDropDown, contentDescription = null, tint = Color.White)
                    }
                    DropdownMenu(
                        expanded = showNeighborhoodMenu,
                        onDismissRequest = { showNeighborhoodMenu = false },
                        modifier = Modifier.background(DarkSurface)
                    ) {
                        activeWard.neighborhoods.forEachIndexed { idx, nh ->
                            DropdownMenuItem(
                                text = { Text(if (isBengali) nh.name else nh.nameEn, color = Color.White, fontSize = 12.sp) },
                                onClick = {
                                    selectedNeighborhoodIndex = idx
                                    showNeighborhoodMenu = false
                                    lat = nh.lat
                                    lng = nh.lon
                                    manualAddressText = "সিলেট সিটি কর্পোরেশন, ${activeWard.ward}, ${nh.name}"
                                }
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
                    TextButton(onClick = onDismiss) {
                        Text(if (isBengali) "বাতিল" else "Cancel", color = DarkTextSecondary)
                    }
                    Spacer(modifier = Modifier.width(8.dp))
                    Button(
                        colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed, contentColor = DarkAccentText),
                        onClick = {
                            val activeWardItem = sylhetAreas[selectedWardIndex]
                            val activeNhItem = activeWardItem.neighborhoods.getOrElse(selectedNeighborhoodIndex) { activeWardItem.neighborhoods[0] }
                            val finalAddress = if (manualAddressText.trim().isNotEmpty()) {
                                manualAddressText.trim()
                            } else {
                                "সিলেট সিটি কর্পোরেশন, ${activeWardItem.ward}, ${activeNhItem.name}"
                            }
                            val finalLat = if (lat != 0.0) lat else activeNhItem.lat
                            val finalLon = if (lng != 0.0) lng else activeNhItem.lon
                            viewModel.updateCustomerLocation(
                                addr = finalAddress,
                                ward = activeWardItem.ward,
                                neighborhood = activeNhItem.name,
                                lat = finalLat,
                                lon = finalLon
                            )
                            android.widget.Toast.makeText(
                                context,
                                if (isBengali) "লোকেশন সফলভাবে সেটিংসে সংরক্ষণ করা হয়েছে!" else "Location successfully saved in Settings!",
                                android.widget.Toast.LENGTH_SHORT
                            ).show()
                            onDismiss()
                        }
                    ) {
                        Text(if (isBengali) "সেটিংসে সেভ করুন" else "Save in Settings", color = DarkAccentText)
                    }
                }
            }
        }
    }
}

@Composable
fun NotificationsScreen(
    viewModel: PharmacyViewModel, 
    isBengali: Boolean,
    onBack: (() -> Unit)? = null
) {
    val notifications by viewModel.notifications.collectAsState()
    val context = androidx.compose.ui.platform.LocalContext.current

    val currentUser by viewModel.currentUser.collectAsState()
    var showStaffRequestDialog by remember { mutableStateOf(false) }
    var showStaffDisconnectWarning by remember { mutableStateOf(false) }
    var staffReqPharmacyName by remember { mutableStateOf("") }
    var staffReqOwnerName by remember { mutableStateOf("") }
    var staffReqSecurityCode by remember { mutableStateOf("") }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
    ) {
        // Header Row
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                if (onBack != null) {
                    IconButton(onClick = onBack) {
                        Icon(
                            imageVector = Icons.Default.ArrowBack,
                            contentDescription = "Back",
                            tint = Color.White
                        )
                    }
                    Spacer(modifier = Modifier.width(4.dp))
                }
                Text(
                    text = if (isBengali) "নোটিফিকেশন সমূহ" else "All Notifications",
                    color = DarkTextPrimary,
                    fontWeight = FontWeight.Bold,
                    fontSize = 18.sp
                )
            }

            if (notifications.any { !it.isRead }) {
                TextButton(
                    onClick = {
                        notifications.forEach { notif ->
                            if (!notif.isRead) {
                                viewModel.markNotificationAsRead(notif)
                            }
                        }
                        android.widget.Toast.makeText(context, if (isBengali) "সব নোটিফিকেশন পড়া হয়েছে!" else "All notifications marked as read!", android.widget.Toast.LENGTH_SHORT).show()
                    }
                ) {
                    Text(
                        text = if (isBengali) "সব পড়া হয়েছে" else "Mark all read",
                        color = DarkAccentGold,
                        fontSize = 13.sp,
                        fontWeight = FontWeight.SemiBold
                    )
                }
            }
        }

        Spacer(modifier = Modifier.height(12.dp))

        // STAFF PHARMACY CONNECTION PANEL
        if (currentUser.role == "staff") {
            val permissionRequests by viewModel.permissionRequests.collectAsState()
            val myRequests = permissionRequests.filter { it.staffUsername == currentUser.username }

            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = DarkSurface),
                border = BorderStroke(
                    width = 1.dp,
                    color = if (currentUser.linkedAdminUsername.isNotEmpty()) SuccessColor.copy(alpha = 0.4f) else DarkAccentGold.copy(alpha = 0.4f)
                ),
                shape = RoundedCornerShape(16.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Icon(
                            imageVector = if (currentUser.linkedAdminUsername.isNotEmpty()) Icons.Filled.CheckCircle else Icons.Filled.Info,
                            contentDescription = "Connection Status",
                            tint = if (currentUser.linkedAdminUsername.isNotEmpty()) SuccessColor else DarkAccentGold,
                            modifier = Modifier.size(22.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = if (isBengali) "ফার্মেসী সংযোগ স্ট্যাটাস" else "Pharmacy Connection Status",
                            color = DarkTextPrimary,
                            fontWeight = FontWeight.Bold,
                            fontSize = 15.sp
                        )
                    }
                    Spacer(modifier = Modifier.height(10.dp))

                    if (currentUser.linkedAdminUsername.isNotEmpty()) {
                        Text(
                            text = if (isBengali) {
                                "আপনি সফলভাবে **${currentUser.pharmacyName}** (মালিক: ${currentUser.ownerName}) এর সাথে যুক্ত আছেন।"
                            } else {
                                "You are successfully linked to **${currentUser.pharmacyName}** (Owner: ${currentUser.ownerName})."
                            },
                            color = DarkTextPrimary,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Medium
                        )
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            text = if (isBengali) {
                                "এখন আপনি এই ফার্মেসীর স্টক, বিক্রয় ও রিপোর্ট পুরোপুরি নিয়ন্ত্রণ করতে পারবেন।"
                            } else {
                                "You can now fully manage stock, sales, and reports for this pharmacy."
                            },
                            color = DarkTextSecondary,
                            fontSize = 12.sp
                        )
                    } else {
                        Text(
                            text = if (isBengali) {
                                "আপনি বর্তমানে কোনো মার্চেন্ট ফার্মেসীর সাথে যুক্ত নন। ফার্মেসীর তথ্য দেখতে ও পরিচালনা করতে অনুগ্রহ করে মার্চেন্টের অনুমতি চেয়ে আবেদন করুন।"
                            } else {
                                "You are not currently linked to any merchant pharmacy. Please apply for permission to gain access and manage pharmacy data."
                            },
                            color = DarkTextSecondary,
                            fontSize = 13.sp
                        )
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    if (currentUser.linkedAdminUsername.isEmpty()) {
                        Button(
                            onClick = { showStaffRequestDialog = true },
                            colors = ButtonDefaults.buttonColors(
                                containerColor = DarkAccentRed,
                                contentColor = DarkAccentText
                            ),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Send,
                                contentDescription = null,
                                modifier = Modifier.size(16.dp)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(
                                text = if (isBengali) "অনুমতির জন্য আবেদন করুন" else "Apply for Access",
                                fontWeight = FontWeight.Bold,
                                fontSize = 13.sp
                            )
                        }
                    } else {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(SuccessColor.copy(alpha = 0.1f), RoundedCornerShape(8.dp))
                                .border(1.dp, SuccessColor.copy(alpha = 0.3f), RoundedCornerShape(8.dp))
                                .padding(12.dp)
                        ) {
                            Column {
                                Text(
                                    text = if (isBengali) {
                                        "🔒 আপনি ইতিমধ্যে একটি সক্রিয় সংযোগে আছেন। অন্য ফার্মেসীর সাথে যুক্ত হতে পারবেন না।"
                                    } else {
                                        "🔒 You are currently in an active connection. You cannot link with another pharmacy simultaneously."
                                    },
                                    color = Color(0xFF81C784),
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.SemiBold
                                )
                                Spacer(modifier = Modifier.height(10.dp))
                                Button(
                                    onClick = { showStaffDisconnectWarning = true },
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = DarkAccentRed.copy(alpha = 0.15f),
                                        contentColor = DarkAccentRed
                                    ),
                                    shape = RoundedCornerShape(8.dp),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Close,
                                        contentDescription = "Exit Pharmacy",
                                        modifier = Modifier.size(16.dp)
                                    )
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text(
                                        text = if (isBengali) "বর্তমান ফার্মেসী থেকে বাহির হোন" else "Exit Current Pharmacy",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold
                                    )
                                }
                            }
                        }
                    }

                    // WARNING DIALOG FOR STAFF TO DISCONNECT
                    if (showStaffDisconnectWarning) {
                        AlertDialog(
                            onDismissRequest = { showStaffDisconnectWarning = false },
                            title = {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(
                                        imageVector = Icons.Default.Warning,
                                        contentDescription = "Warning",
                                        tint = DarkAccentRed,
                                        modifier = Modifier.size(24.dp)
                                    )
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text(
                                        text = if (isBengali) "সংযোগ বিচ্ছিন্ন করার সতর্কতা!" else "Disconnect Connection Warning!",
                                        color = DarkTextPrimary,
                                        fontSize = 18.sp,
                                        fontWeight = FontWeight.Bold
                                    )
                                }
                            },
                            text = {
                                Text(
                                    text = if (isBengali) {
                                        "আপনি কি নিশ্চিত যে আপনি এই ফার্মেসী থেকে বের হতে চান?\n\n⚠️ এর ফলে আপনি আর এই ফার্মেসীর স্টক, বিক্রয় বা রিপোর্ট পরিচালনা করতে পারবেন না।"
                                    } else {
                                        "Are you sure you want to disconnect from this pharmacy?\n\n⚠️ As a result, you will lose all access to its stock, sales, and reports."
                                    },
                                    color = DarkTextSecondary,
                                    fontSize = 14.sp
                                )
                            },
                            confirmButton = {
                                Button(
                                    onClick = {
                                        viewModel.disconnectStaff(currentUser.username)
                                        showStaffDisconnectWarning = false
                                    },
                                    colors = ButtonDefaults.buttonColors(containerColor = DarkAccentRed, contentColor = Color.White),
                                    shape = RoundedCornerShape(8.dp)
                                ) {
                                    Text(if (isBengali) "হ্যাঁ, বের হয়ে যান" else "Confirm Exit", fontWeight = FontWeight.Bold)
                                }
                            },
                            dismissButton = {
                                TextButton(
                                    onClick = { showStaffDisconnectWarning = false }
                                ) {
                                    Text(if (isBengali) "বাতিল" else "Cancel", color = DarkTextSecondary)
                                }
                            },
                            containerColor = DarkSurface,
                            shape = RoundedCornerShape(16.dp)
                        )
                    }

                    if (myRequests.isNotEmpty()) {
                        Spacer(modifier = Modifier.height(16.dp))
                        Text(
                            text = if (isBengali) "আপনার আবেদনসমূহ:" else "Your Requests:",
                            color = DarkTextPrimary,
                            fontWeight = FontWeight.Bold,
                            fontSize = 13.sp
                        )
                        Spacer(modifier = Modifier.height(6.dp))

                        myRequests.sortedByDescending { it.timestamp }.take(3).forEach { req ->
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 4.dp)
                                    .background(DarkBg, RoundedCornerShape(8.dp))
                                    .border(1.dp, Color.White.copy(alpha = 0.05f), RoundedCornerShape(8.dp))
                                    .padding(8.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(modifier = Modifier.weight(0.7f)) {
                                    Text(
                                        text = req.pharmacyName,
                                        color = DarkTextPrimary,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 12.sp
                                    )
                                    Text(
                                        text = "${if (isBengali) "মালিক:" else "Owner:"} ${req.ownerName}",
                                        color = DarkTextSecondary,
                                        fontSize = 11.sp
                                    )
                                }
                                val (statusText, statusColor) = when (req.status) {
                                    "Pending" -> Pair(if (isBengali) "অপেক্ষমাণ" else "Pending", DarkAccentGold)
                                    "Approved" -> Pair(if (isBengali) "অনুমোদিত" else "Approved", SuccessColor)
                                    else -> Pair(if (isBengali) "প্রত্যাখ্যাত" else "Rejected", DarkAccentRed)
                                }
                                Text(
                                    text = statusText,
                                    color = statusColor,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 11.sp,
                                    modifier = Modifier
                                        .background(statusColor.copy(alpha = 0.15f), RoundedCornerShape(4.dp))
                                        .padding(horizontal = 6.dp, vertical = 2.dp)
                                )
                            }
                        }
                    }
                }
            }
            Spacer(modifier = Modifier.height(16.dp))
        }

        if (notifications.isEmpty()) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .weight(1f),
                contentAlignment = Alignment.Center
            ) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    Icon(
                        imageVector = Icons.Outlined.Notifications,
                        contentDescription = "No notifications",
                        tint = DarkTextSecondary.copy(alpha = 0.4f),
                        modifier = Modifier.size(64.dp)
                    )
                    Spacer(modifier = Modifier.height(12.dp))
                    Text(
                        text = if (isBengali) "কোনো নোটিফিকেশন পাওয়া যায়নি" else "No notifications yet",
                        color = DarkTextSecondary,
                        fontSize = 14.sp
                    )
                }
            }
        } else {
            LazyColumn(
                modifier = Modifier
                    .fillMaxSize()
                    .weight(1f),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                items(notifications.size) { index ->
                    val notif = notifications[index]
                    val isUnread = !notif.isRead

                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable {
                                if (isUnread) {
                                    viewModel.markNotificationAsRead(notif)
                                }
                            },
                        colors = CardDefaults.cardColors(
                            containerColor = if (isUnread) DarkSurface.copy(alpha = 0.85f) else DarkSurface.copy(alpha = 0.5f)
                        ),
                        border = BorderStroke(
                            width = 1.dp,
                            color = if (isUnread) DarkAccentGold.copy(alpha = 0.35f) else Color.White.copy(alpha = 0.05f)
                        ),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(14.dp),
                            verticalAlignment = Alignment.Top
                        ) {
                            // Status Dot & Bell Icon
                            Box(modifier = Modifier.padding(top = 2.dp)) {
                                Icon(
                                    imageVector = if (isUnread) Icons.Filled.NotificationsActive else Icons.Outlined.Notifications,
                                    contentDescription = "Notification Bell",
                                    tint = if (isUnread) DarkAccentGold else DarkTextSecondary,
                                    modifier = Modifier.size(22.dp)
                                )
                                if (isUnread) {
                                    Box(
                                        modifier = Modifier
                                            .align(Alignment.TopEnd)
                                            .offset(x = 2.dp, y = (-2).dp)
                                            .size(8.dp)
                                            .background(DarkAccentRed, androidx.compose.foundation.shape.CircleShape)
                                    )
                                }
                            }

                            Spacer(modifier = Modifier.width(12.dp))

                            // Details
                            Column(modifier = Modifier.weight(1f)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = if (isBengali) notif.titleBn else notif.titleEn,
                                        color = if (isUnread) DarkTextPrimary else DarkTextSecondary,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 14.sp,
                                        maxLines = 1,
                                        overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                                    )
                                    
                                    val timeText = SimpleDateFormat("hh:mm a", Locale.getDefault()).format(Date(notif.timestamp))
                                    Text(
                                        text = timeText,
                                        color = DarkTextSecondary.copy(alpha = 0.7f),
                                        fontSize = 11.sp
                                    )
                                }

                                Spacer(modifier = Modifier.height(4.dp))

                                Text(
                                    text = if (isBengali) notif.messageBn else notif.messageEn,
                                    color = if (isUnread) DarkTextPrimary.copy(alpha = 0.9f) else DarkTextSecondary.copy(alpha = 0.8f),
                                    fontSize = 13.sp,
                                    lineHeight = 17.sp
                                )

                                Spacer(modifier = Modifier.height(6.dp))

                                val dateText = SimpleDateFormat("dd MMM yyyy", Locale.getDefault()).format(Date(notif.timestamp))
                                Text(
                                    text = dateText,
                                    color = DarkTextSecondary.copy(alpha = 0.5f),
                                    fontSize = 10.sp
                                )
                            }
                        }
                    }
                }
            }
        }
    }

    if (showStaffRequestDialog) {
        AlertDialog(
            onDismissRequest = { showStaffRequestDialog = false },
            title = {
                Text(
                    text = if (isBengali) "ফার্মেসী নিয়ন্ত্রণ অনুমতি অনুরোধ" else "Request Pharmacy Control Access",
                    color = DarkTextPrimary,
                    fontSize = 18.sp,
                    fontWeight = FontWeight.Bold
                )
            },
            text = {
                Column(modifier = Modifier.fillMaxWidth()) {
                    Text(
                        text = if (isBengali) "যে ফার্মেসীটি আপনি পরিচালনা করতে চান তার সঠিক নাম, মালিকের নাম ও মার্চেন্টের সিকিউরিটি কোড দিন।" else "Provide the exact Pharmacy Name, Owner Name, and Merchant's Security Code for the pharmacy you wish to manage.",
                        color = DarkTextSecondary,
                        fontSize = 12.sp,
                        modifier = Modifier.padding(bottom = 12.dp)
                    )
                    OutlinedTextField(
                        value = staffReqPharmacyName,
                        onValueChange = { staffReqPharmacyName = it },
                        label = { Text(if (isBengali) "ফার্মেসীর নাম" else "Pharmacy Name") },
                        leadingIcon = { Icon(Icons.Default.LocalPharmacy, contentDescription = null, tint = DarkAccentRed) },
                        textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = DarkAccentRed,
                            unfocusedBorderColor = SleekBorderColor,
                            focusedLabelColor = DarkAccentRed,
                            unfocusedLabelColor = DarkTextSecondary
                        )
                    )
                    OutlinedTextField(
                        value = staffReqOwnerName,
                        onValueChange = { staffReqOwnerName = it },
                        label = { Text(if (isBengali) "মালিকের নাম" else "Owner Name") },
                        leadingIcon = { Icon(Icons.Default.Person, contentDescription = null, tint = DarkAccentRed) },
                        textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = DarkAccentRed,
                            unfocusedBorderColor = SleekBorderColor,
                            focusedLabelColor = DarkAccentRed,
                            unfocusedLabelColor = DarkTextSecondary
                        )
                    )
                    OutlinedTextField(
                        value = staffReqSecurityCode,
                        onValueChange = { staffReqSecurityCode = it },
                        label = { Text(if (isBengali) "মার্চেন্টের সিকিউরিটি কোড" else "Merchant Security Code") },
                        placeholder = { Text(if (isBengali) "যেমন: #ROPH-XXXX" else "e.g. #ROPH-XXXX", color = DarkTextSecondary.copy(alpha = 0.5f)) },
                        leadingIcon = { Icon(Icons.Default.VpnKey, contentDescription = null, tint = DarkAccentGold) },
                        textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary),
                        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = DarkAccentGold,
                            unfocusedBorderColor = SleekBorderColor,
                            focusedLabelColor = DarkAccentGold,
                            unfocusedLabelColor = DarkTextSecondary
                        )
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        if (staffReqPharmacyName.isNotEmpty() && staffReqOwnerName.isNotEmpty() && staffReqSecurityCode.isNotEmpty()) {
                            viewModel.sendPermissionRequest(
                                staffReqPharmacyName.trim(),
                                staffReqOwnerName.trim(),
                                staffReqSecurityCode.trim()
                            ) { success, msg ->
                                android.widget.Toast.makeText(context, msg, android.widget.Toast.LENGTH_LONG).show()
                            }
                            showStaffRequestDialog = false
                            staffReqPharmacyName = ""
                            staffReqOwnerName = ""
                            staffReqSecurityCode = ""
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = SuccessColor, contentColor = Color.White),
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text(if (isBengali) "অনুরোধ পাঠান" else "Send Request", fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                TextButton(onClick = { showStaffRequestDialog = false }) {
                    Text(if (isBengali) "বাতিল" else "Cancel", color = DarkTextSecondary)
                }
            },
            containerColor = DarkSurface,
            shape = RoundedCornerShape(16.dp)
        )
    }
}

@Composable
fun CompactIntegerField(
    label: String,
    value: Int,
    onValueChange: (Int) -> Unit,
    modifier: Modifier = Modifier
) {
    var textValue by remember(value) { mutableStateOf(if (value == 0) "" else value.toString()) }
    androidx.compose.material3.OutlinedTextField(
        value = textValue,
        onValueChange = { newValue ->
            textValue = newValue
            newValue.toIntOrNull()?.let { onValueChange(it) } ?: if (newValue.isEmpty()) onValueChange(0) else Unit
        },
        label = { Text(label, fontSize = 10.sp) },
        singleLine = true,
        textStyle = androidx.compose.ui.text.TextStyle(fontSize = 12.sp, color = DarkTextPrimary),
        colors = androidx.compose.material3.OutlinedTextFieldDefaults.colors(
            focusedBorderColor = DarkAccentGold,
            unfocusedBorderColor = Color.White.copy(alpha = 0.15f),
            focusedLabelColor = DarkAccentGold,
            unfocusedLabelColor = DarkTextSecondary
        ),
        modifier = modifier.height(48.dp),
        keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
            keyboardType = androidx.compose.ui.text.input.KeyboardType.Number
        )
    )
}

@Composable
fun CompactDoubleField(
    label: String,
    value: Double?,
    onValueChange: (Double?) -> Unit,
    modifier: Modifier = Modifier
) {
    var textValue by remember(value) { mutableStateOf(value?.let { if (it == 0.0) "" else it.toString() } ?: "") }
    androidx.compose.material3.OutlinedTextField(
        value = textValue,
        onValueChange = { newValue ->
            textValue = newValue
            onValueChange(newValue.toDoubleOrNull())
        },
        label = { Text(label, fontSize = 10.sp) },
        singleLine = true,
        textStyle = androidx.compose.ui.text.TextStyle(fontSize = 12.sp, color = DarkTextPrimary),
        colors = androidx.compose.material3.OutlinedTextFieldDefaults.colors(
            focusedBorderColor = DarkAccentGold,
            unfocusedBorderColor = Color.White.copy(alpha = 0.15f),
            focusedLabelColor = DarkAccentGold,
            unfocusedLabelColor = DarkTextSecondary
        ),
        modifier = modifier.height(48.dp),
        keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
            keyboardType = androidx.compose.ui.text.input.KeyboardType.Decimal
        )
    )
}

sealed class ActivityLog(val timestamp: Long) {
    class Sale(val bill: Bill) : ActivityLog(bill.timestamp)
    class StockIn(val pending: PendingStockIn) : ActivityLog(pending.timestamp)
    class NewMed(val pending: PendingMedicine) : ActivityLog(pending.timestamp)
}

fun isToday(timestamp: Long): Boolean {
    val target = java.util.Calendar.getInstance().apply { timeInMillis = timestamp }
    val today = java.util.Calendar.getInstance()
    return target.get(java.util.Calendar.YEAR) == today.get(java.util.Calendar.YEAR) &&
           target.get(java.util.Calendar.DAY_OF_YEAR) == today.get(java.util.Calendar.DAY_OF_YEAR)
}

fun formatDateTime(timestamp: Long): String {
    val sdf = java.text.SimpleDateFormat("MMM dd, hh:mm a", java.util.Locale.getDefault())
    return sdf.format(java.util.Date(timestamp))
}

@Composable
fun ServerConfigDialog(
    viewModel: PharmacyViewModel,
    isBengali: Boolean,
    onDismiss: () -> Unit
) {
    val context = LocalContext.current
    val isConnected by viewModel.isOnlineSyncConnected.collectAsState()
    val syncMessage by viewModel.firebaseSyncMessage.collectAsState()
    val isTesting by viewModel.isTestingConnection.collectAsState()
    val customDbUrl by viewModel.customFirebaseDatabaseUrl.collectAsState()
    val customApiKey by viewModel.customFirebaseApiKey.collectAsState()
    val customProjectId by viewModel.customFirebaseProjectId.collectAsState()

    var inputUrl by remember { mutableStateOf(if (customDbUrl.isNotBlank()) customDbUrl else viewModel.getEffectiveDatabaseUrl()) }
    var inputApiKey by remember { mutableStateOf(customApiKey) }
    var inputProjectId by remember { mutableStateOf(customProjectId) }
    var statusText by remember { mutableStateOf("") }
    var isSuccess by remember { mutableStateOf<Boolean?>(null) }

    Dialog(onDismissRequest = onDismiss) {
        Card(
            colors = CardDefaults.cardColors(containerColor = DarkSurface),
            border = BorderStroke(1.5.dp, if (isConnected) Color(0xFF00E676) else DarkAccentGold),
            shape = RoundedCornerShape(20.dp),
            modifier = Modifier
                .fillMaxWidth()
                .padding(4.dp)
        ) {
            Column(
                modifier = Modifier
                    .padding(20.dp)
                    .verticalScroll(rememberScrollState()),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                // Header
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Box(
                            modifier = Modifier
                                .size(36.dp)
                                .background(DarkAccentGold.copy(alpha = 0.2f), RoundedCornerShape(10.dp)),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Default.Dns,
                                contentDescription = null,
                                tint = DarkAccentGold,
                                modifier = Modifier.size(20.dp)
                            )
                        }
                        Spacer(modifier = Modifier.width(10.dp))
                        Text(
                            text = if (isBengali) "সার্ভার সেটিংস / এড" else "Server Settings",
                            color = DarkTextPrimary,
                            fontSize = 17.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                    IconButton(onClick = onDismiss, modifier = Modifier.size(28.dp)) {
                        Icon(Icons.Default.Close, contentDescription = "Close", tint = DarkTextSecondary)
                    }
                }

                Spacer(modifier = Modifier.height(14.dp))

                // Connection Status Card
                Card(
                    colors = CardDefaults.cardColors(
                        containerColor = if (isConnected) Color(0xFF00E676).copy(alpha = 0.12f) else DarkAccentRed.copy(alpha = 0.12f)
                    ),
                    border = BorderStroke(
                        1.dp,
                        if (isConnected) Color(0xFF00E676).copy(alpha = 0.4f) else DarkAccentRed.copy(alpha = 0.4f)
                    ),
                    shape = RoundedCornerShape(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Row(
                        modifier = Modifier.padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(10.dp)
                                .background(if (isConnected) Color(0xFF00E676) else DarkAccentRed, CircleShape)
                        )
                        Spacer(modifier = Modifier.width(10.dp))
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = if (isConnected) {
                                    if (isBengali) "সার্ভার সংযুক্ত ও সক্রিয় (Online)" else "Server Connected & Online"
                                } else {
                                    if (isBengali) "সার্ভার এর সাথে কানেক্টেড না (Offline)" else "Not Connected to Server (Offline)"
                                },
                                color = if (isConnected) Color(0xFF00E676) else DarkAccentRed,
                                fontWeight = FontWeight.Bold,
                                fontSize = 13.sp
                            )
                            Text(
                                text = syncMessage,
                                color = DarkTextSecondary,
                                fontSize = 11.5.sp
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(14.dp))

                // Instructions Card
                Card(
                    colors = CardDefaults.cardColors(containerColor = DarkBg),
                    border = BorderStroke(1.dp, SleekBorderColor),
                    shape = RoundedCornerShape(10.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(modifier = Modifier.padding(12.dp)) {
                        Text(
                            text = if (isBengali) "💡 নতুন ক্লাউড সার্ভার এড করার নিয়ম:" else "💡 How to add your Firebase server:",
                            color = DarkAccentGold,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold
                        )
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = if (isBengali)
                                "১. আপনার Firebase Console (firebase.google.com)-এ যান।\n২. 'Realtime Database' তৈরি করুন এবং ডাটাবেজ URL নিচে দিন।\n৩. Rules ট্যাবে \".read\": true ও \".write\": true দিয়ে Publish করুন।"
                            else
                                "1. Open your Firebase Console (firebase.google.com)\n2. Create 'Realtime Database' & paste the Database URL below.\n3. In Rules tab, set \".read\": true and \".write\": true, then Publish.",
                            color = DarkTextSecondary,
                            fontSize = 11.sp,
                            lineHeight = 16.sp
                        )
                    }
                }

                Spacer(modifier = Modifier.height(14.dp))

                // Database URL input
                OutlinedTextField(
                    value = inputUrl,
                    onValueChange = {
                        inputUrl = it
                        statusText = ""
                        isSuccess = null
                    },
                    label = { Text(if (isBengali) "সার্ভার ডাটাবেজ URL (Database URL) *" else "Database URL *") },
                    placeholder = { Text("https://your-db.asia-southeast1.firebasedatabase.app", fontSize = 11.sp, color = DarkTextSecondary.copy(alpha = 0.5f)) },
                    textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary, fontSize = 12.5.sp),
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth(),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = DarkAccentGold,
                        unfocusedBorderColor = SleekBorderColor,
                        focusedLabelColor = DarkAccentGold,
                        unfocusedLabelColor = DarkTextSecondary
                    ),
                    shape = RoundedCornerShape(12.dp)
                )

                Spacer(modifier = Modifier.height(10.dp))

                // API Key input (Optional)
                OutlinedTextField(
                    value = inputApiKey,
                    onValueChange = {
                        inputApiKey = it
                        statusText = ""
                        isSuccess = null
                    },
                    label = { Text(if (isBengali) "Firebase API Key (ঐচ্ছিক / Optional)" else "API Key (Optional)") },
                    placeholder = { Text("AIzaSy...", fontSize = 11.sp, color = DarkTextSecondary.copy(alpha = 0.5f)) },
                    textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary, fontSize = 12.5.sp),
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth(),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = DarkAccentGold,
                        unfocusedBorderColor = SleekBorderColor,
                        focusedLabelColor = DarkAccentGold,
                        unfocusedLabelColor = DarkTextSecondary
                    ),
                    shape = RoundedCornerShape(12.dp)
                )

                Spacer(modifier = Modifier.height(10.dp))

                // Project ID input (Optional)
                OutlinedTextField(
                    value = inputProjectId,
                    onValueChange = {
                        inputProjectId = it
                        statusText = ""
                        isSuccess = null
                    },
                    label = { Text(if (isBengali) "Firebase Project ID (ঐচ্ছিক / Optional)" else "Project ID (Optional)") },
                    placeholder = { Text("my-pharmacy-app", fontSize = 11.sp, color = DarkTextSecondary.copy(alpha = 0.5f)) },
                    textStyle = LocalTextStyle.current.copy(color = DarkTextPrimary, fontSize = 12.5.sp),
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth(),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = DarkAccentGold,
                        unfocusedBorderColor = SleekBorderColor,
                        focusedLabelColor = DarkAccentGold,
                        unfocusedLabelColor = DarkTextSecondary
                    ),
                    shape = RoundedCornerShape(12.dp)
                )

                if (statusText.isNotEmpty()) {
                    Spacer(modifier = Modifier.height(10.dp))
                    Text(
                        text = statusText,
                        color = if (isSuccess == true) Color(0xFF00E676) else DarkAccentRed,
                        fontSize = 12.sp,
                        fontWeight = FontWeight.SemiBold,
                        textAlign = TextAlign.Center
                    )
                }

                Spacer(modifier = Modifier.height(16.dp))

                // Save & Connect Button
                Button(
                    onClick = {
                        if (inputUrl.trim().isEmpty()) {
                            statusText = if (isBengali) "দয়া করে সার্ভার ডাটাবেজ URL লিখুন!" else "Please enter Database URL!"
                            isSuccess = false
                        } else {
                            viewModel.setCustomServerConfig(
                                databaseUrl = inputUrl.trim(),
                                apiKey = inputApiKey.trim(),
                                projectId = inputProjectId.trim()
                            ) { ok, msg ->
                                isSuccess = ok
                                statusText = msg
                                if (ok) {
                                    android.widget.Toast.makeText(context, msg, android.widget.Toast.LENGTH_LONG).show()
                                }
                            }
                        }
                    },
                    enabled = !isTesting,
                    colors = ButtonDefaults.buttonColors(containerColor = DarkAccentGold),
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(46.dp),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    if (isTesting) {
                        CircularProgressIndicator(color = Color.Black, modifier = Modifier.size(20.dp), strokeWidth = 2.dp)
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = if (isBengali) "কানেক্ট করা হচ্ছে..." else "Connecting...",
                            color = Color.Black,
                            fontWeight = FontWeight.Bold
                        )
                    } else {
                        Icon(Icons.Default.CloudSync, contentDescription = null, tint = Color.Black, modifier = Modifier.size(18.dp))
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = if (isBengali) "সার্ভার সেভ ও কানেক্ট করুন" else "Save & Connect Server",
                            color = Color.Black,
                            fontWeight = FontWeight.Bold,
                            fontSize = 13.5.sp
                        )
                    }
                }

                Spacer(modifier = Modifier.height(10.dp))

                // Reconnect & Reset Row
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    OutlinedButton(
                        onClick = {
                            viewModel.reconnectFirebase { ok, msg ->
                                isSuccess = ok
                                statusText = msg
                            }
                        },
                        enabled = !isTesting,
                        modifier = Modifier
                            .weight(1f)
                            .height(40.dp),
                        shape = RoundedCornerShape(10.dp),
                        border = BorderStroke(1.dp, SleekBorderColor)
                    ) {
                        Icon(Icons.Default.Refresh, contentDescription = null, tint = DarkTextPrimary, modifier = Modifier.size(15.dp))
                        Spacer(modifier = Modifier.width(4.dp))
                        Text(
                            text = if (isBengali) "টেস্ট ও রিফ্রেশ" else "Test Ping",
                            color = DarkTextPrimary,
                            fontSize = 11.sp
                        )
                    }

                    OutlinedButton(
                        onClick = {
                            viewModel.resetDefaultServer { ok, msg ->
                                inputUrl = viewModel.getEffectiveDatabaseUrl()
                                inputApiKey = ""
                                inputProjectId = ""
                                isSuccess = ok
                                statusText = if (isBengali) "ডিফল্ট সার্ভার রিসেট হয়েছে" else "Reset to default server"
                            }
                        },
                        enabled = !isTesting,
                        modifier = Modifier
                            .weight(1f)
                            .height(40.dp),
                        shape = RoundedCornerShape(10.dp),
                        border = BorderStroke(1.dp, SleekBorderColor)
                    ) {
                        Text(
                            text = if (isBengali) "ডিফল্ট রিসেট" else "Reset Default",
                            color = DarkTextSecondary,
                            fontSize = 11.sp
                        )
                    }
                }
            }
        }
    }
}



